    good.text(14,7,"╺╋╸  ");model.messages[0].label="╺╋╸";
    auto errors=validate(good,model);ASSERT_TRUE(errors.empty())<<(errors.empty()?"":errors.front());
    for(int y=21;y<36;++y) {good.put(8,y,"┃");good.put(10,y,"┃");}
    good.put(7,21," ");good.put(9,21," ");good.put(11,21," ");
    good.put(7,27," ");good.put(9,27," ");
    model.order.erase(model.order.begin()+7);model.order.erase(model.order.begin()+5);
    errors=validate(good,model);ASSERT_TRUE(errors.empty())<<(errors.empty()?"":errors.front());
    auto bad=good;bad.put(10,35," ");EXPECT_FALSE(validate(bad,model).empty());
    bad=good;bad.text(7,35,"╺╋━┻╸");EXPECT_FALSE(validate(bad,model).empty());
