TEST(MermaidSequenceOracle, PreservesRepeatedIdenticalOrderedNotes) {
    const auto first=self_note();Grid good{24,27,std::vector<std::string>(24*27," ")};
    for(int y=0;y<first.height;++y) for(int x=0;x<first.width;++x) good.put(x,y,first.at(x,y));
    for(int y=19;y<27;++y) good.put(3,y,"│");
    for(int y=11;y<=14;++y) for(int x=0;x<15;++x) good.put(x,y+8,first.at(x,y));
    auto expected=self_model();expected.notes.push_back(expected.notes.front());
    ASSERT_TRUE(validate(good,expected).empty());
    auto bad=good;bad.put(0,22," ");EXPECT_FALSE(validate(bad,expected).empty());
    auto wrong=expected;wrong.notes.pop_back();EXPECT_FALSE(validate(good,wrong).empty());
    bad=good;bad.text(1,20,"Note line X");EXPECT_FALSE(validate(bad,expected).empty());
}
TEST(MermaidSequenceOracle, RejectsResourceExhaustionAndExtraMessages) {
    const auto good=ordinary();EXPECT_FALSE(validate(good,ordinary_model(),10).empty());
    auto bad=good;bad.put(23,12,"▶");EXPECT_FALSE(validate(bad,ordinary_model()).empty());
    auto model=ordinary_model();model.messages.resize(129);EXPECT_FALSE(validate(good,model).empty());
    bad=good;bad.cells.pop_back();EXPECT_FALSE(validate(bad,ordinary_model()).empty());
    model=ordinary_model();model.actors[1].id="a";EXPECT_FALSE(validate(good,model).empty());
    model=ordinary_model();model.messages[0].to=-1;EXPECT_FALSE(validate(good,model).empty());
    model=self_model();model.notes[0].position="unknown";EXPECT_FALSE(validate(self_note(),model).empty());
}
TEST(MermaidSequenceOracle, ChecksAllArrowKindsAndUnheadedEndpointPairs) {
    for(const auto kind:{Arrow::Unheaded,Arrow::Async,Arrow::Cross,Arrow::Both}) {
        auto good=ordinary();auto m=ordinary_model();
        m.messages[0].arrow=kind;m.messages[1].arrow=kind;
        if(kind==Arrow::Unheaded) {good.put(23,6,"┤");good.put(3,10,"├");}
        if(kind==Arrow::Async) {good.put(23,6,"›");good.put(3,10,"‹");}
        if(kind==Arrow::Cross) {good.put(23,6,"×");good.put(3,10,"×");}
        if(kind==Arrow::Both) {good.put(3,6,"◀");good.put(23,10,"▶");}
        const auto errors=validate(good,m);ASSERT_TRUE(errors.empty())<<static_cast<int>(kind)<<": "<<(errors.empty()?"":errors.front());
        auto bad=good;bad.put(23,6,"▶");
        if(kind!=Arrow::Both) EXPECT_FALSE(validate(bad,m).empty());
        bad=good;bad.put(3,6," ");EXPECT_FALSE(validate(bad,m).empty());
        bad=good;bad.put(10,10,"─");EXPECT_FALSE(validate(bad,m).empty());
        if(kind==Arrow::Unheaded) {
            std::swap(m.messages[0].from,m.messages[0].to);
            EXPECT_TRUE(validate(good,m).empty()); // The source pair is intentionally unordered.
            m.actors.push_back({"c","C"});m.messages[0].to=2;
            EXPECT_FALSE(validate(good,m).empty());
        }
    }
}
TEST(MermaidSequenceOracle, BindsCentralMarkersAndNumbersToTheSameRoute) {
    auto good=ordinary();auto m=ordinary_model();
    for(auto& message:m.messages) {message.central_from=true;message.central_to=true;}
    good.put(3,6,"○");good.put(23,6,"○");good.put(22,6,"▶");
    good.put(23,10,"○");good.put(3,10,"○");good.put(4,10,"◀");
    ASSERT_TRUE(validate(good,m).empty());
    auto bad=good;bad.put(22,6,"─");EXPECT_FALSE(validate(bad,m).empty());
    bad=good;bad.put(23,6,"▶");EXPECT_FALSE(validate(bad,m).empty());
    bad=good;bad.put(12,6,"○");EXPECT_FALSE(validate(bad,m).empty());
    bad=good;bad.put(22,10,"─");EXPECT_FALSE(validate(bad,m).empty());
    auto wrong=m;wrong.messages[0].central_from=false;EXPECT_FALSE(validate(good,wrong).empty());
    good=ordinary();m=ordinary_model();m.messages[0].number="1";m.messages[1].number="2";
    good.text(5,5,"1. hello");good.text(5,9,"2. reply");
    ASSERT_TRUE(validate(good,m).empty());
    bad=good;bad.text(5,5,"2. hello");EXPECT_FALSE(validate(bad,m).empty());
    bad=good;bad.text(5,9,"1. reply");EXPECT_FALSE(validate(bad,m).empty());
    wrong=m;wrong.messages[0].number.clear();EXPECT_FALSE(validate(good,wrong).empty());
}
TEST(MermaidSequenceOracle, ChecksMarkerFamiliesOnCompleteSelfReturnsAndEmptyLabels) {
    for(const auto kind:{Arrow::Unheaded,Arrow::Async,Arrow::Cross,Arrow::Both}) {
        auto good=self_note();auto m=self_model();m.messages[0].arrow=kind;
        if(kind==Arrow::Unheaded) good.put(3,8,"├");
        if(kind==Arrow::Async) good.put(3,8,"‹");
        if(kind==Arrow::Cross) good.put(3,8,"×");
        if(kind==Arrow::Both) good.put(3,6,"◀");
        const auto errors=validate(good,m);ASSERT_TRUE(errors.empty())<<static_cast<int>(kind)<<": "<<(errors.empty()?"":errors.front());
        auto bad=good;bad.put(11,7," ");EXPECT_FALSE(validate(bad,m).empty());
        bad=good;bad.put(3,8," ");EXPECT_FALSE(validate(bad,m).empty());
    }
    auto good=ordinary();auto m=ordinary_model();
    good.text(5,5,"     ");good.text(5,9,"     ");
    m.messages[0].label.clear();m.messages[1].label.clear();
    ASSERT_TRUE(validate(good,m).empty());
    auto bad=good;bad.text(5,5,"extra");EXPECT_FALSE(validate(bad,m).empty());
}
std::string input_bytes() {
    const auto path=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures/mermaid_terminal/beautiful_mermaid/cases.json";
    std::ifstream file(path,std::ios::binary);if(!file) throw std::runtime_error("Missing frozen Beautiful inventory");
    return {std::istreambuf_iterator<char>(file),std::istreambuf_iterator<char>()};
}
constexpr std::array<std::string_view,6> kIds{{
    "beautiful_mermaid_31380a33af1ae26c","beautiful_mermaid_f8d338c6759649a5","beautiful_mermaid_acdf057a8dbeaa39",
    "beautiful_mermaid_33c11505f9a11833","beautiful_mermaid_750cb234f8b27234","beautiful_mermaid_c724ac15f9a3b221"}};
std::string fenced(std::string_view source,std::string_view lang) {return "```"+std::string(lang)+"\n"+std::string(source)+"\n```\n\n"+std::string(kSentinel);}
TEST(MermaidSequenceOracle, FreezesWholeVendorAndCompleteFirstCohort) {
    const auto bytes=input_bytes();
    ASSERT_EQ(loom::utils::crypto::sha256(bytes),"4a1fab2e4235ba475f00fe9c687bce0d1cb15f7bacf470c5d287a0ba957a4293");
    const auto doc=json::parse(bytes);ASSERT_TRUE(doc.has_value());
    std::set<std::string> found;
    doc->root().get("cases").iter([&](JsonVal c){
        if(c.get_string("family")!="sequence") return;
        const auto id=c.get_string("id");EXPECT_NE(std::ranges::find(kIds,id),kIds.end());
        EXPECT_TRUE(found.insert(id).second);EXPECT_EQ(loom::utils::crypto::sha256(c.get_string("input")),c.get_string("sha256"));
    });
    EXPECT_EQ(found.size(),kIds.size());
}
TEST(MermaidSequenceSemantics, KeepsLeadingEmptyStatementAdmission) {
    const std::string canonical="sequenceDiagram\nparticipant A\nA->>A: x";
    const auto expected=capture(loom::ui::render_markdown(fenced(canonical,"mermaid")),240,40);
    for(const auto source:{";sequenceDiagram\nparticipant A\nA->>A: x",
                           ";\nsequenceDiagram\nparticipant A\nA->>A: x",
                           " ; ;\r\nsequenceDiagram;\r\nparticipant A;A->>A: x",
                           "%% comment\n ; ; sequenceDiagram ; participant A ; A->>A: x"}) {
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        EXPECT_TRUE(capture(element,240,40)==expected);
        const auto narrow=capture(element,40,40);
        const Model meaning{{{"A","A"}},{{0,0,"x",false}}, {}};
        EXPECT_TRUE(validate(narrow,meaning).empty());EXPECT_TRUE(capture(element,240,40)==expected);
    }
    const std::string malformed=";unexpected;sequenceDiagram\nparticipant A\nA->>A: x";
    EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(malformed,"mermaid")),240,40)==
                capture(loom::ui::render_markdown(fenced(malformed,"text")),240,40));
}
TEST(MermaidSequenceSemantics, KeepsIndependentNoteBoundsAndWholeSourceAdmission) {
    std::string source="sequenceDiagram\nparticipant A\nA->>A: self\n";
    Model expected{{{"A","A"}},{{0,0,"self",false}}, {}};
    for(int n=0;n<64;++n) {
        const auto text="N"+std::to_string(n);
        source+="Note over A: "+text+"\n";expected.notes.push_back({{0},text,"over",0});
    }
    const auto positive=capture(loom::ui::render_markdown(fenced(source,"mermaid")),240,1040);
    ASSERT_TRUE(validate(positive,expected).empty());
    auto preserves_source=[&](const std::string& input) {
        if (literal6_migrated_public(input)) return;
        EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(input,"mermaid")),240,1040)==
                    capture(loom::ui::render_markdown(fenced(input,"text")),240,1040));
    };
    preserves_source(source+"Note over A: N64\n");
    for(const auto invalid:{"Note over Missing: text\nunknown directive","Note over A,A: text","Note left of A,A: text","Note over A: <b>markup</b>","Note over A: text residual #quot;"})
        preserves_source("sequenceDiagram\nparticipant A\nA->>A: self\n"+std::string(invalid));
    preserves_source("sequenceDiagram\nparticipant A\nNote over A: "+std::string(257,'x'));
    preserves_source("sequenceDiagram\nparticipant A\nparticipant B\nparticipant C\nNote over A,B,C: text");
    const std::array<std::string,3> controlled{{"participant A as x<br>\t<br>y",
        "A->>A: x<br>\t<br>y","Note over A: x<br>\t<br>y"}};
    for(std::size_t n=0;n<controlled.size();++n) {
        const std::string input="sequenceDiagram\nparticipant A\nA->>A: self\n"+controlled[n];
        const std::string display="x\n\\u{0009}\ny";
        Model model{{{"A","A"}},{{0,0,"self",false}},{}};
        if(n==0) model.actors[0].label=display;
        else if(n==1) model.messages.push_back({0,0,display,false});
        else model.notes.push_back({{0},display,"over",0});
        auto element=loom::ui::render_markdown(fenced(input,"mermaid"));const auto wide=capture(element,240,1040);
        ASSERT_FALSE(wide==capture(loom::ui::render_markdown(fenced(input,"text")),240,1040));
        for(const auto& error:validate(wide,model)) ADD_FAILURE()<<error;
        const auto narrow=capture(element,40,1040),text=capture(loom::ui::render_markdown(fenced(input,"text")),40,1040);
        if(narrow!=text) for(const auto& error:validate(narrow,model)) ADD_FAILURE()<<error;
        const auto restored=capture(element,240,1040);EXPECT_TRUE(restored==wide);
        for(const auto* frame:{&wide,&narrow,&restored}) {
            bool sentinel=false;for(int y=0;y<frame->height;++y) sentinel|=frame->row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
    }
    const std::string source_case="sequenceDiagram\nparticipant A as Actor<br><br/>One\nA->>A: first<br /><br>last\nnOtE OvEr A: note<br/>two";
    const Model expected_case{{{"A","Actor\n\nOne"}},{{0,0,"first\n\nlast",false}},{{{0},"note\ntwo","over",0}}};
    ASSERT_TRUE(validate(capture(loom::ui::render_markdown(fenced(source_case,"mermaid")),240,80),expected_case).empty());
}
TEST(MermaidSequenceSemantics, DrawsSideNotesWithOrderedLabelsAndOwnedLeaders) {
    const std::string source="sequenceDiagram\nparticipant A as 中文\nparticipant B\n"
        "Note left of A: Leftabcdefghijklmnop<br>二\nA->>B: hi\n"
        "nOtE RiGhT oF A: Right\nNote left of B: Across";
    const Model expected{{{"A","中文"},{"B","B"}},{{0,1,"hi",false}},
        {{{0},"Leftabcdefghijklmnop\n二","left",-1},{{0},"Right","right",0},{{1},"Across","left",0}}};
    auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
    const auto wide=capture(element,240,120),plain=capture(loom::ui::render_markdown(fenced(source,"text")),240,120);
    ASSERT_FALSE(wide==plain);
    const auto errors=validate(wide,expected);for(const auto& error:errors) ADD_FAILURE()<<error;
    bool sentinel=false;for(int y=0;y<wide.height;++y) sentinel|=wide.row(y).find(kSentinel)!=std::string::npos;
    EXPECT_TRUE(sentinel);
    EXPECT_TRUE(capture(element,40,120)==capture(loom::ui::render_markdown(fenced(source,"text")),40,120));
    EXPECT_TRUE(capture(element,240,120)==wide);
    for(const auto malformed:{"Note left A: missing of", "Note right of A,B: multiple", "Note left of Missing: text\nunknown directive", "Note right of A: <b>markup</b>"}) {
        const auto invalid="sequenceDiagram\nparticipant A\n"+std::string(malformed);
        if (!literal6_migrated_public(invalid)) EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(invalid,"mermaid")),240,120)==
                    capture(loom::ui::render_markdown(fenced(invalid,"text")),240,120));
    }
    std::string bounded="sequenceDiagram\nparticipant A\n";Model many{{{"A","A"}},{},{}};
    for(int n=0;n<64;++n) {
        const bool left=n%2==0;const auto text="N"+std::to_string(n);
        bounded+="Note "+std::string(left?"left":"right")+" of A: "+text+"\n";
        many.notes.push_back({{0},text,left?"left":"right",-1});
    }
    const auto full=capture(loom::ui::render_markdown(fenced(bounded,"mermaid")),240,1040);
    ASSERT_TRUE(validate(full,many).empty());
    bounded+="Note left of A: N64";
    EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(bounded,"mermaid")),240,1040)==
                capture(loom::ui::render_markdown(fenced(bounded,"text")),240,1040));
}
TEST(MermaidSequenceSemantics, KeepsNumberedDisplayBudgetAndClosedMessageAdmission) {
    const std::string label=std::string(128,'a')+"<br>"+std::string(124,'b');
    const std::string prefix="sequenceDiagram\nautonumber\nA->>A: ";
    const Model expected{{{"A","A"}},{{0,0,std::string(128,'a')+"\n"+std::string(124,'b'),false,Arrow::Filled,false,false,"1"}}, {}};
    auto element=loom::ui::render_markdown(fenced(prefix+label,"mermaid"));
    const auto wide=capture(element,240,60);
    const auto geometry=validate(wide,expected);for(const auto& error:geometry) ADD_FAILURE()<<error;
    EXPECT_FALSE(wide==capture(loom::ui::render_markdown(fenced(prefix+label,"text")),240,60));
    const auto too_long=prefix+label+"b";
    EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(too_long,"mermaid")),240,60)==
                capture(loom::ui::render_markdown(fenced(too_long,"text")),240,60));
    for(const auto malformed:{"A->>>B: extra", "A ()() ->> B: extra", "A ->>()() B: extra", "A-xB: ok\nunknown directive"}) {
        const auto source="sequenceDiagram\n"+std::string(malformed);
        EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(source,"mermaid")),240,60)==
                    capture(loom::ui::render_markdown(fenced(source,"text")),240,60));
    }
}
// These exact sources previously had fallback-only expectations. Their first
// real failure after per-message numbering is frozen before this migration.
TEST(MermaidSequenceSemantics, MigratesOriginalNumberStartAndLateEnableToCompleteModels) {
    const std::vector<std::pair<std::string,Model>> cases{
        {"sequenceDiagram\nautonumber 3\nA->>B: x",
         {{{"A","A"},{"B","B"}},{{0,1,"x",false,Arrow::Filled,false,false,"3"}}, {}}},
        {"sequenceDiagram\nA->>B: before\nautonumber\nB->>A: after",
         {{{"A","A"},{"B","B"}},{{0,1,"before",false},{1,0,"after",false,Arrow::Filled,false,false,"2"}}, {}}}};
    for(const auto& [source,expected]:cases) {
        SCOPED_TRACE(source);auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        const auto wide=capture(element,240,80);EXPECT_FALSE(wide==capture(loom::ui::render_markdown(fenced(source,"text")),240,80));
        const auto errors=validate(wide,expected);for(const auto& error:errors) ADD_FAILURE()<<error;
        const auto narrow=capture(element,40,80),plain=capture(loom::ui::render_markdown(fenced(source,"text")),40,80);
        if(!(narrow==plain)) EXPECT_TRUE(validate(narrow,expected).empty());
        EXPECT_TRUE(capture(element,240,80)==wide);
        for(const auto* frame:{&wide,&narrow}) {
            bool sentinel=false;for(int y=0;y<frame->height;++y) sentinel|=frame->row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
    }
}
TEST(MermaidSequenceSemantics, KeepsSourceByteLimitAfterCumulativeWorkCharging) {
    const std::string source="sequenceDiagram\nA->>B: hello\n";
    const auto baseline=capture(loom::ui::render_markdown(fenced(source,"mermaid")),240,100);
    std::string padded=source+"%%";padded.append(65536-padded.size(),'c');
    EXPECT_EQ(padded.size(),65536u);
    EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(padded,"mermaid")),240,100)==baseline);
    padded+='c';
    EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(padded,"mermaid")),240,100)==
                capture(loom::ui::render_markdown(fenced(padded,"text")),240,100));
}
TEST(MermaidSequenceSemantics, PreservesExtendedIdentifiersAndNoteFirstUseIdentity) {
    struct Example {std::string source;Model expected;};
    const std::vector<Example> cases{
        {"participant cron job as Cron\nparticipant data=svc as DS\ncron job->>data=svc: sync\ndata=svc--)cron job: ok",
            {{{"cron job","Cron"},{"data=svc","DS"}},{{0,1,"sync",false},{1,0,"ok",true,Arrow::Async}}, {}}},
        {"Alice-in-Wonderland->Bob: hi\nBob-->Alice-in-Wonderland: yo",
            {{{"Alice-in-Wonderland","Alice-in-Wonderland"},{"Bob","Bob"}},{{0,1,"hi",false,Arrow::Unheaded},{1,0,"yo",true,Arrow::Unheaded}}, {}}},
        {"\"A->B\" ->> C: quoted arrow name",{{{"A->B","A->B"},{"C","C"}},{{0,1,"quoted arrow name",false}}, {}}},
        {"participant 用户 as User\n用户->>服务: hello",{{{"用户","User"},{"服务","服务"}},{{0,1,"hello",false}}, {}}},
        {"participant cron  job as same\nparticipant data  svc as same\nparticipant Anchor\ncron  job->>Anchor: from cron\nAnchor->>data  svc: to data",
            {{{"cron  job","same"},{"data  svc","same"},{"Anchor","Anchor"}},{{0,2,"from cron",false},{2,1,"to data",false}}, {}}},
        {"Note over C,D: created\nNote left of C: next\nparticipant C as Client\nC->>D: hello",
            {{{"C","Client"},{"D","D"}},{{0,1,"hello",false}},{{{0,1},"created","over",-1},{{0},"next","left",-1}}}},
        {"A->>B: begin\nNote over C,D: unseen\nD->>A: after",
            {{{"A","A"},{"B","B"},{"C","C"},{"D","D"}},{{0,1,"begin",false},{3,0,"after",false}},{{{2,3},"unseen","over",0}}}},
        {"Note right of A: before\nactor A as Person",{{{"A","Person",Role::Actor}},{},{{{0},"before","right",-1}}}},
        {"\"loop svc\" ()->>() \"data as svc\": hello",
            {{{"loop svc","loop svc"},{"data as svc","data as svc"}},{{0,1,"hello",false,Arrow::Filled,true,true}}, {}}},
        {"participant \"data as svc\" as Alias\n\"data as svc\"->>\"data as svc\": self",
            {{{"data as svc","Alias"}},{{0,0,"self",false}}, {}}},
        {"123->>data.v2: hi",{{{"123","123"},{"data.v2","data.v2"}},{{0,1,"hi",false}}, {}}},
        {"\"<br>\"->>B: literal",{{{"<br>","<br>"},{"B","B"}},{{0,1,"literal",false}}, {}}},
        {"actor-service->>note.svc: punctuation",{{{"actor-service","actor-service"},{"note.svc","note.svc"}},{{0,1,"punctuation",false}}, {}}},
    };
    for(const auto& test:cases) {
        const auto source="sequenceDiagram\n"+test.source;SCOPED_TRACE(source);
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        const auto wide=capture(element,240,160),plain=capture(loom::ui::render_markdown(fenced(source,"text")),240,160);
        EXPECT_FALSE(wide==plain);
        const auto errors=validate(wide,test.expected);for(const auto& error:errors) ADD_FAILURE()<<error;
        bool sentinel=false;for(int y=0;y<wide.height;++y) sentinel|=wide.row(y).find(kSentinel)!=std::string::npos;
        EXPECT_TRUE(sentinel);
        const auto narrow=capture(element,40,160),text=capture(loom::ui::render_markdown(fenced(source,"text")),40,160);
        if(!(narrow==text)) EXPECT_TRUE(validate(narrow,test.expected).empty());
        EXPECT_TRUE(capture(element,240,160)==wide);
    }
}
bool complete_sequence_sentinel(const Grid&);
void config8ab_terminal_old_plain_alias();
TEST(MermaidSequenceSemantics, RejectsAmbiguousExtendedNamesWithoutDroppingStatements) {
    for(const auto malformed:{"\"A->B ->> C: unclosed", "A->>\"C: unterminated", "\"A->B\"->>C->>D: extra",
                             "loop retry ->>B: not a message",
                             "A->>++B: invalid activation suffix",
                             "A->>>B: extra", "Note over A,A: duplicate", "Note over A,B,C: third",
                             "Note left of A,B: multiple", "Note over \"unterminated: text", "Note over : missing"}) {
        const auto source="sequenceDiagram\n"+std::string(malformed);SCOPED_TRACE(source);
        EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(source,"mermaid")),240,120)==
                    capture(loom::ui::render_markdown(fenced(source,"text")),240,120));
    }
    config8ab_terminal_old_plain_alias();
    const std::string valid="sequenceDiagram\nlooped->>actorService: hello";
    const Model expected{{{"looped","looped"},{"actorService","actorService"}},{{0,1,"hello",false}}, {}};
    EXPECT_TRUE(validate(capture(loom::ui::render_markdown(fenced(valid,"mermaid")),240,120),expected).empty());
    // Exact former fallback source retained as a complete source-backed Actor
    // positive; primary role metadata is YAML, not a JSON-only grammar.
    const std::string yaml_source="sequenceDiagram\nparticipant A@{type: actor}\nA->>B: unsupported config";
    const Model yaml_model{{{"A","A",Role::Actor},{"B","B"}},{{0,1,"unsupported config",false}},{}};
    auto yaml_node=loom::ui::render_markdown(fenced(yaml_source,"mermaid"));
    const auto yaml_plain=loom::ui::render_markdown(fenced(yaml_source,"text"));
    const auto yaml_wide=capture(yaml_node,240,120),yaml_narrow=capture(yaml_node,40,120),yaml_restored=capture(yaml_node,240,120);
    EXPECT_FALSE(yaml_wide==capture(yaml_plain,240,120));EXPECT_TRUE(yaml_wide==yaml_restored);
    for(const auto& error:validate(yaml_wide,yaml_model))ADD_FAILURE()<<error;
    if(yaml_narrow!=capture(yaml_plain,40,120))for(const auto& error:validate(yaml_narrow,yaml_model))ADD_FAILURE()<<error;
    for(const auto* frame:{&yaml_wide,&yaml_narrow,&yaml_restored})EXPECT_TRUE(complete_sequence_sentinel(*frame));
}
TEST(MermaidSequenceSemantics, PreservesLiteralArrowsAndColonsInsideTextFields) {
    const std::string source="sequenceDiagram\nparticipant A as A > Actor\n"
        "A->>B: fall back -> origin: yes\nNote over A,B: nightly -> at 02:00\nNote right of B: done > ack";
    const Model expected{{{"A","A > Actor"},{"B","B"}},{{0,1,"fall back -> origin: yes",false}},
        {{{0,1},"nightly -> at 02:00","over",0},{{1},"done > ack","right",0}}};
    auto element=loom::ui::render_markdown(fenced(source,"mermaid"));const auto wide=capture(element,240,120);
    EXPECT_FALSE(wide==capture(loom::ui::render_markdown(fenced(source,"text")),240,120));
    const auto errors=validate(wide,expected);for(const auto& error:errors) ADD_FAILURE()<<error;
    const auto narrow=capture(element,40,120),plain=capture(loom::ui::render_markdown(fenced(source,"text")),40,120);
    if(!(narrow==plain)) EXPECT_TRUE(validate(narrow,expected).empty());
    EXPECT_TRUE(capture(element,240,120)==wide);
    for(const auto text:{"<b>HTML</b>","&gt;", "value #62;", "`rich`"}) {
        const auto unsupported="sequenceDiagram\nA->>B: "+std::string(text);
        if (!literal6_migrated_public(unsupported)) EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(unsupported,"mermaid")),240,120)==
                    capture(loom::ui::render_markdown(fenced(unsupported,"text")),240,120));
    }
}
TEST(MermaidSequenceSemantics, RendersReviewedFragmentKindsAndOrderedBranches) {
    auto check=[](const std::string& source,const Model& expected) {
        SCOPED_TRACE(source);auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        const auto wide=capture(element,240,256);
        ASSERT_FALSE(wide==capture(loom::ui::render_markdown(fenced(source,"text")),240,256));
        const auto errors=validate(wide,expected);for(const auto& error:errors) ADD_FAILURE()<<error;
        const auto narrow=capture(element,40,256),text=capture(loom::ui::render_markdown(fenced(source,"text")),40,256);
        if(narrow!=text) EXPECT_TRUE(validate(narrow,expected).empty());
        EXPECT_TRUE(capture(element,240,256)==wide);
    };
    for(const auto kind:{"loop","opt","alt","par","critical","break","rect"}) {
        const std::string condition=std::string_view(kind)=="rect"?"rgb(0,255,0)":"ready -> now: yes";
        auto expected=fragment_pair();expected.fragments={{kind,condition,-1,{}}};
        expected.order={{EventKind::Open,0},{EventKind::Message,0},{EventKind::Close,0}};
        check("sequenceDiagram\nparticipant a as A\nparticipant b as B\n"+std::string(kind)+" "+condition+"\na->>b: hello\nend",expected);
    }
    auto expected=fragment_pair();expected.fragments={{"alt","outer",-1,{"next","last"}},{"opt","inner",0,{}}};
    expected.messages.push_back({1,0,"reply",false});
    expected.notes={{{0},"nested note","over",0}};
    expected.order={{EventKind::Open,0},{EventKind::Open,1},{EventKind::Message,0},{EventKind::Note,0},
        {EventKind::Close,1},{EventKind::Divide,0,0},{EventKind::Message,1},{EventKind::Divide,0,1},{EventKind::Close,0}};
    check("sequenceDiagram\nparticipant a as A\nparticipant b as B\nalt outer\nopt inner\n"
        "a->>b: hello\nNote over a: nested note\nend\nelse next\nb->>a: reply\nelse last\nend",expected);
    for(const auto& [kind,divider]:std::array<std::pair<std::string_view,std::string_view>,2>{{{"par","and"},{"critical","option"}}}) {
        expected=fragment_pair();expected.fragments={{std::string(kind),"",-1,{"again"}}};
        expected.order={{EventKind::Open,0},{EventKind::Divide,0},{EventKind::Message,0},{EventKind::Close,0}};
        check("sequenceDiagram\nparticipant a as A\nparticipant b as B\n"+std::string(kind)+"\n"+std::string(divider)+" again\na->>b: hello\nend",expected);
    }
}
TEST(MermaidSequenceSemantics, KeepsEmptyFragmentsAndWholeSourceResourceLimits) {
    auto check=[](const std::string& source,const Model& expected) {
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));const auto wide=capture(element,240,1040);
        ASSERT_FALSE(wide==capture(loom::ui::render_markdown(fenced(source,"text")),240,1040));
        const auto errors=validate(wide,expected);for(const auto& error:errors) ADD_FAILURE()<<error;
        const auto narrow=capture(element,40,1040),text=capture(loom::ui::render_markdown(fenced(source,"text")),40,1040);
        if(narrow!=text) EXPECT_TRUE(validate(narrow,expected).empty());
        const auto restored=capture(element,240,1040);EXPECT_TRUE(restored==wide);
        for(const auto* frame:{&wide,&narrow,&restored}) {
            bool sentinel=false;for(int y=0;y<frame->height;++y) sentinel|=frame->row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
    };
    Model siblings;std::string source="sequenceDiagram\n";
    for(int n=0;n<64;++n) {
        siblings.fragments.push_back({"loop","",-1,{}});
        siblings.order.push_back({EventKind::Open,n});siblings.order.push_back({EventKind::Close,n});source+="loop\nend\n";
    }
    check(source,siblings);
    auto fallback=[](const std::string& source) {
        if (literal6_migrated_public(source)) return;
        EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(source,"mermaid")),240,1040)==
                    capture(loom::ui::render_markdown(fenced(source,"text")),240,1040));
    };
    fallback(source+"loop\nend\n");
    Model nested;source="sequenceDiagram\n";
    for(int n=0;n<16;++n) {nested.fragments.push_back({"loop","",n-1,{}});nested.order.push_back({EventKind::Open,n});source+="loop\n";}
    for(int n=15;n>=0;--n) {nested.order.push_back({EventKind::Close,n});source+="end\n";}
    check(source,nested);fallback("sequenceDiagram\nloop\n"+source.substr(16)+"end\n");
    const std::string condition=std::string(125,'a')+"<br>"+std::string(125,'b');
    const Model bounded{{},{},{},{{"loop",std::string(125,'a')+"\n"+std::string(125,'b'),-1,{}}},
        {{EventKind::Open,0},{EventKind::Close,0}}};
    check("sequenceDiagram\nloop "+condition+"\nend",bounded);
    fallback("sequenceDiagram\nloop "+condition+"b\nend");
    for(const auto malformed:{"end","else no","and no","option no","loop retry\nA->>B: x",
        "alt one\nand two\nend","par one\nelse two\nend","critical one\nelse two\nend",
        "loop retry\nelse other\nend","opt once\noption other\nend","loop <b>rich</b>\nend"})
        fallback("sequenceDiagram\n"+std::string(malformed));
}
TEST(MermaidSequenceSemantics, SourceReviewedOfficialSideNotes) {
    int config38_raw_migrated=0;
    const auto root=std::filesystem::path(LOOM_TESTS_DIR)/"fixtures";
    std::ifstream input(root/"mermaid_native/sequence_official_side_notes_facts.json",std::ios::binary);
    ASSERT_TRUE(input);
    const std::string bytes{std::istreambuf_iterator<char>(input),std::istreambuf_iterator<char>()};
    ASSERT_EQ(loom::utils::crypto::sha256(bytes),"9a5ce7dc8c5f98badaf5c6a86346d8acbf98f6088b3851c2ef7e6131d188e1c7");
    const auto doc=json::parse(bytes);ASSERT_TRUE(doc.has_value());
    ASSERT_EQ(doc->root().get("cases").size(),8u);
    std::set<std::string> paths,bodies;
    doc->root().get("cases").iter([&](JsonVal test){
        const auto path=test.get_string("path");SCOPED_TRACE(path);EXPECT_TRUE(paths.insert(path).second);
        std::ifstream source_file(root/"mermaid_official/cases"/path,std::ios::binary);ASSERT_TRUE(source_file);
        const std::string raw{std::istreambuf_iterator<char>(source_file),std::istreambuf_iterator<char>()};
        ASSERT_EQ(loom::utils::crypto::sha256(raw),test.get_string("raw_sha256"));
        const auto offset=static_cast<std::size_t>(test.get_int("body_offset_utf8_bytes"));ASSERT_LE(offset,raw.size());
        const auto body=raw.substr(offset);ASSERT_EQ(body,test.get_string("body"));
        ASSERT_EQ(loom::utils::crypto::sha256(body),test.get_string("body_sha256"));EXPECT_TRUE(bodies.insert(body).second);
        Model expected;const auto meaning=test.get("model");
        meaning.get("actors").iter([&](JsonVal a){expected.actors.push_back({a.get_string("id"),a.get_string("label"),role_fact(a)});});
        meaning.get("messages").iter([&](JsonVal m){
            const auto name=m.get_string("arrow");ASSERT_TRUE(name=="Filled"||name=="Both");
            expected.messages.push_back({static_cast<int>(m.get_int("from")),static_cast<int>(m.get_int("to")),m.get_string("label"),m.get("dashed").as_bool(),
                name=="Both"?Arrow::Both:Arrow::Filled,m.get("central_from").as_bool(),m.get("central_to").as_bool(),fact_number(m.get("number"))});
        });
        meaning.get("notes").iter([&](JsonVal n){
            Note note{{},n.get_string("text"),n.get_string("position"),static_cast<int>(n.get_int("after"))};
            n.get("actors").iter([&](JsonVal a){note.actors.push_back(static_cast<int>(a.as_int()));});expected.notes.push_back(std::move(note));
        });
        auto element=loom::ui::render_markdown(fenced(body,"mermaid"));const auto wide=capture(element,240,160);
        ASSERT_FALSE(wide==capture(loom::ui::render_markdown(fenced(body,"text")),240,160));
        const auto errors=validate(wide,expected);for(const auto& error:errors) ADD_FAILURE()<<error;
        const auto narrow=capture(element,40,160),plain=capture(loom::ui::render_markdown(fenced(body,"text")),40,160);
        if(!(narrow==plain)) EXPECT_TRUE(validate(narrow,expected).empty());
        EXPECT_TRUE(capture(element,240,160)==wide);
        for(const auto* frame:{&wide,&narrow}) {
            bool sentinel=false;for(int y=0;y<frame->height;++y) sentinel|=frame->row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
        if (config38_legacy_raw(path,raw)) ++config38_raw_migrated;
        else if (!description77_legacy_raw(raw) && !config116_legacy_raw(raw)) EXPECT_TRUE(capture(loom::ui::render_markdown(fenced(raw,"mermaid")),240,160)==
                    capture(loom::ui::render_markdown(fenced(raw,"text")),240,160));
    });
    EXPECT_EQ(paths.size(),8u);EXPECT_EQ(bodies.size(),8u);
    EXPECT_EQ(config38_raw_migrated,5);
}
