Model official_message_meaning(int kind) {
    const Actor alice{"Alice","Alice"},bob{"Bob","Bob"},john{"John","John"},charlie{"Charlie","Charlie"};
    if(kind==0) return {{{"A","A"},{"B","B"}},
        {{0,1,"This is a bidirectional message",false,Arrow::Both,false,false,"1"},
         {0,1,"This is a normal message",false,Arrow::Unheaded,false,false,"2"}}, {}};
    if(kind==1) return {{alice,john},
        {{0,1,"Hello John,\nhow are you?",false,Arrow::Filled,false,false,"1"},
         {0,1,"John,\ncan you hear me?",false,Arrow::Filled,false,false,"2"},
         {1,0,"Hi Alice,\nI can hear you!",true,Arrow::Filled,false,false,"3"},
         {1,0,"I feel great!",true,Arrow::Filled,false,false,"4"}}, {}};
    if(kind==2) return {{alice,john},
        {{0,1,"Hello John, how are you?",false,Arrow::Both},
         {0,1,"Hi Alice, I can hear you!",true,Arrow::Both},
         {1,0,"This also works the other way",false,Arrow::Both},
         {1,0,"Yes",true,Arrow::Both},{0,1,"Test",false,Arrow::Unheaded},{1,0,"Still works",false}}, {}};
    if(kind==3) return {{alice,bob,charlie},
        {{0,1,"Central connection",false,Arrow::Filled,true,true},
         {1,2,"Reverse central connection",true,Arrow::Filled,true,false},
         {2,0,"Dual central connection",true,Arrow::Both,true,true}}, {}};
    if(kind==4) return {{alice,bob,charlie},
        {{0,1,"Normal message",false},{1,2,"Central connection",false,Arrow::Filled,true,true},
         {2,0,"Normal dotted message",true},{0,1,"Dual central connection",true,Arrow::Both,true,true},
         {1,2,"Normal cross message",false,Arrow::Cross}}, {}};
    if(kind==5) return {{alice,bob},
        {{0,1,"Bidirectional solid",false,Arrow::Both,true,true},{0,1,"Bidirectional dotted",true,Arrow::Both,true,true}}, {}};
    if(kind==6) return {{alice,bob},
        {{0,1,"Solid open arrow",false,Arrow::Filled,true,true},
         {0,1,"Dotted open arrow",true,Arrow::Filled,true,true},
         {0,1,"Solid cross",false,Arrow::Cross,true,true},{0,1,"Dotted cross",true,Arrow::Cross,true,true},
         {0,1,"Solid arrow",false,Arrow::Unheaded,true,true}}, {}};
    return {{{"A","Extremely utterly long line of longness which had previously overflown the actor box as it is much longer than what it should be"},bob},
        {{0,1,"Hola",false},{1,0,"Pasten !",true,Arrow::Unheaded}}, {}};
}
