TEST(MermaidSequenceSemantics, FrozenBeautifulSequenceCohort) {
    const auto bytes=input_bytes();ASSERT_EQ(loom::utils::crypto::sha256(bytes),"4a1fab2e4235ba475f00fe9c687bce0d1cb15f7bacf470c5d287a0ba957a4293");
    const auto doc=json::parse(bytes);ASSERT_TRUE(doc.has_value());
    json::JsonMutDoc report;auto root=report.object();auto cases=root.make_arr();std::size_t count=0;
    root.set("kind","frozen_beautiful_sequence_cell_observations");
    doc->root().get("cases").iter([&](JsonVal c){
        if(c.get_string("family")!="sequence") return;
        ++count;const auto source=c.get_string("input");SCOPED_TRACE(c.get_string("id"));
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        auto ordinary_element=loom::ui::render_markdown(fenced(source,"text"));
        element->ComputeRequirement();const int height=std::min(1040,std::max(40,element->requirement().min_y+12));
        const auto wide=capture(element,240,height),ordinary_wide=capture(ordinary_element,240,height);
        auto errors=validate(wide,model(c.get("expectation").get("semantic_model")));
        const bool drawn=wide!=ordinary_wide;
        std::string text;for(int y=0;y<wide.height;++y) text+=wide.row(y)+'\n';
        std::size_t assertions=0;
        c.get("expectation").get("assertions").iter([&](JsonVal a){
            ++assertions;const auto kind=a.get_string("kind"),value=a.get_string("value");
            if(a.get("render_options").get("useAscii").as_bool()) {errors.push_back("Unported ASCII predicate");return;}
            if(kind!="contains"&&kind!="not_contains") {errors.push_back("Unported original predicate");return;}
            if((kind=="contains")!=(text.find(value)!=std::string::npos)) errors.push_back("Original predicate failed: "+value);
        });
        if(!drawn) errors.push_back("Wide source fallback is not a drawing");
        if(text.find(kSentinel)==std::string::npos) errors.push_back("Following Markdown lost");
        const auto narrow=capture(element,40,height),narrow_source=capture(ordinary_element,40,height);
        const auto restored=capture(element,240,height);
        if(restored!=wide) errors.push_back("Width restoration changed cells");
        auto has_sentinel=[&](const Grid& g) {for(int y=0;y<g.height;++y) if(g.row(y).find(kSentinel)!=std::string::npos) return true;return false;};
        if(!has_sentinel(narrow)||!has_sentinel(restored)) errors.push_back("Following Markdown lost after resize");
        if(narrow!=narrow_source) {
            const auto narrow_errors=validate(narrow,model(c.get("expectation").get("semantic_model")));
            errors.insert(errors.end(),narrow_errors.begin(),narrow_errors.end());
        }
        auto row=cases.make_obj();row.set("id",c.get_string("id"));row.set("drawn",drawn);row.set("assertions_executed",static_cast<std::int64_t>(assertions));
        row.set("input_sha256",loom::utils::crypto::sha256(source));
        row.set("semantic_model_sha256",loom::utils::crypto::sha256(c.get("expectation").get("semantic_model").to_string()));
        auto append_frame=[&](std::string_view key,const Grid& g){auto lines=root.make_arr();for(int y=0;y<g.height;++y) lines.append(root.make_str(g.row(y)));row.add(key,lines);};
        append_frame("wide_frame",wide);append_frame("narrow_frame",narrow);append_frame("restored_frame",restored);
        auto failures=row.make_arr();for(const auto& error:errors) {failures.append(root.make_str(error));ADD_FAILURE()<<error;}
        row.add("errors",failures);cases.append(row);
    });
    EXPECT_EQ(count,6u);root.add("cases",cases);report.set_root(root);
    std::filesystem::create_directories(LOOM_MERMAID_REPORT_DIR);
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-sequence-semantics.json");output<<report.to_string()<<'\n';ASSERT_TRUE(output.good());
}
// Native supplements are separate from the immutable upstream capture. Every
// source witness and model path is hash bound before a cell assertion can run.
std::string fixture_bytes(std::string_view relative) {
    std::ifstream file(std::filesystem::path(LOOM_TESTS_DIR)/"fixtures"/relative,std::ios::binary);
    if(!file) throw std::runtime_error("Missing sequence fixture: "+std::string(relative));
    return {std::istreambuf_iterator<char>(file),std::istreambuf_iterator<char>()};
}
JsonVal pointer(JsonVal value,std::string_view path) {
    if(path.empty()||path.front()!='/') throw std::runtime_error("Invalid frozen JSON pointer");
    path.remove_prefix(1);
    for(;;) {
        const auto slash=path.find('/');const auto key=path.substr(0,slash);
        if(value.is_arr()) {
            std::size_t index=0;const auto result=std::from_chars(key.data(),key.data()+key.size(),index);
            if(result.ec!=std::errc{}||result.ptr!=key.data()+key.size()) throw std::runtime_error("Invalid frozen array index");
            value=value.at(index);
        } else value=value.get(key);
        if(!value) throw std::runtime_error("Missing frozen model path");
        if(slash==std::string_view::npos) return value;
        path.remove_prefix(slash+1);
    }
}
std::string display_field(JsonVal model,JsonVal facts,const std::string& path) {
    const auto original=pointer(model,path);if(!original.is_str()) throw std::runtime_error("Nontext model path");
    std::string result(original.as_str());int matches=0;
    for(const auto key:{"display_sensitive_source_fields","explicit_break_fields"}) facts.get(key).iter([&](JsonVal field){
        if(field.get_string("model_path")!=path) return;
        if(field.get_string("raw")!=original.as_str()||++matches>1) throw std::runtime_error("Conflicting frozen display fact");
        result=field.get_string("display");
    });
    return result;
}
struct GoModel {Model simple;std::vector<std::string> pending;bool valid_empty=false;};
GoModel go_model(JsonVal value,JsonVal facts) {
    GoModel out;std::map<std::string,std::string> roles;std::set<std::string> declared_created,event_created;
    facts.get("actor_declarations").iter([&](JsonVal declaration){
        roles[declaration.get_string("id")]=declaration.get_string("role");
        if(declaration.get("created").as_bool()) declared_created.insert(declaration.get_string("id"));
    });
    value.get("actors").iter([&](JsonVal actor){
        const auto index=out.simple.actors.size();const auto id=actor.get_string("id");
        if(roles.contains(id)&&roles[id]!="participant"&&roles[id]!="actor") throw std::runtime_error("Unknown frozen declaration role");
        out.simple.actors.push_back({id,display_field(value,facts,"/actors/"+std::to_string(index)+"/label"),roles.contains(id)&&roles[id]=="actor"?Role::Actor:Role::Participant});
    });
    auto actor_index=[&](const std::string& id) {
        for(std::size_t n=0;n<out.simple.actors.size();++n) if(out.simple.actors[n].id==id) return static_cast<int>(n);
        throw std::runtime_error("Unknown frozen Go actor identity");
    };
    value.get("messages").iter([&](JsonVal message){
        const auto a=message.get_string("arrow");
        Arrow kind=Arrow::Filled;
        if(a=="solid-open"||a=="dotted-open") kind=Arrow::Unheaded;
        else if(a=="solid-point"||a=="dotted-point") kind=Arrow::Async;
        else if(a=="solid-cross"||a=="dotted-cross") kind=Arrow::Cross;
        else if(a=="bidirectional-solid"||a=="bidirectional-dotted") kind=Arrow::Both;
        else if(a!="solid"&&a!="dotted") throw std::runtime_error("Unmapped frozen Go arrow");
        const auto path="/messages/"+std::to_string(out.simple.messages.size())+"/label";
        out.simple.messages.push_back({actor_index(message.get_string("from")),actor_index(message.get_string("to")),
            display_field(value,facts,path),a.find("dotted")!=std::string::npos,kind,
            message.get("central_from").as_bool(),message.get("central_to").as_bool(),fact_number(message.get("number"))});
    });
    std::vector<std::string> rect_colors;
    facts.get("color_regions").iter([&](JsonVal region){
        if(region.get_string("kind")=="rect") rect_colors.push_back(region.get_string("color"));
    });
    std::vector<int> fragments;std::size_t rect_index=0;
    int message_index=-1,event_index=-1;
    value.get("events").iter([&](JsonVal event){
        ++event_index;const auto kind=event.get_string("kind");
        if(kind=="message") {out.simple.order.push_back({EventKind::Message,++message_index});return;}
        if(kind=="fragment-start") {
            const auto fragment=event.get("fragment");const auto type=fragment.get_string("type");
            auto label=display_field(value,facts,"/events/"+std::to_string(event_index)+"/fragment/label");
            if(type=="rect") {
                if(rect_index>=rect_colors.size()||!label.empty()) throw std::runtime_error("Missing/conflicting source-only rect color");
                label=rect_colors[rect_index++];
            }
            const int index=static_cast<int>(out.simple.fragments.size());
            out.simple.fragments.push_back({type,std::move(label),fragments.empty()?-1:fragments.back(),{}});
            out.simple.order.push_back({EventKind::Open,index});fragments.push_back(index);return;
        }
        if(kind=="fragment-divider") {
            if(fragments.empty()) throw std::runtime_error("Orphan frozen Go divider");
            const int index=fragments.back();auto& fragment=out.simple.fragments[static_cast<std::size_t>(index)];
            if(event.get("fragment").get_string("type")!=fragment.kind) throw std::runtime_error("Mismatched frozen Go divider kind");
            out.simple.order.push_back({EventKind::Divide,index,static_cast<int>(fragment.dividers.size())});
            fragment.dividers.push_back(display_field(value,facts,"/events/"+std::to_string(event_index)+"/fragment/label"));return;
        }
        if(kind=="fragment-end") {
            if(fragments.empty()) throw std::runtime_error("Orphan frozen Go close");
            out.simple.order.push_back({EventKind::Close,fragments.back()});fragments.pop_back();return;
        }
        if(kind=="activate"||kind=="deactivate") {
            out.simple.order.push_back({kind=="activate"?EventKind::Activate:EventKind::Deactivate,
                                        actor_index(event.get_string("participant_id"))});return;
        }
        if(kind=="create"||kind=="destroy") {
            const auto id=event.get_string("participant_id");
            if(kind=="create"&&!event_created.insert(id).second) throw std::runtime_error("Duplicate frozen Go creation");
            out.simple.order.push_back({kind=="create"?EventKind::Create:EventKind::Destroy,actor_index(id)});return;
        }
        if(kind!="note") {out.pending.push_back("Ordered event geometry: "+kind);return;}
        const auto note=event.get("note");Note meaning{{},display_field(value,facts,"/events/"+std::to_string(event_index)+"/note/text"),note.get_string("placement"),message_index};
        note.get("actor_ids").iter([&](JsonVal id){meaning.actors.push_back(actor_index(std::string(id.as_str())));});
        if(meaning.actors.empty()) throw std::runtime_error("Missing frozen note actors");
        if(meaning.position!="over"&&meaning.position!="left"&&meaning.position!="right") throw std::runtime_error("Unknown frozen note placement");
        out.simple.order.push_back({EventKind::Note,static_cast<int>(out.simple.notes.size())});
        out.simple.notes.push_back(std::move(meaning));
    });
    std::set<std::string> model_created;
    value.get("created").iter([&](JsonVal actor) {
        const auto id=actor.get_string("ID");const auto index=actor_index(id);
        if(!model_created.insert(id).second||actor.get_int("Index")!=index||
            actor.get_string("Label")!=value.get("actors").at(static_cast<std::size_t>(index)).get_string("label"))
            throw std::runtime_error("Conflicting frozen Go created actor identity");
    });
    if(event_created!=declared_created||model_created!=declared_created)
        throw std::runtime_error("Incomplete frozen Go created actor mapping");
    if(message_index+1!=static_cast<int>(out.simple.messages.size())) throw std::runtime_error("Frozen Go event/message mismatch");
    if(!fragments.empty()||rect_index!=rect_colors.size()) throw std::runtime_error("Incomplete frozen Go fragment/color mapping");
    value.get("boxes").iter([&](JsonVal box){
        const auto index=out.simple.boxes.size();
        ParticipantBox group{{},display_field(value,facts,"/boxes/"+std::to_string(index)+"/Title"),{}};
        const auto first=box.get_int("First"),last=box.get_int("Last");
        if(first<0||last<first||last>=static_cast<std::int64_t>(out.simple.actors.size()))
            throw std::runtime_error("Invalid frozen participant box interval");
        for(auto a=first;a<=last;++a) group.actors.push_back(static_cast<int>(a));
        int witnesses=0;
        facts.get("color_regions").iter([&](JsonVal region){
            if(region.get_string("kind")!="box"||region.get_int("box_index")!=static_cast<std::int64_t>(index)) return;
            if(++witnesses!=1||region.get_string("title")!=box.get_string("Title"))
                throw std::runtime_error("Conflicting frozen box title/color source fact");
            group.color=region.get_string("color");
        });
        if(witnesses!=1) throw std::runtime_error("Missing independent box color witness");
        out.simple.boxes.push_back(std::move(group));
    });
    Work model_work;check_event_model(out.simple,model_work);
    if(facts.get("authored_titles").size()>1) throw std::runtime_error("Conflicting frozen Go titles");
    facts.get("authored_titles").iter([&](JsonVal title) {
        out.simple.title=title.get_string("text");
        if(out.simple.title.empty()) throw std::runtime_error("Empty frozen authored title");
    });
    out.valid_empty=out.simple.actors.empty()&&out.simple.messages.empty()&&value.get("events").size()==0;
    return out;
}
TEST(MermaidActivationSceneOracle, MapsEveryFrozenGoActivationWithoutDroppingOtherObligations) {
    const auto vendor=json::parse(fixture_bytes("mermaid_terminal/mermaid_ascii/cases.json"));
    const auto facts=json::parse(fixture_bytes("mermaid_native/sequence_go_facts.json"));ASSERT_TRUE(vendor&&facts);
    std::map<std::string,JsonVal> by_id;
    facts->root().get("cases").iter([&](JsonVal c){by_id.emplace(c.get_string("id"),c);});
    int starts=0,stops=0;
    vendor->root().get("cases").iter([&](JsonVal c){
        if(c.get_string("family")!="sequence") return;
        const auto original=c.get("expectation").get("semantic_model");if(!original) return;
        const auto converted=go_model(original,by_id.at(c.get_string("id")));
        int want_start=0,want_stop=0,have_start=0,have_stop=0;
        original.get("events").iter([&](JsonVal e){
            want_start+=e.get_string("kind")=="activate";want_stop+=e.get_string("kind")=="deactivate";
        });
        for(const auto& event:converted.simple.order) {
            have_start+=event.kind==EventKind::Activate;have_stop+=event.kind==EventKind::Deactivate;
        }
        EXPECT_EQ(want_start,have_start);EXPECT_EQ(want_stop,have_stop);starts+=have_start;stops+=have_stop;
        EXPECT_EQ(converted.simple.boxes.size(),original.get("boxes").size());
    });
    EXPECT_EQ(starts,12);EXPECT_EQ(stops,11);
    auto model=activation_scene_model();model.order.insert(model.order.begin(),{EventKind::Deactivate,0});
    EXPECT_FALSE(validate(activation_scene(),model).empty());
    model=activation_scene_model();model.order[0].part=1;EXPECT_FALSE(validate(activation_scene(),model).empty());
}
TEST(MermaidSequenceSemantics, ActivationSourceFormsRequireCompleteOwnedGeometry) {
    auto check=[](const std::string& source,const Model& model) {
        SCOPED_TRACE(source);const auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        const auto wide=capture(element,240,1040),text=capture(loom::ui::render_markdown(fenced(source,"text")),240,1040);
        ASSERT_FALSE(wide==text)<<"Source-positive activation remains unsupported";
        for(const auto& error:validate(wide,model)) ADD_FAILURE()<<error;
        const auto narrow=capture(element,40,1040),plain=capture(loom::ui::render_markdown(fenced(source,"text")),40,1040);
        if(narrow!=plain) for(const auto& error:validate(narrow,model)) ADD_FAILURE()<<error;
        const auto restored=capture(element,240,1040);EXPECT_TRUE(restored==wide);
        for(const auto* frame:{&wide,&narrow,&restored}) {
            bool sentinel=false;for(int y=0;y<frame->height;++y) sentinel|=frame->row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
    };
    auto model=ordinary_model();
    model.order={{EventKind::Activate,1},{EventKind::Message,0},{EventKind::Message,1},{EventKind::Deactivate,1}};
    check("sequenceDiagram\nparticipant a as A\nparticipant b as B\nactivate b\na->>b: hello\nb-->>a: reply\ndeactivate b",model);
    model.order={{EventKind::Message,0},{EventKind::Activate,1},{EventKind::Message,1},{EventKind::Deactivate,1}};
    check("sequenceDiagram\nparticipant a as A\nparticipant b as B\na->>+b: hello\nb-->>-a: reply",model);
    check("sequenceDiagram\nparticipant a as A\nparticipant b as B\na->> + b: hello\nb-->>a: reply\ndeactivate b",model);
    model.order.pop_back();
    check("sequenceDiagram\nparticipant a as A\nparticipant b as B\na->>+b: hello\nb-->>a: reply",model);
    Model migrated{{{"A","A"},{"B","B"}},{{0,1,"Request",false}},{}};
    migrated.order={{EventKind::Message,0},{EventKind::Activate,1}};
    check("sequenceDiagram\nA->>B: Request\nactivate B",migrated);
    Model empty{{{"a","A"}},{},{}};empty.order={{EventKind::Activate,0},{EventKind::Deactivate,0}};
    check("sequenceDiagram\nparticipant a as A\nactivate a\ndeactivate a",empty);
}
