TEST(MermaidSequenceSemantics, ActivationDepthAndCompleteEventBoundariesRetainSourceLimits) {
    auto check=[](const std::string& source,const Model& model) {
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));const auto wide=capture(element,240,1040);
        ASSERT_FALSE(wide==capture(loom::ui::render_markdown(fenced(source,"text")),240,1040));
        for(const auto& error:validate(wide,model)) ADD_FAILURE()<<error;
        const auto narrow=capture(element,40,1040),plain=capture(loom::ui::render_markdown(fenced(source,"text")),40,1040);
        if(narrow!=plain) for(const auto& error:validate(narrow,model)) ADD_FAILURE()<<error;
        const auto restored=capture(element,240,1040);EXPECT_TRUE(restored==wide);
        for(const auto* frame:{&wide,&narrow,&restored}) {
            bool sentinel=false;for(int y=0;y<frame->height;++y) sentinel|=frame->row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
    };
    auto fallback=[](const std::string& source) {
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        for(int width:{240,40,240}) {
            const auto frame=capture(element,width,1040);
            EXPECT_TRUE(frame==capture(loom::ui::render_markdown(fenced(source,"text")),width,1040));
            bool sentinel=false;for(int y=0;y<frame.height;++y) sentinel|=frame.row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
    };
    Model depth{{{"a","A"},{"b","B"}},{{0,1,"work",false}},{}};
    std::string source="sequenceDiagram\nparticipant a as A\nparticipant b as B\n";
    for(int n=0;n<16;++n) {source+="activate a\n";depth.order.push_back({EventKind::Activate,0});}
    source+="a->>b: work\n";depth.order.push_back({EventKind::Message,0});
    for(int n=0;n<16;++n) {source+="deactivate a\n";depth.order.push_back({EventKind::Deactivate,0});}
    check(source,depth);
    auto over=source;over.insert(over.find("a->>b:"),"activate a\n");fallback(over);
    Model events{{{"a","A"},{"b","B"}},{},{}};
    source="sequenceDiagram\nparticipant a as A\nparticipant b as B\n";
    for(int n=0;n<128;++n) {
        source+="activate a\nactivate b\ndeactivate a\ndeactivate b\n";
        events.order.insert(events.order.end(),{{EventKind::Activate,0},{EventKind::Activate,1},
                                                {EventKind::Deactivate,0},{EventKind::Deactivate,1}});
    }
    ASSERT_EQ(events.order.size(),512u);check(source,events);fallback(source+"activate a\n");
}
