Grid participant_box_fragment_scene(bool text_on_side) {
    auto g=participant_box_scene();
    for(int y=23;y<=26;++y) for(int x=27;x<=35;++x) g.put(x,y,x==27?"│":" ");
    for(int y=23;y<30;++y) {g.put(2,y,"│");g.put(74,y,"│");}
    for(int y:{22,24,30}) for(int x=3;x<74;++x) g.put(x,y,(x==7||x==27||x==44||x==61)?"┼":"─");
    g.put(2,22,"┌");g.put(74,22,"┐");g.put(2,24,"├");g.put(74,24,"┤");g.put(2,30,"└");g.put(74,30,"┘");
    for(int x=3;x<74;++x) g.put(x,23," ");
    g.text(text_on_side?42:10,23,"loop retry");
    g.text(29,26,"self");g.put(27,27,"├");g.put(35,27,"┐");g.put(27,29,"◀");g.put(35,29,"┘");g.put(35,28,"│");
    for(int x=28;x<35;++x) {g.put(x,27,"─");g.put(x,29,"─");}
    return g;
}
