    auto wrong=expected;wrong.actors[1].role=Role::Participant;EXPECT_FALSE(validate(scene,wrong).empty());
    auto lost_alias=scene;lost_alias.put(35,4," ");EXPECT_FALSE(validate(lost_alias,expected).empty());
