    scene.put(1,0,"┌");scene.put(16,0,"┐");scene.put(1,2,"├");scene.put(16,2,"┤");
    scene.put(1,42,"└");scene.put(16,42,"┘");scene.text(5,1,"Owned");
    for(int y:{12,14,19,26,34}) scene.put(16,y,"┼");
    auto expected=lifetime_model();expected.boxes={{{0},"Owned",""}};
