constexpr std::string_view kGoEofTerminalId="go_lifecycle_source_5330763644ae19a6";
constexpr std::string_view kGoEofTerminalSha="f40475b5a6b68ff69923089fe4a86fdd33f5263ab7f01748eb388b392726cea7";
json::JsonDoc go_eof_terminal_document(Work&);
Model go_eof_terminal_model(JsonVal,JsonVal,Work&,std::size_t&);
