TEST(MermaidSequenceSemantics, LifecycleUnion24RequiresCompleteSourceReviewedGeometry) {
    const auto bytes=fixture_bytes("mermaid_native/sequence_lifecycle_union24_facts.json");
    ASSERT_EQ(loom::utils::crypto::sha256(bytes),kLifecycleFactsSha);const auto doc=json::parse(bytes);ASSERT_TRUE(doc);
    Work terminal_setup;const auto terminal=go_eof_terminal_document(terminal_setup);
    json::JsonMutDoc report;auto root=report.object(),observations=root.make_arr();
    root.set("kind","complete_source_reviewed_lifecycle_union24_native_profile_not_original_assertion_graduation");
    int seen=0,positives=0,negatives=0,drawn=0,matched=0,policy=0,terminal_selected=0,terminal_mutated=0;
    doc->root().get("cases").iter([&](JsonVal c) {
        ++seen;const auto id=c.get_string("id");const bool terminal_projection=id==kGoEofTerminalId;
        Work terminal_work;if(terminal_projection){++terminal_selected;terminal_work.spend(c.get("input").as_str().size()*6u+256u);}
        const auto source=c.get_string("input");SCOPED_TRACE(id);
        const bool positive=terminal_projection||c.get_string("expected")=="drawing";positive?++positives:++negatives;
        std::vector<std::string> errors;std::string wide_hash,narrow_hash,restored_hash;bool fallback=true;
        try {
            if(terminal_projection)terminal_work.spend(512u*(3u*240u+2u*40u)*8u+512u*(240u+40u+240u)*8u+256u);
            auto element=loom::ui::render_markdown(fenced(source,"mermaid"));auto plain=loom::ui::render_markdown(fenced(source,"text"));
            const auto wide=capture(element,240,512),narrow=capture(element,40,512),restored=capture(element,240,512);
            wide_hash=lifecycle_frame_hash(wide);narrow_hash=lifecycle_frame_hash(narrow);restored_hash=lifecycle_frame_hash(restored);
            fallback=wide==capture(plain,240,512);
            if(positive) {
                if(terminal_projection) {
                    if(restored!=wide)errors.emplace_back("Go EOF same-node restoration changed cells");
                    for(const auto* frame:{&wide,&narrow,&restored}){terminal_work.spend(frame->cells.size()+1u);if(!complete_sequence_sentinel(*frame))errors.emplace_back("Go EOF complete physical sentinel missing");}
                }
                std::size_t terminal_copy=0;
                const auto expected=terminal_projection?go_eof_terminal_model(terminal.root(),c,terminal_work,terminal_copy):lifecycle_fact_model(c.get("model"));
                if(fallback) errors.emplace_back("A complete lifecycle source obligation remains source fallback");
                else {++drawn;const auto geometry=terminal_projection?validate(wide,expected,terminal_work.remaining):validate(wide,expected);errors.insert(errors.end(),geometry.begin(),geometry.end());}
                if(narrow!=capture(plain,40,512)) {
                    const auto geometry=terminal_projection?validate(narrow,expected,terminal_work.remaining):validate(narrow,expected);errors.insert(errors.end(),geometry.begin(),geometry.end());
                }
                if(terminal_projection&&errors.empty()) {
                    const auto changes=go_eof_terminal_mutations(wide,expected,terminal_copy,terminal_work.remaining);
                    errors.insert(errors.end(),changes.begin(),changes.end());if(changes.empty())++terminal_mutated;
                }
            } else if(!fallback||narrow!=capture(plain,40,512)||restored!=capture(plain,240,512))
                errors.emplace_back("Invalid/unbound lifecycle source did not preserve the complete ordinary code block");
            if(restored!=wide) errors.emplace_back("Lifecycle same-node width restoration changed cells");
            for(const auto* frame:{&wide,&narrow,&restored}) {
                bool sentinel=false;for(int y=0;y<frame->height;++y) sentinel|=frame->row(y).find(kSentinel)!=std::string::npos;
                if(!sentinel) errors.emplace_back("Lifecycle following Markdown sentinel missing");
            }
        } catch(const std::exception& error) {errors.emplace_back(std::string("Lifecycle native case exception: ")+error.what());}
        if(errors.empty()) {positive?++matched:++policy;}
        auto row=observations.make_obj();row.set("id",id);row.set("input_sha256",loom::utils::crypto::sha256(source));
        row.set("positive_drawing_obligation",positive);row.set("source_fallback",fallback);row.set("native_profile_pass",errors.empty());
        row.set("wide_cells_sha256",wide_hash);row.set("narrow_cells_sha256",narrow_hash);row.set("restored_cells_sha256",restored_hash);
        row.set("original_assertion_port","pending_complete_predicate_API_and_ASCII_conditional_mapping");
        if(terminal_projection){row.set("terminal_projection_asset_sha256",std::string(kGoEofTerminalSha));row.set("original_source_policy",c.get_string("expected"));row.set("original_Go_error_predicate","must be followed by a message: foreign API debt retained");}
        auto failures=row.make_arr();for(const auto& error:errors) {failures.append(row.make_str(error));ADD_FAILURE()<<error;}
        row.add("errors",failures);observations.append(row);
    });
    EXPECT_EQ(seen,24);EXPECT_EQ(positives,15);EXPECT_EQ(negatives,9);EXPECT_EQ(terminal_selected,1);EXPECT_EQ(terminal_mutated,1);
    root.set("terminal_projection_asset_sha256",std::string(kGoEofTerminalSha));root.set("immutable_original_source_policies",10);
    root.set("positive_obligations",positives);root.set("negative_source_policies",negatives);root.set("candidate_drawings",drawn);
    root.set("native_geometry_matches",matched);root.set("native_source_policy_matches",policy);root.add("cases",observations);report.set_root(root);
    std::filesystem::create_directories(LOOM_MERMAID_REPORT_DIR);
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-lifecycle-union24-semantics.json");
    output<<report.to_string()<<'\n';ASSERT_TRUE(output.good());
}

TEST(MermaidLifecycleOracle, FrozenGoCodecPreservesEverySourceReviewedLifetimeModelField) {
    const auto bytes=fixture_bytes("mermaid_native/sequence_lifecycle_union24_facts.json");
    ASSERT_EQ(loom::utils::crypto::sha256(bytes),kLifecycleFactsSha);
    const auto source_facts=json::parse(bytes);
    const auto vendor=json::parse(fixture_bytes("mermaid_terminal/mermaid_ascii/cases.json"));
    const auto supplements=json::parse(fixture_bytes("mermaid_native/sequence_go_facts.json"));
    ASSERT_TRUE(source_facts&&vendor&&supplements);
    std::map<std::string,JsonVal> originals,roles;
    vendor->root().get("cases").iter([&](JsonVal c){originals.emplace(c.get_string("id"),c);});
    supplements->root().get("cases").iter([&](JsonVal c){roles.emplace(c.get_string("id"),c);});
    int count=0,creates=0,destroys=0;
    source_facts->root().get("cases").iter([&](JsonVal c) {
        if(!c.get("frozen_bindings").size()) return;
        ++count;const auto id=c.get_string("id");SCOPED_TRACE(id);
        ASSERT_TRUE(originals.contains(id)&&roles.contains(id));
        const auto converted=go_model(originals.at(id).get("expectation").get("semantic_model"),roles.at(id));
        const auto expected=lifecycle_fact_model(c.get("model"));const auto& actual=converted.simple;
        EXPECT_TRUE(converted.pending.empty());EXPECT_FALSE(converted.valid_empty);
        ASSERT_EQ(actual.actors.size(),expected.actors.size());
        for(std::size_t n=0;n<expected.actors.size();++n) {
            EXPECT_EQ(actual.actors[n].id,expected.actors[n].id);EXPECT_EQ(actual.actors[n].label,expected.actors[n].label);
            EXPECT_EQ(actual.actors[n].role,expected.actors[n].role);
        }
        ASSERT_EQ(actual.messages.size(),expected.messages.size());
        for(std::size_t n=0;n<expected.messages.size();++n) {
            const auto& a=actual.messages[n];const auto& e=expected.messages[n];
            EXPECT_EQ(a.from,e.from);EXPECT_EQ(a.to,e.to);EXPECT_EQ(a.label,e.label);EXPECT_EQ(a.dashed,e.dashed);
            EXPECT_EQ(a.arrow,e.arrow);EXPECT_EQ(a.central_from,e.central_from);EXPECT_EQ(a.central_to,e.central_to);EXPECT_EQ(a.number,e.number);
        }
        ASSERT_EQ(actual.notes.size(),expected.notes.size());
        for(std::size_t n=0;n<expected.notes.size();++n) {
            const auto& a=actual.notes[n];const auto& e=expected.notes[n];
            EXPECT_EQ(a.actors,e.actors);EXPECT_EQ(a.text,e.text);EXPECT_EQ(a.position,e.position);EXPECT_EQ(a.after,e.after);
        }
        ASSERT_EQ(actual.fragments.size(),expected.fragments.size());
        for(std::size_t n=0;n<expected.fragments.size();++n) {
            const auto& a=actual.fragments[n];const auto& e=expected.fragments[n];
            EXPECT_EQ(a.kind,e.kind);EXPECT_EQ(a.label,e.label);EXPECT_EQ(a.parent,e.parent);EXPECT_EQ(a.dividers,e.dividers);
        }
        ASSERT_EQ(actual.boxes.size(),expected.boxes.size());
        for(std::size_t n=0;n<expected.boxes.size();++n) {
            const auto& a=actual.boxes[n];const auto& e=expected.boxes[n];
            EXPECT_EQ(a.actors,e.actors);EXPECT_EQ(a.title,e.title);EXPECT_EQ(a.color,e.color);
        }
        // Compare every ordered source event, including its actor identity and
        // divider part; retaining a pending flag cannot substitute for mapping.
        ASSERT_EQ(actual.order.size(),expected.order.size());
        for(std::size_t n=0;n<expected.order.size();++n) {
            EXPECT_EQ(actual.order[n].kind,expected.order[n].kind);EXPECT_EQ(actual.order[n].index,expected.order[n].index);
            EXPECT_EQ(actual.order[n].part,expected.order[n].part);
            creates+=actual.order[n].kind==EventKind::Create;destroys+=actual.order[n].kind==EventKind::Destroy;
        }
    });
    EXPECT_EQ(count,6);EXPECT_EQ(creates,5);EXPECT_EQ(destroys,6);
}

TEST(MermaidSequenceSemantics, LifetimeSourceEpisodesKeepNestedStripsSelfReturnsAndEmptyBirths) {
    auto check=[](const std::string& source,const Model& expected) {
        SCOPED_TRACE(source);Work work{8000000};check_event_model(expected,work);
        const auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        const auto text=loom::ui::render_markdown(fenced(source,"text"));
        const auto wide=capture(element,240,1040),narrow=capture(element,40,1040),restored=capture(element,240,1040);
        ASSERT_FALSE(wide==capture(text,240,1040));
        for(const auto& error:validate(wide,expected)) ADD_FAILURE()<<error;
        if(narrow!=capture(text,40,1040)) for(const auto& error:validate(narrow,expected)) ADD_FAILURE()<<error;
        EXPECT_TRUE(restored==wide);
        for(const auto* frame:{&wide,&narrow,&restored}) {
            bool sentinel=false;for(int y=0;y<frame->height;++y) sentinel|=frame->row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
    };
    const std::string prefix="sequenceDiagram\nparticipant A\nA->>A: before\ncreate actor B as New\nparticipant C\n";
    for(const bool automatic_close:{false,true}) {
        Model expected{{{"A","A"},{"B","New",Role::Actor},{"C","C"}},
            {{0,0,"before",false},{0,1,"born",false},{1,automatic_close?0:1,"leave",false},{0,2,"after",false}},{}};
        expected.order={{EventKind::Message,0},{EventKind::Create,1},{EventKind::Message,1},
            {EventKind::Activate,1},{EventKind::Activate,1},{EventKind::Message,2}};
        if(automatic_close) expected.order.push_back({EventKind::Deactivate,1});
        expected.order.insert(expected.order.end(),{{EventKind::Destroy,1},{EventKind::Message,3}});
        check(prefix+"A->>+B: born\nactivate B\ndestroy B\n"+
            (automatic_close?"B->>-A: leave\n":"B->>B: leave\n")+"A->>C: after",expected);
    }
    Model empty{{{"A","A"},{"B","New",Role::Actor},{"C","C"}},
        {{0,0,"before",false},{0,1,"",false},{1,0,"ready",false},{1,1,"leave",true},{0,2,"after",false}},{}};
    empty.order={{EventKind::Message,0},{EventKind::Create,1},{EventKind::Message,1},{EventKind::Message,2},
        {EventKind::Message,3},{EventKind::Destroy,1},{EventKind::Message,4}};
    check(prefix+"A->>B:\nB->>A: ready\ndestroy B\nB-->>B: leave\nA->>C: after",empty);
}
TEST(MermaidSequenceSemantics, NativeLifetimePolicyKeepsLatestSignalsAndRejectsPrematureUse) {
    // Native whole-source policy guards are separate from the immutable
    // original parser's exact error-substring and ASCII obligations.
    const std::string prefix="sequenceDiagram\nA->>B: hi\n";
    for(const auto tail:{"destroy B\nA->>B: bye\nA->>B: late",
        "destroy B\nA->>B: bye\nactivate B",
        "destroy B\nA->>B: bye\ndestroy B\nA->>B: twice",
        "destroy B\nA->>B: bye\ncreate participant B\nA->>B: again",
        "create participant C\nactivate C\nA->>C: born",
        "create actor C\nNote over C: early\nA->>C: born"}) {
        const auto source=prefix+tail;SCOPED_TRACE(source);
        const auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        const auto text=loom::ui::render_markdown(fenced(source,"text"));
        for(const int width:{240,40,240}) {
            const auto frame=capture(element,width,1040);EXPECT_TRUE(frame==capture(text,width,1040));
            bool sentinel=false;for(int y=0;y<frame.height;++y) sentinel|=frame.row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
    }
    // A destroyed actor still names a Note anchor, without continuing its rail.
    // Keep this exact former source control as a whole-scene positive.
    Model late{{{"A","A"},{"B","B"}},{{0,1,"hi",false},{0,1,"bye",false}},
        {{{1},"late","over",1}}};
    late.order={{EventKind::Message,0},{EventKind::Message,1},
        {EventKind::Destroy,1},{EventKind::Note,0}};
    EXPECT_TRUE(dead_note_public(prefix+"destroy B\nA->>B: bye\nNote over B: late",late));
    // The original pending setter replaces a previous same-kind signal. Keep
    // these exact former source controls as complete positive geometry gates.
    Model born{{{"A","A"},{"B","B"},{"C","C"},{"D","D"}},
        {{0,1,"hi",false},{0,3,"born",false}},{}};
    born.order={{EventKind::Message,0},{EventKind::Create,3},{EventKind::Message,1}};
    Model dead{{{"A","A"},{"B","B"}},
        {{0,1,"hi",false},{0,1,"bye",false}},{}};
    dead.order={{EventKind::Message,0},{EventKind::Message,1},{EventKind::Destroy,1}};
    for(const auto& [tail,expected]:std::array<std::pair<std::string_view,Model>,2>{{
        {"create participant C\ncreate participant D\nA->>D: born",born},
        {"destroy A\ndestroy B\nA->>B: bye",dead}}}) {
        const auto source=prefix+std::string(tail);SCOPED_TRACE(source);
        Work work;check_event_model(expected,work);
        const auto node=loom::ui::render_markdown(fenced(source,"mermaid"));
        const auto plain=loom::ui::render_markdown(fenced(source,"text"));
        const auto wide=capture(node,240,1040),narrow=capture(node,40,1040),restored=capture(node,240,1040);
        ASSERT_FALSE(wide==capture(plain,240,1040));
        for(const auto& error:validate(wide,expected)) ADD_FAILURE()<<error;
        if(narrow!=capture(plain,40,1040))
            for(const auto& error:validate(narrow,expected)) ADD_FAILURE()<<error;
        EXPECT_TRUE(restored==wide);
        EXPECT_TRUE(complete_sequence_sentinel(wide));
        EXPECT_TRUE(complete_sequence_sentinel(narrow));
        EXPECT_TRUE(complete_sequence_sentinel(restored));
    }
}

TEST(MermaidLifecycleOracle, ExplicitNestedCapMayShareTheDestroyedParentsLastLiveRow) {
    // Independent cells: two nested activations, the child explicitly closes
    // on the parent's last live row, then a separate death marker ends parent.
    Grid scene{60,28,std::vector<std::string>(1680," ")};
    for(int y=0;y<28;++y) scene.put(8,y,"│");
    for(int y=5;y<=15;++y) scene.put(36,y,"│");
    for(int y=8;y<=15;++y) scene.put(36,y,"┃");
    for(int y=11;y<=15;++y) scene.put(38,y,"┃");
    scene.text(35,8,"╺╋╸");scene.text(35,11,"╺╋━┳╸");scene.text(35,15,"╺╋━┻╸");scene.put(36,16,"×");
    const std::vector<ActiveStrip> strips{{1,1,8,15,StripEnd::Destruction},{1,2,11,15,StripEnd::Cap}};
    const std::vector<LifeInterval> lives{{0,27},{5,15,16}};
    auto check=[&](const Grid& g,const std::vector<ActiveStrip>& s,const std::vector<LifeInterval>& l) {
        Work work{8000000};return activation_component_core(g,{8,36},s,work,l);
    };
    EXPECT_TRUE(check(scene,strips,lives).empty());
    auto lost_cap=scene;lost_cap.text(35,15," ┃ ┃ ");EXPECT_FALSE(check(lost_cap,strips,lives).empty());
    auto lost_marker=scene;lost_marker.put(36,16," ");EXPECT_FALSE(check(lost_marker,strips,lives).empty());
    auto ghost=scene;ghost.put(38,17,"┃");EXPECT_FALSE(check(ghost,strips,lives).empty());
    auto wrong=lives;wrong[1].death=17;EXPECT_FALSE(check(scene,strips,wrong).empty());
    auto phantom=strips;phantom[0].end=StripEnd::Cap;EXPECT_FALSE(check(scene,phantom,lives).empty());
    phantom=strips;phantom[1].end=StripEnd::Destruction;EXPECT_FALSE(check(scene,phantom,lives).empty());
    phantom=strips;phantom[0].finish=14;EXPECT_FALSE(check(scene,phantom,lives).empty());
}

TEST(MermaidSequenceSemantics, SourceReviewedOfficialLifecycleBodyPreservesEveryRoleAndLifetime) {
    const auto bytes=fixture_bytes("mermaid_native/sequence_official_lifecycle_facts.json");
    ASSERT_EQ(loom::utils::crypto::sha256(bytes),"5e5c7dd947af547fcf03ee3878cc9a8f9264ddef40b629fdd220eb60d0fb545f");
    const auto doc=json::parse(bytes);ASSERT_TRUE(doc);ASSERT_EQ(doc->root().get("cases").size(),1u);
    int actors=0,messages=0,events=0,creates=0,destroys=0,statements=0;
    doc->root().get("cases").iter([&](JsonVal c) {
        SCOPED_TRACE(c.get_string("path"));
        const auto raw=fixture_bytes("mermaid_official/cases/"+c.get_string("path"));
        ASSERT_EQ(loom::utils::crypto::sha256(raw),c.get_string("raw_sha256"));
        const auto offset=static_cast<std::size_t>(c.get_int("body_offset_utf8_bytes"));ASSERT_LE(offset,raw.size());
        const auto body=raw.substr(offset);ASSERT_EQ(loom::utils::crypto::sha256(body),c.get_string("body_sha256"));
        for(const auto key:{"complete_source_rows","lifecycle_source_witnesses"}) c.get(key).iter([&](JsonVal witness) {
            const auto at=static_cast<std::size_t>(witness.get_int("offset_utf8_bytes"));const auto text=witness.get_string("text");
            ASSERT_LE(at,body.size());EXPECT_EQ(body.substr(at,text.size()),text);
            EXPECT_EQ(loom::utils::crypto::sha256(text),witness.get_string("sha256"));
            if(std::string_view(key)=="lifecycle_source_witnesses") ++statements;
        });
        const auto expected=lifecycle_fact_model(c.get("model"));
        actors+=static_cast<int>(expected.actors.size());messages+=static_cast<int>(expected.messages.size());events+=static_cast<int>(expected.order.size());
        for(const auto event:expected.order) {creates+=event.kind==EventKind::Create;destroys+=event.kind==EventKind::Destroy;}
        const auto element=loom::ui::render_markdown(fenced(body,"mermaid"));
        const auto text=loom::ui::render_markdown(fenced(body,"text"));
        const auto wide=capture(element,240,512),narrow=capture(element,40,512),restored=capture(element,240,512);
        ASSERT_FALSE(wide==capture(text,240,512));
        for(const auto& error:validate(wide,expected)) ADD_FAILURE()<<error;
        if(narrow!=capture(text,40,512)) for(const auto& error:validate(narrow,expected)) ADD_FAILURE()<<error;
        EXPECT_TRUE(restored==wide);
        for(const auto* frame:{&wide,&narrow,&restored}) {
            bool sentinel=false;for(int y=0;y<frame->height;++y) sentinel|=frame->row(y).find(kSentinel)!=std::string::npos;
            EXPECT_TRUE(sentinel);
        }
        // The raw description/frontmatter is a separate unsupported contract.
        if (!description77_legacy_raw(raw)) {
            const auto raw_element=loom::ui::render_markdown(fenced(raw,"mermaid"));
            const auto raw_text=loom::ui::render_markdown(fenced(raw,"text"));
            for(int width:{240,40,240}) EXPECT_TRUE(capture(raw_element,width,512)==capture(raw_text,width,512));
        }
    });
    EXPECT_EQ(actors,5);EXPECT_EQ(messages,10);EXPECT_EQ(events,16);EXPECT_EQ(creates,3);EXPECT_EQ(destroys,3);EXPECT_EQ(statements,6);
}

namespace {
Grid prepend_source_title(const Grid& body,const std::string& title) {
    const auto lines=rows(title);int width=body.width;
    for(const auto& line:lines) width=std::max(width,ftxui::string_width(line));
    const int offset=static_cast<int>(lines.size())+1;
    Grid result{width,body.height+offset,std::vector<std::string>(static_cast<std::size_t>(width*(body.height+offset))," ")};
    for(std::size_t y=0;y<lines.size();++y) result.text(0,static_cast<int>(y),lines[y]);
    for(int y=0;y<body.height;++y) for(int x=0;x<body.width;++x) result.put(x,y+offset,body.at(x,y));
    return result;
}
}
