    EXPECT_TRUE(mapped.simple.notes.empty()&&expected.notes.empty());EXPECT_TRUE(mapped.simple.fragments.empty()&&expected.fragments.empty());
    EXPECT_TRUE(mapped.simple.boxes.empty()&&expected.boxes.empty());
