bool complete_sequence_sentinel(const Grid& grid) {
    int count=0;
    for(int y=0;y<grid.height;++y) {
        if(!grid.row(y).starts_with(kSentinel)) continue;
        bool complete=static_cast<std::size_t>(grid.width)>=kSentinel.size();
        for(int x=0;x<grid.width&&complete;++x) {
            const auto at=static_cast<std::size_t>(x);
            complete=grid.at(x,y)==(at<kSentinel.size()?kSentinel.substr(at,1):std::string_view{" "});
        }
        if(complete) ++count;
    }
    return count==1;
}
TEST(MermaidSequenceOracle, CompleteCore402FactsKeepAllSourcesAndExplicitNullModels) {
    const auto bytes=fixture_bytes(kCore402FactsPath);
    ASSERT_EQ(loom::utils::crypto::sha256(bytes),kCore402FactsSha);
    const auto facts=json::parse(bytes);ASSERT_TRUE(facts);
    const auto root=facts->root();ASSERT_EQ(root.get("cases").size(),402u);
    std::set<std::string> ids,inputs;int models=0,pending=0,drawings=0,empty=0;
    int actors=0,messages=0,notes=0,events=0;
    for(const auto vendor:kSequenceVendors) {
        const std::string relative="mermaid_terminal/"+std::string(vendor)+"/cases.json";
        const auto manifest=fixture_bytes(relative),manifest_sha=loom::utils::crypto::sha256(manifest);
        const auto original=json::parse(manifest);ASSERT_TRUE(original);
        root.get("cases").iter([&](JsonVal c) {
            if(c.get_string("vendor")!=vendor) return;
            const auto id=c.get_string("id"),source=c.get_string("input");SCOPED_TRACE(id);
            EXPECT_TRUE(ids.insert(id).second);inputs.insert(c.get_string("input_sha256"));
            EXPECT_EQ(c.get_string("manifest"),"tests/fixtures/"+relative);
            EXPECT_EQ(c.get_string("manifest_sha256"),manifest_sha);
            EXPECT_EQ(loom::utils::crypto::sha256(source),c.get_string("input_sha256"));
            const auto member=pointer(original->root(),c.get_string("json_pointer"));
            EXPECT_EQ(member.get_string("family"),"sequence");EXPECT_EQ(member.get_string("id"),id);
            EXPECT_EQ(member.get_string("input"),source);EXPECT_EQ(member.get_string("sha256"),c.get_string("input_sha256"));
            c.get("complete_source_statement_witnesses").iter([&](JsonVal w) {
                const auto at=static_cast<std::size_t>(w.get_int("offset_utf8_bytes"));const auto text=w.get_string("text");
                ASSERT_LE(at,source.size());ASSERT_LE(text.size(),source.size()-at);
                EXPECT_EQ(source.substr(at,text.size()),text);EXPECT_EQ(loom::utils::crypto::sha256(text),w.get_string("sha256"));
            });
            const auto meaning=c.get("model");
            if(!meaning.is_obj()) {
                ++pending;EXPECT_TRUE(meaning.is_null());EXPECT_TRUE(c.get("blocker").is_obj());return;
            }
            ++models;
            EXPECT_EQ(loom::utils::crypto::sha256(canonical_json(meaning)),c.get_string("candidate_model_sha256"));
            const auto m=lifecycle_fact_model(meaning);
            actors+=static_cast<int>(m.actors.size());messages+=static_cast<int>(m.messages.size());
            notes+=static_cast<int>(m.notes.size());events+=static_cast<int>(m.order.size());
            EXPECT_TRUE(m.fragments.empty());EXPECT_TRUE(m.boxes.empty());
            int preceding_messages=0;
            for(const auto event:m.order) {
                if(event.kind==EventKind::Message) ++preceding_messages;
                if(event.kind==EventKind::Note) {
                    // Native Note.after is a preceding-message index, not a count.
                    ASSERT_GE(event.index,0);ASSERT_LT(static_cast<std::size_t>(event.index),m.notes.size());
                    EXPECT_EQ(m.notes[static_cast<std::size_t>(event.index)].after,preceding_messages-1);
                }
            }
            const auto classification=c.get_string("source_classification");
            if(classification=="valid_empty") {
                ++empty;EXPECT_TRUE(m.actors.empty()&&m.messages.empty()&&m.notes.empty()&&m.order.empty()&&m.title.empty());
            } else {++drawings;EXPECT_EQ(classification,"drawing");EXPECT_FALSE(m.actors.empty());}
            EXPECT_FALSE(c.get("native_complete_original_predicate_certification").as_bool());
        });
    }
    EXPECT_EQ(ids.size(),402u);EXPECT_EQ(inputs.size(),386u);EXPECT_EQ(models,249);EXPECT_EQ(pending,153);
    EXPECT_EQ(drawings,247);EXPECT_EQ(empty,2);EXPECT_EQ(actors,527);EXPECT_EQ(messages,543);EXPECT_EQ(notes,79);EXPECT_EQ(events,622);
}
