TEST(MermaidSequenceOracle, DecodesExactDisplayNumbersWithoutTruncatingJsonFractionsOrTypes) {
    const auto doc=json::parse(R"({"zero":0,"integer":12,"empty":"","decimal":"10.11","scientific":"1e+21",
        "fraction":1.25,"negative":-1,"boolean":true,"null":null,"object":{},"array":[]})");
    ASSERT_TRUE(doc.has_value());const auto root=doc->root();
    EXPECT_EQ(fact_number(root.get("zero")),"");EXPECT_EQ(fact_number(root.get("integer")),"12");
    EXPECT_EQ(fact_number(root.get("empty"),NumberFactEncoding::DisplayText),"");
    EXPECT_EQ(fact_number(root.get("decimal"),NumberFactEncoding::DisplayText),"10.11");
    EXPECT_EQ(fact_number(root.get("scientific"),NumberFactEncoding::DisplayText),"1e+21");
    for(const auto key:{"empty","decimal","scientific"}) EXPECT_THROW(static_cast<void>(fact_number(root.get(key))),std::runtime_error);
    for(const auto key:{"zero","integer"}) EXPECT_THROW(static_cast<void>(fact_number(root.get(key),NumberFactEncoding::DisplayText)),std::runtime_error);
    for(const auto key:{"fraction","negative","boolean","null","object","array","missing"}) {
        SCOPED_TRACE(key);EXPECT_THROW(static_cast<void>(fact_number(root.get(key))),std::runtime_error);
        EXPECT_THROW(static_cast<void>(fact_number(root.get(key),NumberFactEncoding::DisplayText)),std::runtime_error);
    }
}

