TEST(MermaidSequenceSemantics, InlineTitleWhitespaceKeepsExactlyOneGrammarSeparatorAndLogicalTrailingExtent) {
    struct Witness {std::string statement,value,wrong_visible_whitespace;};
    const std::vector<Witness> witnesses{
        {"title Plain","Plain"," Plain"},
        {"title  Leading"," Leading","Leading"},
        {"title   Leading","  Leading"," Leading"},
        {"title Wide  Gap","Wide  Gap","Wide Gap"},
        {"title Tail  ","Tail  ",""},
        {"TITLE:  Ready  "," Ready  ","Ready  "},
        {"TiTlE:\tReady","Ready"," Ready"},
        {"title\t  Pad  ","  Pad  "," Pad  "},
        {"TiTlE   Mixed  Case ","  Mixed  Case ","  Mixed Case "},
        {"  title   Indented  ","  Indented  "," Indented  "}};
    int complete=0;
    for(const auto& witness:witnesses) {
        SCOPED_TRACE(witness.statement);
        // Literal title cells are authored on the preexisting independent
        // complete two-message scene. No renderer output supplies the oracle.
        auto handmade_model=ordinary_model();handmade_model.title=witness.value;
        const auto handmade=prepend_source_title(ordinary(),witness.value);
        EXPECT_TRUE(validate(handmade,handmade_model).empty());
        if(!witness.wrong_visible_whitespace.empty()) {
            auto wrong=handmade_model;wrong.title=witness.wrong_visible_whitespace;
            EXPECT_FALSE(validate(handmade,wrong).empty());
            const auto collapsed=prepend_source_title(ordinary(),wrong.title);
            EXPECT_FALSE(validate(collapsed,handmade_model).empty());
        }
        auto shifted=handmade_model;shifted.title=" "+witness.value;
        EXPECT_FALSE(validate(handmade,shifted).empty());
        auto missing=handmade_model;missing.title.clear();
        EXPECT_FALSE(validate(handmade,missing).empty());
        const auto expected=title5_basic_model(witness.value);
        const auto source="sequenceDiagram\n"+witness.statement+"\nA->>B: one\n";
        complete+=title5_expect_complete_public_scene(source,expected)?1:0;
    }
    EXPECT_EQ(complete,static_cast<int>(witnesses.size()));

    // Ordinary trailing blank cells equal canvas padding. They cannot alone
    // distinguish a trimmed Model. Use the existing public adaptive width gate:
    // 64 real title cells plus two authored spaces have logical width66.
    const std::string base="0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_-";
    ASSERT_EQ(base.size(),64u);
    const auto title=base+"  ";
    ASSERT_EQ(ftxui::string_width(title),66);
    const auto expected=title5_basic_model(title);
    const std::vector<std::string> padded_sources{
        "sequenceDiagram\ntitle "+title+"\nA->>B: one\n",
        "sequenceDiagram\nTiTlE:\t"+title+"\nA->>B: one\n",
        "sequenceDiagram\nA->>B: one\ntitle "+title};
    for(const auto& source:padded_sources) {
        SCOPED_TRACE(source);
        EXPECT_TRUE(title5_expect_complete_public_scene(source,expected));
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        auto ordinary_source=loom::ui::render_markdown(fenced(source,"text"));
        const auto exact=capture(element,66,140),exact_plain=capture(ordinary_source,66,140);
        EXPECT_FALSE(exact==exact_plain);
        EXPECT_TRUE(validate(exact,expected).empty());
        const auto below=capture(element,65,140),below_plain=capture(ordinary_source,65,140);
        EXPECT_TRUE(below==below_plain)<<"Two trailing title spaces must count toward adaptive width";
        const auto restored=capture(element,66,140);
        EXPECT_TRUE(restored==exact);
        EXPECT_TRUE(validate(restored,expected).empty());
        for(const auto* image:{&exact,&below,&restored}) EXPECT_TRUE(complete_sequence_sentinel(*image));
        // This wrong whitespace Model requires a drawing at65, whereas the
        // same correct source must preserve whole-source fallback at65.
        auto trimmed_model=expected;trimmed_model.title=base;
        EXPECT_FALSE(validate(below,trimmed_model).empty());
    }
    const auto trimmed_source="sequenceDiagram\ntitle "+base+"\nA->>B: one\n";
    const auto trimmed_model=title5_basic_model(base);
    EXPECT_TRUE(title5_expect_complete_public_scene(trimmed_source,trimmed_model));
    auto trimmed_element=loom::ui::render_markdown(fenced(trimmed_source,"mermaid"));
    auto trimmed_plain=loom::ui::render_markdown(fenced(trimmed_source,"text"));
    const auto trimmed65=capture(trimmed_element,65,140);
    EXPECT_FALSE(trimmed65==capture(trimmed_plain,65,140));
    EXPECT_TRUE(validate(trimmed65,trimmed_model).empty());
    EXPECT_TRUE(complete_sequence_sentinel(trimmed65));

    // Existing punctuation identifiers are not standalone title statements.
    // These two old-valid public sources must still draw on the old producer.
    int identifiers_complete=0;
    for(const std::string& id:std::vector<std::string>{"title-service","title.svc"}) {
        SCOPED_TRACE(id);
        Model actor_model{{{id,id},{"B","B"}},{{0,1,"one",false}},{}};
        actor_model.order={{EventKind::Message,0}};
        identifiers_complete+=title5_expect_complete_public_scene(
            "sequenceDiagram\n"+id+"->>B: one",actor_model)?1:0;
    }
    EXPECT_EQ(identifiers_complete,2);

    // The first delimiter TAB is syntax, as proved by the positives above.
    // A remaining TAB belongs to title DATA and is an undisclosed control under
    // the existing native title profile. This does not call it invalid Mermaid.
    const std::vector<std::string> deferred{
        "sequenceDiagram\ntitle \tBody\nA->>B: one\n",
        "sequenceDiagram\ntitle\t\tBody\nA->>B: one\n",
        "sequenceDiagram\ntitle Body\t\nA->>B: one\n",
        "sequenceDiagram\nTiTlE:\tBody\t\nA->>B: one\n",
        "sequenceDiagram\ntitle\xc2\xa0" "Body\nA->>B: one\n"};
    for(const auto& source:deferred) {
        SCOPED_TRACE(source);
        auto element=loom::ui::render_markdown(fenced(source,"mermaid"));
        auto ordinary_source=loom::ui::render_markdown(fenced(source,"text"));
        const auto wide=capture(element,240,140),plain=capture(ordinary_source,240,140);
        const auto narrow=capture(element,40,140),plain_narrow=capture(ordinary_source,40,140);
        const auto restored=capture(element,240,140);
        EXPECT_TRUE(wide==plain);EXPECT_TRUE(narrow==plain_narrow);EXPECT_TRUE(restored==wide);
        for(const auto* image:{&wide,&narrow,&restored}) EXPECT_TRUE(complete_sequence_sentinel(*image));
    }
}
