Model text7_basic(std::string label) {
    Model m{{{"A","A"},{"B","B"}},{{0,1,std::move(label),false}},{}};
    m.order={{EventKind::Message,0}};return m;
}
void text7_clear(Grid& grid,int y,int first,int last) {
    for(int x=first;x<last;++x) grid.put(x,y," ");
}
Grid text7_wide_hand() {
    Grid g{64,14,std::vector<std::string>(64u*14u," ")};
    g.text(0,0,"┌─────┐");g.text(0,1,"│ A   │");g.text(0,2,"└─────┘");
    g.text(52,0,"┌─────┐");g.text(52,1,"│ B   │");g.text(52,2,"└─────┘");
    for(int y=3;y<14;++y) {g.put(3,y,"│");g.put(55,y,"│");}
    g.text(3,6,"├");for(int x=4;x<55;++x) g.put(x,6,"─");g.put(55,6,"▶");
    g.put(3,10,"◀");for(int x=4;x<55;++x) g.put(x,10,"┄");g.put(55,10,"┤");
    g.text(5,9,"reply");return g;
}

TEST(MermaidSequenceOracle, SevenTextSourcesKeepEveryFrozenModelAndPhysicalStatementBinding) {
    const auto bytes=fixture_bytes(kCoreNext20FactsPath);
    ASSERT_EQ(loom::utils::crypto::sha256(bytes),kCoreNext20FactsSha);
    const auto facts=json::parse(bytes),literal=json::parse(kText7Expectations);ASSERT_TRUE(facts);ASSERT_TRUE(literal);
    std::map<std::string,JsonVal> wanted;
    literal->root().get("cases").iter([&](JsonVal row) {ASSERT_TRUE(wanted.emplace(row.get_string("id"),row).second);});
    ASSERT_EQ(wanted.size(),7u);std::set<std::string> found;
    int actors=0,messages=0,notes=0,events=0,entities=0,hash=0,br=0;
    facts->root().get("cases").iter([&](JsonVal row) {
        const auto id=row.get_string("id");if(!wanted.contains(id)) return;
        SCOPED_TRACE(id);ASSERT_TRUE(found.insert(id).second);const auto expected=wanted.at(id);
        EXPECT_EQ(row.get_string("feature"),expected.get_string("feature"));
        EXPECT_EQ(row.get_string("input"),expected.get_string("input"));
        EXPECT_EQ(row.get_string("input_sha256"),expected.get_string("input_sha256"));
        const auto source=row.get_string("input");
        EXPECT_EQ(loom::utils::crypto::sha256(source),expected.get_string("input_sha256"));
        ASSERT_TRUE(row.get("model").is_obj());ASSERT_TRUE(expected.get("model").is_obj());
        EXPECT_EQ(canonical_json(row.get("model")),canonical_json(expected.get("model")));
        EXPECT_EQ(loom::utils::crypto::sha256(canonical_json(row.get("model"))),expected.get_string("model_sha256"));
        const auto m=lifecycle_fact_model(expected.get("model"),NumberFactEncoding::LegacyInteger);
        actors+=static_cast<int>(m.actors.size());messages+=static_cast<int>(m.messages.size());
        notes+=static_cast<int>(m.notes.size());events+=static_cast<int>(m.order.size());
        entities+=row.get_string("feature")=="entities";hash+=row.get_string("feature")=="hash_comment";
        br+=row.get_string("feature")=="explicit_break_whitespace";
        EXPECT_TRUE(m.title.empty());EXPECT_TRUE(m.fragments.empty());EXPECT_TRUE(m.boxes.empty());
        int preceding=0;
        for(const auto event:m.order) {
            if(event.kind==EventKind::Message) ++preceding;
            if(event.kind==EventKind::Note) {ASSERT_GE(event.index,0);ASSERT_LT(static_cast<std::size_t>(event.index),m.notes.size());EXPECT_EQ(m.notes[static_cast<std::size_t>(event.index)].after,preceding-1);}
        }
        row.get("complete_physical_source_witnesses").iter([&](JsonVal w) {
            const auto offset=static_cast<std::size_t>(w.get_int("offset_utf8_bytes"));const auto text=w.get_string("text");
            ASSERT_LE(offset,source.size());ASSERT_LE(text.size(),source.size()-offset);
            EXPECT_EQ(source.substr(offset,text.size()),text);EXPECT_EQ(loom::utils::crypto::sha256(text),w.get_string("sha256"));
        });
        const auto vendor=fixture_bytes("mermaid_terminal/"+row.get_string("vendor")+"/cases.json");
        EXPECT_EQ(loom::utils::crypto::sha256(vendor),row.get_string("manifest_sha256"));
        const auto imported=json::parse(vendor);ASSERT_TRUE(imported);const auto original=pointer(imported->root(),row.get_string("json_pointer"));
        EXPECT_EQ(original.get_string("id"),id);EXPECT_EQ(original.get_string("input"),source);
        EXPECT_EQ(loom::utils::crypto::sha256(canonical_json(original)),row.get_string("case_sha256"));
        EXPECT_FALSE(row.get("original_predicate_native_certification").as_bool());
    });
    EXPECT_EQ(found.size(),wanted.size());EXPECT_EQ(actors,21);EXPECT_EQ(messages,22);EXPECT_EQ(notes,14);EXPECT_EQ(events,36);
    EXPECT_EQ(entities,5);EXPECT_EQ(hash,1);EXPECT_EQ(br,1);
}

TEST(MermaidSequenceOracle, DecodedEntityScalarsNeedExactHeadersLabelsAndBusinessOrder) {
    auto g=ordinary();auto m=ordinary_model();m.order={{EventKind::Message,0},{EventKind::Message,1}};
    text7_clear(g,1,1,6);text7_clear(g,1,21,26);g.text(2,1,"♥");g.text(22,1,"∞");
    m.actors[0].label="♥";m.actors[1].label="∞";
    text7_clear(g,5,4,23);text7_clear(g,9,4,23);g.text(5,5,"♥ # ; < > ∞");g.text(5,9,"literal <br>");
    m.messages[0].label="♥ # ; < > ∞";m.messages[1].label="literal <br>";
    ASSERT_TRUE(validate(g,m).empty());
    auto bad=g;bad.put(5,5,"♡");EXPECT_FALSE(validate(bad,m).empty());
    bad=g;bad.put(7,5," ");EXPECT_FALSE(validate(bad,m).empty());
    bad=g;bad.put(9,5," ");EXPECT_FALSE(validate(bad,m).empty());
    bad=g;bad.put(13,9," ");EXPECT_FALSE(validate(bad,m).empty());
    auto wrong=m;wrong.actors[0].label="♡";EXPECT_FALSE(validate(g,wrong).empty());
    wrong=m;wrong.messages[0].label="#9829; #35; #59; #lt; #gt; #infin;";EXPECT_FALSE(validate(g,wrong).empty());
    wrong=m;wrong.messages[1].label="literal\n";EXPECT_FALSE(validate(g,wrong).empty());
    wrong=m;wrong.order={{EventKind::Message,1},{EventKind::Message,0}};EXPECT_FALSE(validate(g,wrong).empty());
    EXPECT_FALSE(validate(g,m,100).empty());
}

TEST(MermaidSequenceOracle, ActualBlankRowsAndEscapedBrTabStayDifferentPhysicalText) {
    auto g=ordinary();auto m=ordinary_model();m.order={{EventKind::Message,0},{EventKind::Message,1}};
    text7_clear(g,5,4,23);g.text(6,3,"x");g.text(5,5,"<br>");m.messages[0].label="x\n\n<br>";
    ASSERT_TRUE(validate(g,m).empty());
    auto wrong=m;wrong.messages[0].label="x\n<br>";EXPECT_FALSE(validate(g,wrong).empty());
    wrong=m;wrong.messages[0].label="x\n\n\n";EXPECT_FALSE(validate(g,wrong).empty());
    auto bad=g;bad.put(6,5," ");EXPECT_FALSE(validate(bad,m).empty());
    bad=g;bad.put(5,4,"x");EXPECT_FALSE(validate(bad,m).empty());
    auto literal=text7_wide_hand();auto lm=ordinary_model();lm.order={{EventKind::Message,0},{EventKind::Message,1}};
    lm.messages[0].label=R"(using <br \u{0009}/>)";literal.text(5,5,lm.messages[0].label);
    ASSERT_TRUE(validate(literal,lm).empty());
    wrong=lm;wrong.messages[0].label="using <br \t/>";EXPECT_FALSE(validate(literal,wrong).empty());
    wrong=lm;wrong.messages[0].label=R"(using <br \\u{0009}/>)";EXPECT_FALSE(validate(literal,wrong).empty());
    bad=literal;const int at=5+static_cast<int>(lm.messages[0].label.find(R"(\u{0009})"));
    text7_clear(bad,5,at,at+8);EXPECT_FALSE(validate(bad,lm).empty());
}

bool text7_expect_public(std::string_view source,const Model& m) {
    auto node=loom::ui::render_markdown(fenced(source,"mermaid"));auto ordinary_source=loom::ui::render_markdown(fenced(source,"text"));
    const auto wide=capture(node,240,240),wide_source=capture(ordinary_source,240,240);
    const auto narrow=capture(node,40,240),narrow_source=capture(ordinary_source,40,240),restored=capture(node,240,240);
    const bool fallback=wide==wide_source;EXPECT_FALSE(fallback)<<"Full text source-positive obligation remains unmet";
    bool valid=restored==wide;EXPECT_TRUE(valid);
    for(const auto* image:{&wide,&narrow,&restored}) {const bool ok=complete_sequence_sentinel(*image);EXPECT_TRUE(ok);valid&=ok;}
    // All three actual captures execute even on unsupported wide sources. A
    // source fallback never executes or counts forged geometry as passed.
    if(fallback) return false;
    const auto errors=validate(wide,m);for(const auto& error:errors) ADD_FAILURE()<<error;valid&=errors.empty();
    if(!(narrow==narrow_source)) {const auto e=validate(narrow,m);for(const auto& error:e) ADD_FAILURE()<<error;valid&=e.empty();}
    if(!valid) return false;
    auto rejects=[&](const Model& wrong) {const bool rejected=!validate(wide,wrong).empty();EXPECT_TRUE(rejected);valid&=rejected;};
    for(std::size_t n=0;n<m.actors.size();++n) {auto wrong=m;wrong.actors[n].label+="?";rejects(wrong);}
    for(std::size_t n=0;n<m.messages.size();++n) {
        auto wrong=m;wrong.messages[n].label+="?";rejects(wrong);
        wrong=m;wrong.messages[n].dashed=!wrong.messages[n].dashed;rejects(wrong);
    }
    for(std::size_t n=0;n<m.notes.size();++n) {
        auto wrong=m;wrong.notes[n].text+="?";rejects(wrong);
        wrong=m;wrong.notes[n].after=wrong.notes[n].after==-1?0:-1;rejects(wrong);
    }
    if(!m.messages.empty()) {
        auto wrong=m;wrong.messages.push_back(m.messages.front());wrong.order.push_back({EventKind::Message,static_cast<int>(wrong.messages.size()-1)});rejects(wrong);
        if(m.messages.size()>1) {wrong=m;std::swap(wrong.messages[0],wrong.messages[1]);rejects(wrong);}
    }
    return valid;
}
void text7_expect_source(std::string_view source) {
    auto node=loom::ui::render_markdown(fenced(source,"mermaid"));auto ordinary_source=loom::ui::render_markdown(fenced(source,"text"));
    const auto wide=capture(node,240,240);
    for(const int width:{240,40,240}) {const auto image=capture(node,width,240);EXPECT_TRUE(image==capture(ordinary_source,width,240));EXPECT_TRUE(complete_sequence_sentinel(image));if(width==240) EXPECT_TRUE(image==wide);}
}

TEST(MermaidSequenceSemantics, CompleteSevenReviewedTextSourcesRequireAllModelsAtThreeWidths) {
    const auto bytes=fixture_bytes(kCoreNext20FactsPath);ASSERT_EQ(loom::utils::crypto::sha256(bytes),kCoreNext20FactsSha);
    const auto facts=json::parse(bytes),literal=json::parse(kText7Expectations);ASSERT_TRUE(facts);ASSERT_TRUE(literal);
    std::map<std::string,JsonVal> selected;literal->root().get("cases").iter([&](JsonVal row) {ASSERT_TRUE(selected.emplace(row.get_string("id"),row).second);});
    int executed=0,complete=0;
    facts->root().get("cases").iter([&](JsonVal row) {
        const auto id=row.get_string("id");if(!selected.contains(id)) return;SCOPED_TRACE(id);++executed;
        const auto reference=selected.at(id);ASSERT_EQ(row.get_string("input"),reference.get_string("input"));
        const auto model=reference.get("model");ASSERT_TRUE(model.is_obj());
        complete+=text7_expect_public(row.get_string("input"),lifecycle_fact_model(model,NumberFactEncoding::LegacyInteger))?1:0;
    });
    EXPECT_EQ(executed,7);EXPECT_EQ(complete,7);
}

TEST(MermaidSequenceSemantics, EntityAtomsProtectGrammarAndStandaloneCommentsKeepLaterOrder) {
    const std::string raw="#35; #59; #9829; #lt; #gt; #infin;",shown="# ; ♥ < > ∞";
    Model m{{{"A","♥"},{"B","∞"}},{{0,1,shown,false},{1,0,"later ; intact",true}},{{{0,1},shown,"over",0}}};
    m.order={{EventKind::Message,0},{EventKind::Note,0},{EventKind::Message,1}};
    const std::string source="sequenceDiagram\nparticipant A as #9829;\nparticipant B as #infin;\n# leading standalone comment\nA->>B: "+raw+
        "\nNote over A,B: "+raw+"\n%% another comment\n# Another comment\nB-->>A: later #59; intact\n";
    EXPECT_TRUE(text7_expect_public(source,m));
    auto single=text7_basic("; B->>A: injected");
    EXPECT_TRUE(text7_expect_public("sequenceDiagram\nA->>B: #59; B->>A: injected",single));
    single=text7_basic("# not a comment");
    EXPECT_TRUE(text7_expect_public("sequenceDiagram\nA->>B: #35; not a comment",single));
    single=text7_basic("before ; A->>B: after");
    EXPECT_TRUE(text7_expect_public("sequenceDiagram\nA->>B: before #59; A->>B: after",single));
    single=text7_basic("<br>");
    EXPECT_TRUE(text7_expect_public("sequenceDiagram\nA->>B: #lt;br#gt;",single));
}

TEST(MermaidSequenceSemantics, BrSyntaxWhitespacePrecedesOneEntityDecodeAndSafeDisplay) {
    for(const std::string& tag:{std::string("<br>"),std::string("<br/>"),std::string("<br />"),std::string("<br \t/>")}) {
        SCOPED_TRACE(tag);
        Model m{{{"A","head\nrow"},{"B","B"}},{{0,1,"first\n\nlast",false}},{{{1},"note\nrow","right",0}}};
        m.order={{EventKind::Message,0},{EventKind::Note,0}};
        const auto source="sequenceDiagram\nparticipant A as head"+tag+"row\nparticipant B\nA->>B: first"+tag+tag+"last\nNote right of B: note"+tag+"row";
        EXPECT_TRUE(text7_expect_public(source,m));
    }
    auto literal=text7_basic("x\n\n<br>");
    EXPECT_TRUE(text7_expect_public("sequenceDiagram\nA->>B: x<br><br>#lt;br#gt;",literal));
    literal=text7_basic(R"(using <br \u{0009}/>)");
    EXPECT_TRUE(text7_expect_public("sequenceDiagram\nA->>B: using #lt;br \t/#gt;",literal));
}

TEST(MermaidSequenceResources, UnknownAtomsAndNonBrMarkupRemainCompleteUnreviewedSources) {
    for(const std::string& field:{std::string("#35"),std::string("#59"),std::string("#unknown;"),std::string("&lt;"),
            std::string("#+35;"),std::string("#x23;"),std::string("#0;"),std::string("#128;"),
            std::string("#55296;"),std::string("#1114112;"),std::string("#99999999999999999999999999;"),
            std::string("<b>markup</b>"),std::string("<br class=x>"),std::string("<br"),std::string("<br / >")}) {
        SCOPED_TRACE(field);const auto source="sequenceDiagram\nA->>B: "+field;
        if (!literal6_migrated_public(source)) text7_expect_source(source);
    }
    text7_expect_source("sequenceDiagram\n#35; not a recognized statement\nA->>B: later");
    text7_expect_source("sequenceDiagram\n#unknown; not a statement\nunknown directive\nA->>B: later");
    text7_expect_source("sequenceDiagram\nA->>B: #9829;\nunknown directive");
    EXPECT_TRUE(description77_legacy_raw("---\ndescription: Deferred metadata\n---\nsequenceDiagram\nA->>B: #9829;"));
    text7_expect_source("sequenceDiagram\ntitle #lt;Title#gt;\nA->>B: later");
    // No entity alias is allowed to become structural identifier/grammar input.
    text7_expect_source("sequenceDiagram\n#lt;A#gt;->>B: later");
}

TEST(MermaidSequenceResources, DecodedRowsRetainAggregateByteCanvasAndSharedWorkBounds) {
    auto encoded=[](int n) {std::string text;for(int i=0;i<n;++i) text+="#35;";return text;};
    const std::string left=encoded(128),right=encoded(127);
    Model m{{{"A","A"}},{{0,0,std::string(128,'#')+'\n'+std::string(127,'#'),false}},{}};m.order={{EventKind::Message,0}};
    const auto source="sequenceDiagram\nA->>A: "+left+"<br>"+right;
    EXPECT_TRUE(text7_expect_public(source,m));
    text7_expect_source(source+"#35;"); //128 + break +128 exceeds aggregate256.
    text7_expect_source("sequenceDiagram\nA->>A: "+encoded(241)); //true source width, no clipping permission.
    std::string bounded="sequenceDiagram\n#";
    const std::string suffix="\nA->>A: #9829;";bounded+=std::string(65536-bounded.size()-suffix.size(),'x');bounded+=suffix;
    ASSERT_EQ(bounded.size(),65536u);Model one{{{"A","A"}},{{0,0,"♥",false}},{}};one.order={{EventKind::Message,0}};
    EXPECT_TRUE(text7_expect_public(bounded,one));text7_expect_source(bounded+'\n');
    const auto good=ordinary();const auto expected=ordinary_model();
    EXPECT_TRUE(validate(good,expected).empty());EXPECT_FALSE(validate(good,expected,100).empty());
}
