TEST(MermaidSequenceRoleScene, MultilineWideAliasesKeepContinuationAndAttachedCombiningCellsOwned) {
    Grid good{48,19,std::vector<std::string>(912," ")};
    good.text(5,4,"┌─────┐");good.text(5,5,"│     │");good.text(5,6,"│     │");good.text(5,7,"└─────┘");
    good.text(7,5,"中");good.text(7,6,"文");role_stage2_hand_header(good,29,4,"e\u0301");
    role_stage2_hand_figure(good,Role::Database,8,4);role_stage2_hand_figure(good,Role::Queue,32,4);
    for(int y=8;y<19;++y)good.put(8,y,"│");for(int y=7;y<19;++y)good.put(32,y,"│");
    good.text(10,11,"wide");good.put(8,12,"├");for(int x=9;x<32;++x)good.put(x,12,"─");good.put(32,12,"▶");
    Model model{{{"d","中\n文",Role::Database},{"q","e\u0301",Role::Queue}},{{0,1,"wide",false}},{}};
    const auto errors=validate(good,model);ASSERT_TRUE(errors.empty())<<(errors.empty()?"":errors.front());
    auto bad=good;bad.put(8,5,"x");EXPECT_FALSE(validate(bad,model).empty());
    bad=good;bad.put(7,5," ");EXPECT_FALSE(validate(bad,model).empty());
    bad=good;bad.put(32,5,"e");EXPECT_FALSE(validate(bad,model).empty());
    bad=good;bad.put(32,0,"─");EXPECT_FALSE(validate(bad,model).empty());
    auto wrong=model;wrong.actors[0].label="中 文";EXPECT_FALSE(validate(good,wrong).empty());
    wrong=model;wrong.actors[1].label="e";EXPECT_FALSE(validate(good,wrong).empty());
}
