// The embedded sources/Models are authored from the pinned grammar and native
// profile, before any role producer exists. No default geometry helper changes.
// The original complete31 mutator assumes Message/Note-only Models. A
// lifecycle source must keep its birth/death schedule structurally meaningful
// before a rejected Model can count as evidence about actual geometry.
std::vector<std::string> role_producer_source_mutations(const Grid& good,const Model& model) {
    const bool lifetime=std::ranges::any_of(model.order,[](const OrderedEvent& e) {
        return e.kind==EventKind::Create||e.kind==EventKind::Destroy;
    });
    if(!lifetime)return role_stage2_source_mutations(good,model);
    std::vector<std::string> failures;int valid_mutants=0;
    auto rejects=[&](const Model& wrong,std::string_view detail) {
        Work schema_budget;
        try {check_event_model(wrong,schema_budget);}
        catch(const std::runtime_error&) {
            // In particular, deleting the sole Create-trigger message is not
            // a valid missing-business-geometry adversary. Do not execute or
            // count it. Existing153 lifetime controls are retained unchanged.
            return;
        }
        ++valid_mutants;
        if(validate(good,wrong).empty())failures.emplace_back("Accepted lifecycle source mutation: "+std::string(detail));
    };
    for(std::size_t n=0;n<model.actors.size();++n) {
        auto wrong=model;wrong.actors[n].label+="_wrong";rejects(wrong,"complete actor alias");
        wrong=model;wrong.actors[n].role=wrong.actors[n].role==Role::Participant?Role::Actor:Role::Participant;rejects(wrong,"actual actor role");
    }
    for(std::size_t n=0;n<model.messages.size();++n) {
        auto wrong=model;wrong.messages[n].label+="_wrong";rejects(wrong,"complete message text");
        wrong=model;wrong.messages[n].arrow=wrong.messages[n].arrow==Arrow::Filled?Arrow::Async:Arrow::Filled;rejects(wrong,"business arrow marker");
        wrong=model;wrong.messages[n].dashed=!wrong.messages[n].dashed;rejects(wrong,"business stroke");
        wrong=model;wrong.messages[n].from=(wrong.messages[n].from+1)%static_cast<int>(model.actors.size());rejects(wrong,"different sender identity");
        wrong=model;wrong.messages.erase(wrong.messages.begin()+static_cast<std::ptrdiff_t>(n));
        std::erase_if(wrong.order,[&](const OrderedEvent& e){return e.kind==EventKind::Message&&e.index==static_cast<int>(n);});
        for(auto& e:wrong.order)if(e.kind==EventKind::Message&&e.index>static_cast<int>(n))--e.index;
        for(auto& note:wrong.notes)if(note.after>=static_cast<int>(n))--note.after;
        rejects(wrong,"structurally valid non-trigger message erasure");
    }
    if(valid_mutants<static_cast<int>(2*model.actors.size()+3*model.messages.size()))
        failures.emplace_back("Expected schema-preserving role/text/arrow/stroke adversaries were not executed");
    auto orphan=good;bool changed=false;
    for(int x=good.width-1;x>=0&&!changed;--x)if(good.at(x,0)==" "){orphan.put(x,0,"┼");changed=true;}
    if(!changed)failures.emplace_back("Missing independently observable orphan mutation cell");
    else if(validate(orphan,model).empty())failures.emplace_back("Unclaimed lifecycle role header arm was accepted");
    return failures;
}
void role_producer_expect_public(JsonVal item) {
    const auto source=item.get_string("input");
    ASSERT_EQ(loom::utils::crypto::sha256(source),item.get_string("input_sha256"));
    const auto meaning=item.get("native_model");
    ASSERT_TRUE(meaning.is_obj());
    ASSERT_EQ(loom::utils::crypto::sha256(canonical_json(meaning)),item.get_string("native_model_sha256"));
    const auto model=lifecycle_fact_model(meaning,NumberFactEncoding::DisplayText);
    auto node=loom::ui::render_markdown(fenced(source,"mermaid"));
    auto ordinary=loom::ui::render_markdown(fenced(source,"text"));
    node->ComputeRequirement();
    const int height=std::min(1040,std::max(256,node->requirement().min_y+8));
    const auto wide=capture(node,240,height),plain=capture(ordinary,240,height);
    const auto narrow=capture(node,40,height),plain_narrow=capture(ordinary,40,height);
    const auto restored=capture(node,240,height);
    EXPECT_TRUE(wide==restored);
    for(const auto* frame:{&wide,&narrow,&restored})EXPECT_TRUE(complete_sequence_sentinel(*frame));
    const bool fallback=wide==plain;
    EXPECT_FALSE(fallback)<<"Source-defined role/spacing obligation remains unmet";
    if(fallback)return; // A fallback never executes or counts forged geometry.
    const auto errors=validate(wide,model);
    for(const auto& error:errors)ADD_FAILURE()<<error;
    if(!(narrow==plain_narrow)) {
        const auto narrow_errors=validate(narrow,model);
        for(const auto& error:narrow_errors)ADD_FAILURE()<<error;
    }
    if(errors.empty()) {
        const auto mutations=role_producer_source_mutations(wide,model);
        for(const auto& error:mutations)ADD_FAILURE()<<error;
    }
    const auto legacy=item.get_string("equivalent_legacy_source");
    if(!legacy.empty()) {
        auto old=loom::ui::render_markdown(fenced(legacy,"mermaid"));
        EXPECT_TRUE(wide==capture(old,240,height));
        EXPECT_TRUE(narrow==capture(old,40,height));
        EXPECT_TRUE(restored==capture(old,240,height));
    }
}
void role_producer_batch(std::string_view selected,int expected) {
    const auto bytes=role_producer_case_bytes();
    ASSERT_EQ(loom::utils::crypto::sha256(bytes),kRoleProducerCasesSha);
    const auto parsed=json::parse(bytes);ASSERT_TRUE(parsed);
    ASSERT_EQ(parsed->root().get("cases").size(),89u);
    std::set<std::string> seen;int visited=0;
    parsed->root().get("cases").iter([&](JsonVal item) {
        if(item.get_string("batch")!=selected)return;
        ++visited;const auto id=item.get_string("id");SCOPED_TRACE(id);
        ASSERT_TRUE(seen.insert(id).second);
        const auto source=item.get_string("input");
        ASSERT_EQ(loom::utils::crypto::sha256(source),item.get_string("input_sha256"));
        if(item.get_string("requirement")=="strong_drawing")role_producer_expect_public(item);
        else {
            ASSERT_EQ(item.get_string("requirement"),"whole_source_profile_boundary");
            ASSERT_TRUE(item.get("native_model").is_null());
            text7_expect_source(source);
        }
    });
    EXPECT_EQ(visited,expected);
}
