TEST(MermaidSequenceRoleProducer, SafeUnicodeSelectedAliasesAndResourceLimitsRetainEveryGlyph) {
    role_producer_batch("unicode",9);
    // Malformed UTF-8 is not a JSON escape and cannot become an admitted ID or
    // alias. These literal bytes intentionally cannot live in UTF-8 JSON facts.
    for(const std::string& poison:std::array<std::string,3>{{std::string("\xC0\xAD",2),std::string("\xED\xA0\x80",3),std::string("\xF4\x90\x80\x80",4)}}) {
        text7_expect_source("sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\""+poison+"\"}\nA->>B: ping");
    }
    const std::string over_source="sequenceDiagram\nparticipant A@{\"type\":\"database\"}\nA->>B: ping\n%%"+std::string(65536,'x');
    text7_expect_source(over_source);
}

Grid role_producer_spacing_hand() {
    // Independent semantic witness, not a producer snapshot or exact pixel
    // requirement. Unequal adjacent gaps retain all intervening lifelines.
    Grid g{104,40,std::vector<std::string>(104u*40u," ")};
    const std::array<int,4> centers{{8,34,66,92}};
    const std::array<Role,4> roles{{Role::Control,Role::Participant,Role::Database,Role::Actor}};
    const std::array<std::string_view,4> aliases{{"A","B","C","D"}};
    for(std::size_t n=0;n<centers.size();++n) {
        const int c=centers[n];role_stage2_hand_header(g,c-3,4,aliases[n]);
        role_stage2_hand_figure(g,roles[n],c,4);
        for(int y=7;y<40;++y)g.put(c,y,"│");
    }
    g.text(10,9,"100. abcdefghijklmnopq");g.put(8,10,"├");
    for(int x=9;x<66;++x)g.put(x,10,"─");g.put(34,10,"┼");g.put(66,10,"▶");
    g.text(10,14,"105. reverse");g.put(8,15,"◀");g.put(92,15,"┤");
    for(int x=9;x<92;++x)g.put(x,15,"┄");g.put(34,15,"┼");g.put(66,15,"┼");
    g.text(36,19,"110. self");g.put(34,20,"├");
    for(int x=35;x<46;++x)g.put(x,20,"─");g.put(46,20,"┐");g.put(46,21,"│");
    g.put(34,22,"◀");for(int x=35;x<46;++x)g.put(x,22,"─");g.put(46,22,"┘");
    for(int x=33;x<68;++x){g.put(x,26,"─");g.put(x,28,"─");g.put(x,27," ");}
    g.put(32,26,"┌");g.put(68,26,"┐");g.put(32,28,"└");g.put(68,28,"┘");
    g.put(32,27,"│");g.put(68,27,"│");g.text(45,27,"owned note");
    for(const int c:{34,66}){g.put(c,26,"┴");g.put(c,28,"┬");}
    g.text(68,33,"last");g.put(66,34,"├");for(int x=67;x<92;++x)g.put(x,34,"─");g.put(92,34,"▶");
    return g;
}
Model role_producer_spacing_model() {
    Model m{{{"A","A",Role::Control},{"B","B",Role::Participant},{"C","C",Role::Database},{"D","D",Role::Actor}},
            {{0,2,"abcdefghijklmnopq",false},{3,0,"reverse",true},{1,1,"self",false},{2,3,"last",false}},
            {{{1,2},"owned note","over",2}}};
    m.messages[0].number="100";m.messages[1].number="105";m.messages[2].number="110";
    m.order={{EventKind::Message,0},{EventKind::Message,1},{EventKind::Message,2},{EventKind::Note,0},{EventKind::Message,3}};
    return m;
}
TEST(MermaidSequenceRoleProducer, FinalNumberedLabelsUseSourceLeftIntervalsWithoutBorrowingNeighborLifelines) {
    const auto good=role_producer_spacing_hand();const auto model=role_producer_spacing_model();
    const auto errors=validate(good,model);ASSERT_TRUE(errors.empty())<<(errors.empty()?"":errors.front());
    const auto mutations=role_stage2_source_mutations(good,model);
    for(const auto& error:mutations)ADD_FAILURE()<<error;
    auto bad=good;bad.put(34,9," ");EXPECT_FALSE(validate(bad,model).empty());
    bad=good;bad.put(34,10,"─");EXPECT_FALSE(validate(bad,model).empty());
    bad=good;bad.put(34,15,"┄");EXPECT_FALSE(validate(bad,model).empty());
    bad=good;bad.put(46,21," ");EXPECT_FALSE(validate(bad,model).empty());
    bad=good;bad.put(66,27,"│");EXPECT_FALSE(validate(bad,model).empty());
    auto wrong=model;wrong.messages[0].number="";EXPECT_FALSE(validate(good,wrong).empty());
    wrong=model;wrong.messages[0].number="10";EXPECT_FALSE(validate(good,wrong).empty());
    wrong=model;wrong.messages[1].from=0;wrong.messages[1].to=3;EXPECT_FALSE(validate(good,wrong).empty());
    wrong=model;wrong.notes[0].actors={0};EXPECT_FALSE(validate(good,wrong).empty());
    EXPECT_FALSE(validate(good,model,0).empty());EXPECT_FALSE(validate(good,model,100).empty());
    // Bind the hand Model to the independently declared complete source Model.
    const auto parsed=json::parse(role_producer_case_bytes());ASSERT_TRUE(parsed);int matched=0;
    parsed->root().get("cases").iter([&](JsonVal item) {
        if(item.get_string("batch")!="spacing")return;++matched;
        const auto declared=lifecycle_fact_model(item.get("native_model"),NumberFactEncoding::DisplayText);
        EXPECT_TRUE(validate(good,declared).empty());
    });EXPECT_EQ(matched,1);
}
