bool role_c_model_adversaries(const Grid& good,const Model& model) {
    bool passed=true;int executed=0;
    auto rejects=[&](const Model& wrong,std::string_view reason) {
        SCOPED_TRACE(reason);
        // A schema-invalid schedule is an author error, not evidence that
        // the complete drawing rejects a semantic geometry mutation.
        try {Work schema;check_event_model(wrong,schema);}
        catch(const std::exception& error){ADD_FAILURE()<<"Invalid contextual-ID adversary: "<<error.what();passed=false;return;}
        ++executed;const auto errors=validate(good,wrong);
        EXPECT_FALSE(errors.empty())<<reason;passed&=!errors.empty();
    };
    for(std::size_t n=0;n<model.actors.size();++n) {
        auto wrong=model;wrong.actors[n].label+="_wrong";rejects(wrong,"complete alias");
    }
    for(std::size_t n=0;n<model.messages.size();++n) {
        auto wrong=model;wrong.messages[n].label+="_wrong";rejects(wrong,"complete message label");
        wrong=model;wrong.messages[n].to=(wrong.messages[n].to+1)%static_cast<int>(wrong.actors.size());
        rejects(wrong,"different receiver");
        wrong=model;wrong.messages.erase(wrong.messages.begin()+static_cast<std::ptrdiff_t>(n));
        std::erase_if(wrong.order,[&](const OrderedEvent& event){return event.kind==EventKind::Message&&event.index==static_cast<int>(n);});
        for(auto& event:wrong.order)if(event.kind==EventKind::Message&&event.index>static_cast<int>(n))--event.index;
        for(auto& note:wrong.notes)if(note.after>=static_cast<int>(n))--note.after;
        rejects(wrong,"missing complete business message with preserved activation/note schedule");
    }
    if(!model.messages.empty()) {
        auto wrong=model;wrong.messages.push_back(model.messages.front());
        wrong.order.push_back({EventKind::Message,static_cast<int>(wrong.messages.size()-1)});
        rejects(wrong,"extra complete business message");
    }
    EXPECT_EQ(executed,static_cast<int>(model.actors.size()+3*model.messages.size()+(!model.messages.empty()?1u:0u)));
    return passed;
}

bool role_c_expect_public(std::string_view source,const Model& expected) {
    try {
        Work schema;check_event_model(expected,schema);
        auto node=loom::ui::render_markdown(fenced(source,"mermaid"));
        auto plain=loom::ui::render_markdown(fenced(source,"text"));
        node->ComputeRequirement();const int height=std::min(1040,std::max(256,node->requirement().min_y+8));
        const auto wide=capture(node,240,height),ordinary=capture(plain,240,height);
        const auto narrow=capture(node,40,height),ordinary_narrow=capture(plain,40,height),restored=capture(node,240,height);
        bool valid=wide==restored;EXPECT_TRUE(valid)<<"same Node restoration";
        for(const auto* frame:{&wide,&narrow,&restored}) {const bool following=complete_sequence_sentinel(*frame);EXPECT_TRUE(following);valid&=following;}
        const bool fallback=wide==ordinary;EXPECT_FALSE(fallback)<<"Complete contextual-ID source drawing remains unmet";
        // Capture all public states before any return. A source fallback never
        // executes or counts forged geometry as successful.
        if(fallback)return false;
        const auto geometry=validate(wide,expected);for(const auto& error:geometry)ADD_FAILURE()<<error;valid&=geometry.empty();
        if(!(narrow==ordinary_narrow)) {const auto errors=validate(narrow,expected);for(const auto& error:errors)ADD_FAILURE()<<error;valid&=errors.empty();}
        if(!valid)return false;
        return role_c_model_adversaries(wide,expected);
    } catch(const std::exception& error){ADD_FAILURE()<<"Contextual-ID public execution error: "<<error.what();return false;}
}

TEST(MermaidSequenceContextualIds, CompleteHandBindsDeclaredIdsToAliasesAndOwnedBusinessRoutes) {
    const auto good=ordinary();auto expected=ordinary_model();
    expected.actors[0].id="Link";expected.actors[1].id="Links";
    expected.order={{EventKind::Message,0},{EventKind::Message,1}};
    const auto errors=validate(good,expected);ASSERT_TRUE(errors.empty())<<(errors.empty()?"":errors.front());
    EXPECT_TRUE(role_c_model_adversaries(good,expected));
    auto missing=good;missing.put(12,6," ");EXPECT_FALSE(validate(missing,expected).empty());
    auto orphan=good;orphan.put(31,0,"┼");EXPECT_FALSE(validate(orphan,expected).empty());
}

TEST(MermaidSequenceContextualIds, ThirtyCompleteSourcesRespectInitialAndExclusiveIdContexts) {
    ASSERT_EQ(loom::utils::crypto::sha256(kRoleContextualSourceCases),kRoleContextualSourceCasesSha);
    const auto document=json::parse(kRoleContextualSourceCases);ASSERT_TRUE(document);
    const auto rows=document->root().get("positive30");ASSERT_EQ(rows.size(),30u);
    int visited=0,complete=0;
    rows.iter([&](JsonVal row){
        ++visited;const auto name=row.get_string("name");SCOPED_TRACE(name);
        const auto source=row.get_string("source");EXPECT_EQ(loom::utils::crypto::sha256(source),row.get_string("input_sha256"));
        const auto meaning=row.get("native_model");ASSERT_TRUE(meaning.is_obj());
        ASSERT_EQ(loom::utils::crypto::sha256(canonical_json(meaning)),row.get_string("native_model_sha256"));
        const auto expected=lifecycle_fact_model(meaning,NumberFactEncoding::LegacyInteger);
        complete+=role_c_expect_public(source,expected)?1:0;
    });
    EXPECT_EQ(visited,30);EXPECT_EQ(complete,30);
}

TEST(MermaidSequenceContextualIds, ExactSpaceTabAndOperatorBoundariesNeverInventMetadataMessages) {
    for(const std::string_view name:{"Link","Links","Properties","Details"}) {
        Model expected{{{std::string(name),std::string(name)},{"B","B"}},{{0,1,"request",true},{1,0,"reply",false}},{}};
        expected.order={{EventKind::Message,0},{EventKind::Message,1}};
        for(const std::string_view separator:{"  ","\t"}) {
            SCOPED_TRACE(std::string(name)+std::string(separator));
            EXPECT_TRUE(role_c_expect_public("sequenceDiagram\n"+std::string(name)+std::string(separator)+"-->> B: request\nB->>"+std::string(name)+" : reply\n",expected));
        }
    }
    const std::string source="sequenceDiagram\nLink-->>Links: channels\nLinks->>Properties: settings\nProperties-->>Details: inspect\nDetails->>Link: return\n";
    Model expected{{{"Link","Link"},{"Links","Links"},{"Properties","Properties"},{"Details","Details"}},
        {{0,1,"channels",true},{1,2,"settings",false},{2,3,"inspect",true},{3,0,"return",false}},{}};
    expected.order={{EventKind::Message,0},{EventKind::Message,1},{EventKind::Message,2},{EventKind::Message,3}};
    EXPECT_TRUE(role_c_expect_public(source,expected));
}

