TEST(MermaidSequenceRoleMetadataBoundaries, SourceLexicalSeparatorsAndFinalRawAliasSelectionStayDistinct) {
    // Pinned sequenceDiagram.jison35 requires a single-token ID before @{
    // and rule33 requires whitespace before the AS state transition. Keep
    // these whole-source controls outside the immutable89-source collection.
    for(const std::string_view source:{
        "sequenceDiagram\nparticipant A B@{\"type\":\"control\"}\n\"A B\"->>C: kept\n",
        "sequenceDiagram\nparticipant A\tB@{\"type\":\"control\"}\nC->>D: kept\n",
        "sequenceDiagram\nparticipant A B@{\"type\":\"control\"}\nC->>D: kept\n", // U+00A0
        "sequenceDiagram\nparticipant A　B@{\"type\":\"control\"}\nC->>D: kept\n", // U+3000
        "sequenceDiagram\nparticipant A@{\"type\":\"control\"}as Chosen\nA->>B: kept\n",
        "sequenceDiagram\nparticipant A@{\"type\":\"control\"}AS Chosen\nA->>B: kept\n",
        "sequenceDiagram\nparticipant A&X@{\"type\":\"database\",\"alias\":\"Meta\"} as Chosen&\nA&X->>B: ping\n",
        "sequenceDiagram\nparticipant A&X@{\"type\":\"database\",\"alias\":\"\"} as A&X\nA&X->>B: ping\n"}) {
        SCOPED_TRACE(source);text7_expect_source(source);
    }
    // ECMAScript's fixed whitespace set belongs to the pinned metadata-ID
    // token rule, not a blanket ban on non-ASCII identities. Iterate all
    // non-ASCII members plus the remaining same-line ASCII members.
    for(const std::string_view whitespace:{"\v","\f","\r","\xC2\xA0","\xE1\x9A\x80",
        "\xE2\x80\x80","\xE2\x80\x81","\xE2\x80\x82","\xE2\x80\x83","\xE2\x80\x84",
        "\xE2\x80\x85","\xE2\x80\x86","\xE2\x80\x87","\xE2\x80\x88","\xE2\x80\x89","\xE2\x80\x8A",
        "\xE2\x80\xA8","\xE2\x80\xA9","\xE2\x80\xAF","\xE2\x81\x9F","\xE3\x80\x80","\xEF\xBB\xBF"}) {
        SCOPED_TRACE(std::string(whitespace));
        text7_expect_source("sequenceDiagram\nparticipant A"+std::string(whitespace)+
            "B@{\"type\":\"control\"}\nC->>D: kept\n");
    }
    Model separated{{{"A","Chosen",Role::Control},{"B","B"}},{{0,1,"kept",false}},{}};
    separated.order={{EventKind::Message,0}};
    for(const std::string_view separator:{" ","\t"}) {
        SCOPED_TRACE(separator);
        EXPECT_TRUE(role_c_expect_public("sequenceDiagram\nparticipant A@{\"type\":\"control\"}"+
            std::string(separator)+"as Chosen\nA->>B: kept\n",separated));
    }
    auto nonascii=separated;nonascii.actors[0].id="甲";
    EXPECT_TRUE(role_c_expect_public(
        "sequenceDiagram\nparticipant 甲@{\"type\":\"control\"} as Chosen\n甲->>B: kept\n",nonascii));
    // Primary selects metadata alias when the raw AS description equals the
    // raw actor ID. The unselected AS is never a displayed TXT field: its '&'
    // must not be rejected by the selected-label decoder before selection.
    Model selected{{{"A&X","Meta",Role::Database},{"B","B"}},{{0,1,"ping",false}},{}};
    selected.order={{EventKind::Message,0}};
    EXPECT_TRUE(role_c_expect_public(
        "sequenceDiagram\nparticipant A&X@{\"type\":\"database\",\"alias\":\"Meta\"} as A&X\nA&X->>B: ping\n",selected));
}
