constexpr std::string_view kOfficialRole38FactsPath="mermaid_native/sequence_official_role57_facts.json";
constexpr std::string_view kOfficialRole38FactsSha="9dbb2b2faf9b8fa85b41730df983fdd059ea859f180f896cc71fd33e54a69709";
constexpr std::string_view kOfficialRole38ManifestSha="c966a7258f1007eda6b992be7a79c2d5f746169d21591dbdd0b7091c6371569b";
std::string joined683_canonical(JsonVal,Work&);
void official_role38_require(bool condition,std::string_view detail) {
    if(!condition)throw std::runtime_error(std::string(detail));
}
void official_role38_bind(JsonVal item,JsonVal manifest,std::set<std::string>& paths) {
    const auto body=item.get_string("body"),digest=item.get_string("body_sha256");
    official_role38_require(!body.empty()&&body.size()<=1000,"Official Role complete body source cap");
    official_role38_require(item.get("body_bytes").is_int()&&item.get_int("body_bytes")==static_cast<std::int64_t>(body.size()),"Official Role body byte count");
    official_role38_require(loom::utils::crypto::sha256(body)==digest,"Official Role full body digest");
    official_role38_require(item.get_string("number_encoding")=="DisplayText","Official Role explicit number encoding");
    official_role38_require(item.get("model").is_obj()&&loom::utils::crypto::sha256(canonical_json(item.get("model")))==item.get_string("model_canonical_sha256"),"Official Role complete Model digest");
    official_role38_require(item.get("original_bindings").is_arr()&&item.get("original_bindings").size()>0,"Official Role missing raw bindings");
    item.get("original_bindings").iter([&](JsonVal binding) {
        const auto path=binding.get_string("path");
        official_role38_require(path.starts_with("sequence/")&&path.find("..") == std::string::npos&&paths.insert(path).second,"Official Role unsafe/duplicate original path");
        official_role38_require(binding.get_string("raw_path")=="tests/fixtures/mermaid_official/cases/"+path,"Official Role raw path binding");
        const auto raw=fixture_bytes("mermaid_official/cases/"+path);
        official_role38_require(raw==binding.get_string("raw_text")&&loom::utils::crypto::sha256(raw)==binding.get_string("raw_sha256"),"Official Role exact original raw bytes");
        official_role38_require(binding.get("body_offset_utf8_bytes").is_int()&&binding.get_int("body_offset_utf8_bytes")>=0,"Official Role invalid body offset");
        const auto offset=static_cast<std::size_t>(binding.get_int("body_offset_utf8_bytes"));
        official_role38_require(offset<=raw.size()&&raw.substr(offset)==body,"Official Role full suffix binding");
        official_role38_require(raw.substr(0,offset)==binding.get_string("raw_metadata_prefix"),"Official Role metadata prefix");
        official_role38_require(binding.get("raw_bytes").is_int()&&binding.get_int("raw_bytes")==static_cast<std::int64_t>(raw.size())&&binding.get("body_bytes").is_int()&&binding.get_int("body_bytes")==static_cast<std::int64_t>(body.size())&&binding.get_string("body_sha256")==digest,"Official Role complete binding lengths/hash");
        int found=0;
        manifest.get("fixtures").iter([&](JsonVal record) {
            if(record.get_string("path")!=path)return;
            ++found;official_role38_require(canonical_json(record)==canonical_json(binding.get("original_manifest_record")),"Official Role complete original policy record changed");
            official_role38_require(record.get_string("sha256")==binding.get_string("raw_sha256")&&record.get_string("git_blob")==binding.get_string("raw_git_blob"),"Official Role original raw SHA/Git blob");
            const auto diagnostic=record.get("diagnostic");
            official_role38_require(diagnostic.is_obj()&&diagnostic.get("offset").is_int()&&diagnostic.get_int("offset")==static_cast<std::int64_t>(offset)&&diagnostic.get_string("sha256")==digest,"Official Role original diagnostic offset/hash");
        });
        official_role38_require(found==1,"Official Role original path missing/ambiguous");
    });
}
struct OfficialRole38Mutations {
    std::map<std::string,int> executed,skipped_schema;
    std::vector<std::string> errors;
};
bool termaid47_resource(std::string_view message);
OfficialRole38Mutations official_role38_mutations(const Grid& good,const Model& model) {
    OfficialRole38Mutations out;
    // Each independent adversary retains the existing per-validation 8M cap.
    // Charge Model copy storage before copying; schema work and geometry share
    // that allowance. No lifecycle/fragment-invalid mutant counts as geometry.
    std::size_t copy_charge=4*(model.actors.size()+model.messages.size()+model.notes.size()+model.fragments.size()+model.order.size()+model.boxes.size()+1);
    auto text_charge=[&](std::string_view text){copy_charge+=4*(text.size()+1);};
    text_charge(model.title);
    for(const auto& actor:model.actors){text_charge(actor.id);text_charge(actor.label);}
    for(const auto& message:model.messages){text_charge(message.label);text_charge(message.number);}
    for(const auto& note:model.notes){text_charge(note.text);text_charge(note.position);copy_charge+=4*note.actors.size();}
    for(const auto& fragment:model.fragments){text_charge(fragment.kind);text_charge(fragment.label);for(const auto& text:fragment.dividers)text_charge(text);}
    for(const auto& box:model.boxes){text_charge(box.title);text_charge(box.color);copy_charge+=4*box.actors.size();}
    auto adversary=[&](std::string_view kind,auto alter) {
        Work work;work.spend(copy_charge);auto wrong=model;alter(wrong);
        try{check_event_model(wrong,work);}catch(const std::runtime_error& error){if(termaid47_resource(error.what()))throw;++out.skipped_schema[std::string(kind)];return;}
        const auto rejected=validate(good,wrong,work.remaining);
        if(std::ranges::any_of(rejected,[](const std::string& error){return termaid47_resource(error);}))
            throw std::runtime_error("Official Role adversary oracle resource exhaustion is not geometry evidence");
        ++out.executed[std::string(kind)];
        if(rejected.empty())out.errors.emplace_back("Accepted schema-preserving official Role adversary: "+std::string(kind));
    };
    auto different=[](const std::string& text){return text=="Wrong"?std::string("Other"):std::string("Wrong");};
    for(std::size_t n=0;n<model.actors.size();++n) {
        adversary("actor_alias",[&](Model& wrong){wrong.actors[n].label=different(wrong.actors[n].label);});
        adversary("actor_role",[&](Model& wrong){wrong.actors[n].role=wrong.actors[n].role==Role::Participant?Role::Actor:Role::Participant;});
    }
    for(std::size_t n=0;n<model.messages.size();++n) {
        adversary("message_label",[&](Model& wrong){wrong.messages[n].label=different(wrong.messages[n].label);});
        adversary("message_arrow",[&](Model& wrong){wrong.messages[n].arrow=wrong.messages[n].arrow==Arrow::Filled?Arrow::Cross:Arrow::Filled;});
        adversary("message_stroke",[&](Model& wrong){wrong.messages[n].dashed=!wrong.messages[n].dashed;});
        if(model.actors.size()>1)adversary("message_receiver",[&](Model& wrong){wrong.messages[n].to=(wrong.messages[n].to+1)%static_cast<int>(wrong.actors.size());});
        if(model.messages[n].central_from)adversary("central_from",[&](Model& wrong){wrong.messages[n].central_from=false;});
        if(model.messages[n].central_to)adversary("central_to",[&](Model& wrong){wrong.messages[n].central_to=false;});
        adversary("message_erasure",[&](Model& wrong) {
            wrong.messages.erase(wrong.messages.begin()+static_cast<std::ptrdiff_t>(n));
            std::erase_if(wrong.order,[&](const OrderedEvent& event){return event.kind==EventKind::Message&&event.index==static_cast<int>(n);});
            for(auto& event:wrong.order)if(event.kind==EventKind::Message&&event.index>static_cast<int>(n))--event.index;
            for(auto& note:wrong.notes)if(note.after>=static_cast<int>(n))--note.after;
        });
    }
    for(std::size_t n=0;n<model.notes.size();++n) {
        adversary("note_text",[&](Model& wrong){wrong.notes[n].text=different(wrong.notes[n].text);});
        if(model.notes[n].actors.size()==1&&model.actors.size()>1)
            adversary("note_owner",[&](Model& wrong){wrong.notes[n].actors[0]=(wrong.notes[n].actors[0]+1)%static_cast<int>(wrong.actors.size());});
        adversary("note_erasure",[&](Model& wrong) {
            wrong.notes.erase(wrong.notes.begin()+static_cast<std::ptrdiff_t>(n));
            std::erase_if(wrong.order,[&](const OrderedEvent& event){return event.kind==EventKind::Note&&event.index==static_cast<int>(n);});
            for(auto& event:wrong.order)if(event.kind==EventKind::Note&&event.index>static_cast<int>(n))--event.index;
        });
    }
    for(std::size_t n=0;n<model.fragments.size();++n) {
        adversary("fragment_label",[&](Model& wrong){wrong.fragments[n].label=different(wrong.fragments[n].label);});
        for(std::size_t d=0;d<model.fragments[n].dividers.size();++d)
            adversary("fragment_divider",[&](Model& wrong){wrong.fragments[n].dividers[d]=different(wrong.fragments[n].dividers[d]);});
    }
    for(std::size_t n=0;n<model.boxes.size();++n) {
        adversary("box_title",[&](Model& wrong){wrong.boxes[n].title=different(wrong.boxes[n].title);});
        adversary("box_color",[&](Model& wrong){wrong.boxes[n].color=wrong.boxes[n].color=="red"?"blue":"red";});
        adversary("box_erasure",[&](Model& wrong){wrong.boxes.erase(wrong.boxes.begin()+static_cast<std::ptrdiff_t>(n));});
    }
    for(std::size_t n=0;n<model.order.size();++n)
        if(model.order[n].kind==EventKind::Create||model.order[n].kind==EventKind::Destroy)
            adversary("lifetime_event",[&](Model& wrong){wrong.order.erase(wrong.order.begin()+static_cast<std::ptrdiff_t>(n));});
    for(std::size_t actor=0;actor<model.actors.size();++actor)
        if(std::ranges::any_of(model.order,[&](const OrderedEvent& event){return event.index==static_cast<int>(actor)&&(event.kind==EventKind::Activate||event.kind==EventKind::Deactivate);}))
            adversary("activation_interval",[&](Model& wrong) {
                std::erase_if(wrong.order,[&](const OrderedEvent& event){return event.index==static_cast<int>(actor)&&(event.kind==EventKind::Activate||event.kind==EventKind::Deactivate);});
            });
    // These total lower bounds are schedule-preserving by construction. Other
    // candidates are reported separately, including valid lifecycle erasures.
    const auto count=[&](std::string_view key){return out.executed[std::string(key)];};
    if(count("actor_alias")!=static_cast<int>(model.actors.size())||count("actor_role")!=static_cast<int>(model.actors.size())||count("message_label")!=static_cast<int>(model.messages.size())||count("message_arrow")!=static_cast<int>(model.messages.size())||count("message_stroke")!=static_cast<int>(model.messages.size())||count("note_text")!=static_cast<int>(model.notes.size())||count("fragment_label")!=static_cast<int>(model.fragments.size())||count("box_title")!=static_cast<int>(model.boxes.size()))
        out.errors.emplace_back("Official Role useful schema-preserving mutation threshold not reached");
    if(std::ranges::any_of(model.order,[](const OrderedEvent& event){return event.kind==EventKind::Create||event.kind==EventKind::Destroy;})&&count("lifetime_event")==0)
        out.errors.emplace_back("Official Role lifetime source has no valid independent interval adversary");
    Work pixel_work;pixel_work.spend(good.cells.size());auto orphan=good;bool placed=false;
    for(int x=good.width-1;x>=0;--x) {
        pixel_work.spend();if(good.at(x,0)!=" ")continue;orphan.put(x,0,"┼");placed=true;break;
    }
    if(!placed)out.errors.emplace_back("Official Role orphan control has no independent blank cell");
    else {
        const auto rejected=validate(orphan,model,pixel_work.remaining);
        if(std::ranges::any_of(rejected,[](const std::string& error){return termaid47_resource(error);}))
            throw std::runtime_error("Official Role orphan oracle resource exhaustion is not geometry evidence");
        ++out.executed["orphan_ink"];
        if(rejected.empty())out.errors.emplace_back("Official Role unowned extra ink accepted");
    }
    return out;
}
