TEST(MermaidTermaid47Native, MatrixJoinUsesOnlyTheExistingFortySevenWholeSourceModels){
    constexpr std::string_view supplement_path="mermaid_native/sequence_termaid2_profile_supplement.json";
    constexpr std::string_view supplement_sha="51ef62ac2f504b10c82b5c87515a35f6bdc6b410cb93834c10de180a30276dab";
    Work setup;
    const auto bytes=joined683_fixture(kTermaid47FactsPath,kTermaid47FactsSha,setup);
    const auto side_bytes=joined683_fixture(supplement_path,supplement_sha,setup);
    const auto facts=json::parse(bytes),side=json::parse(side_bytes);ASSERT_TRUE(facts&&side);
    ASSERT_EQ(side->root().get_string("base_facts_sha256"),kTermaid47FactsSha);
    // Core/Go disjointness is asserted against the live owner maps in the
    // matrix above; this assertion does not duplicate the large core setup.
    const auto vendor_bytes=fixture_bytes("mermaid_terminal/termaid/cases.json");setup.spend(vendor_bytes.size());
    ASSERT_EQ(loom::utils::crypto::sha256(vendor_bytes),kTermaid47ManifestSha);const auto vendor=json::parse(vendor_bytes);ASSERT_TRUE(vendor);
    std::map<std::string,JsonVal> supplements;
    side->root().get("cases").iter([&](JsonVal c){setup.spend(c.get("id").as_str().size()+3);ASSERT_TRUE(supplements.emplace(c.get_string("id"),c).second);});
    ASSERT_EQ(supplements.size(),2u);
    std::set<std::string> selected,sources,consumed;int base_models=0,actors=0,messages=0,notes=0,fragments=0,events=0;
    facts->root().get("cases").iter([&](JsonVal c){
        Work work;work.spend(c.get("input").as_str().size()*3+c.get("id").as_str().size()*2+512);
        const auto id=c.get_string("id"),source=c.get_string("input"),sha=c.get_string("input_sha256");SCOPED_TRACE(id);
        ASSERT_TRUE(selected.insert(id).second);ASSERT_TRUE(sources.insert(sha).second);
        ASSERT_EQ(c.get_string("vendor"),"termaid");ASSERT_EQ(loom::utils::crypto::sha256(source),sha);
        ASSERT_EQ(c.get_string("manifest"),"tests/fixtures/mermaid_terminal/termaid/cases.json");ASSERT_EQ(c.get_string("manifest_sha256"),kTermaid47ManifestSha);
        const auto original=pointer(vendor->root(),c.get_string("json_pointer"));ASSERT_EQ(original.get_string("family"),"sequence");
        ASSERT_EQ(original.get_string("id"),id);ASSERT_EQ(original.get_string("input"),source);ASSERT_EQ(original.get_string("sha256"),sha);
        ASSERT_EQ(loom::utils::crypto::sha256(joined683_canonical(original,work)),c.get_string("case_sha256"));
        const bool profile=c.get("native_model").is_null();ASSERT_TRUE(!profile||supplements.contains(id));
        const auto chosen=profile?supplements.at(id):c;
        if(profile){
            ASSERT_TRUE(consumed.insert(id).second);ASSERT_EQ(chosen.get_string("input"),source);ASSERT_EQ(chosen.get_string("input_sha256"),sha);
            ASSERT_EQ(pointer(facts->root(),chosen.get_string("base_case_pointer")).get_string("id"),id);
            ASSERT_EQ(loom::utils::crypto::sha256(joined683_canonical(c,work)),chosen.get_string("base_case_sha256"));
        }else ++base_models;
        ASSERT_EQ(chosen.get_string("number_encoding"),"DisplayText");const auto meaning=chosen.get("native_model");ASSERT_TRUE(meaning.is_obj());
        ASSERT_EQ(loom::utils::crypto::sha256(joined683_canonical(meaning,work)),chosen.get_string("native_model_sha256"));
        meaning.get("messages").iter([&](JsonVal m){ASSERT_TRUE(m.get("number").is_str());});
        const auto model=lifecycle_fact_model(meaning,NumberFactEncoding::DisplayText);check_event_model(model,work);
        actors+=static_cast<int>(model.actors.size());messages+=static_cast<int>(model.messages.size());notes+=static_cast<int>(model.notes.size());fragments+=static_cast<int>(model.fragments.size());events+=static_cast<int>(model.order.size());
    });
    EXPECT_EQ(selected.size(),47u);EXPECT_EQ(sources.size(),47u);EXPECT_EQ(consumed.size(),2u);EXPECT_EQ(base_models,45);
    EXPECT_EQ(actors,114);EXPECT_EQ(messages,146);EXPECT_EQ(notes,13);EXPECT_EQ(fragments,47);EXPECT_EQ(events,286);
}
