    wrap_doc.root().get("cases").iter([&](JsonVal row){wrap_setup.spend(row.get("id").as_str().size()+64);ASSERT_TRUE(wrap_by_id.emplace(row.get_string("id"),row).second);});
    ASSERT_EQ(wrap_by_id.size(),43u);
