Grid first19_cross_group_note_hand() {
    Grid grid{86,43,std::vector<std::string>(86u*43u," ")};
    auto group=[&](int left,int right,std::string_view caption,bool colored) {
        grid.put(left,0,"┌");grid.put(right,0,"┐");grid.put(left,42,"└");grid.put(right,42,"┘");
        for(int x=left+1;x<right;++x){grid.put(x,0,"─");grid.put(x,42,"─");}
        for(int y=1;y<42;++y){grid.put(left,y,"│");grid.put(right,y,"│");}
        auto divider=[&](int y){grid.put(left,y,"├");grid.put(right,y,"┤");for(int x=left+1;x<right;++x)grid.put(x,y,"─");};
        if(colored){grid.text(left+2,1,"color: Green");divider(2);grid.text(left+2,3,caption);divider(4);}
        else{grid.text(left+2,1,caption);divider(2);}
    };
    group(0,44,"Left",false);group(54,84,"Right",true);
    for(const auto& [column,label]:std::array<std::pair<int,std::string_view>,4>{{{7,"A"},{27,"B"},{61,"C"},{77,"D"}}}) {
        role_stage2_hand_header(grid,column-3,6,label);
        for(int y=9;y<42;++y)grid.put(column,y,"│");
    }
    auto shaft=[&](int from,int to,int y,bool dashed,std::string_view label) {
        const int low=std::min(from,to),high=std::max(from,to);grid.text(low+2,y-1,label);
        grid.put(from,y,from<to?"├":"┤");grid.put(to,y,from<to?"▶":"◀");
        for(int x=low+1;x<high;++x)grid.put(x,y,(x==7||x==27||x==61||x==77||x==44||x==54)?"┼":dashed?"┄":"─");
    };
    shaft(7,27,12,false,"hi");shaft(27,77,16,false,"across");
    shaft(77,7,29,true,"back");shaft(61,27,35,false,"done");
    // Note.over B,C is an opaque complete box. It owns only its exact
    // rectangle, including the two group sides44/54 and its target ports.
    for(int y=20;y<=23;++y)for(int x=25;x<=64;++x)grid.put(x,y," ");
    grid.put(25,20,"┌");grid.put(64,20,"┐");grid.put(25,23,"└");grid.put(64,23,"┘");
    for(int x=26;x<64;++x){grid.put(x,20,"─");grid.put(x,23,"─");}
    for(int y=21;y<23;++y){grid.put(25,y,"│");grid.put(64,y,"│");}
    grid.text(28,21,"cross");grid.text(28,22,"note");
    for(const int column:{27,61}){grid.put(column,20,"┴");grid.put(column,23,"┬");}
    return grid;
}
