TEST(MermaidSequenceFirst19, EveryFrozenWholeSourceUsesItsUnchangedCompleteModelAcrossThreeWidths) {
    Work setup;const auto bytes=joined683_fixture(kMerman280FactsPath,kMerman280FactsSha,setup);
    const auto document=json::parse(bytes);ASSERT_TRUE(document);
    ASSERT_EQ(document->root().get("cases").size(),280u);
    std::set<std::string> visited;std::map<std::string,int> classes;
    document->root().get("cases").iter([&](JsonVal row){
        const auto id=row.get("id").as_str();
        const auto selected=std::ranges::find_if(kFirst19SourceBindings,[&](const auto& b){return b.id==id;});
        if(selected==kFirst19SourceBindings.end())return;
        SCOPED_TRACE(std::string(id));
        try {
            Work work;work.spend(row.get("input").as_str().size()*3+id.size()*2+512);
            ASSERT_TRUE(visited.insert(std::string(id)).second);++classes[std::string(selected->source_class)];
            const auto source=row.get_string("input");ASSERT_EQ(loom::utils::crypto::sha256(source),selected->input_sha);
            ASSERT_EQ(row.get_string("input_sha256"),selected->input_sha);
            ASSERT_TRUE(row.get("native_model").is_obj());ASSERT_EQ(row.get_string("number_encoding"),"DisplayText");
            const auto encoded=joined683_canonical(row.get("native_model"),work);
            ASSERT_EQ(loom::utils::crypto::sha256(encoded),selected->model_sha);
            ASSERT_EQ(row.get_string("native_model_sha256"),selected->model_sha);
            work.spend(encoded.size()*8+64);
            const auto model=lifecycle_fact_model(row.get("native_model"),NumberFactEncoding::DisplayText);
            first19_expect_public(source,model,work.remaining);
        } catch(const std::exception& error) {ADD_FAILURE()<<"First19 actual source/Model/oracle error: "<<error.what();}
    });
    EXPECT_EQ(visited.size(),19u);
    EXPECT_EQ(classes,(std::map<std::string,int>{{"literal_double_quote",5},{"literal_box_ampersand",1},
        {"fragment_inline_hash_comment",4},{"explicit_nowrap_false",1},{"tiny_yaml_role_syntax",2},
        {"pending_create_destroy_priority",1},{"identity_lexical_context",1},{"role_fragment_uniform_gap_width",2},
        {"cross_group_opaque_note",2}}));
}
TEST(MermaidSequenceFirst19, FalseWrapDirectiveBelongsToParsedTextAndNotTheSelectedMetadataAlias) {
    // Pinned jison264/269 and421 call parseMessage; sequenceDb.addActor
    // selects doc.alias directly without parseMessage/extractWrap.
    Model parsed{{{"A","nowrap:Literal",Role::Database},{"B","Visible"}},{{0,1,"message",false}},{{{0,1},"note","over",0}}};
    parsed.fragments={{"loop","condition",-1,{}}};
    parsed.order={{EventKind::Open,0},{EventKind::Message,0},{EventKind::Note,0},{EventKind::Close,0}};
    first19_expect_public("sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\"nowrap:Literal\"}\n"
        "participant B as nowrap:Visible\nloop nowrap:condition\nA->>B: nowrap:message\nNote over A,B: nowrap:note\nend\n",parsed);
    // Raw AS text differs from identity, so its parsed description wins.
    Model alias{{{"A","Chosen",Role::Database},{"B","B"}},{{0,1,"ping",false}},{}};
    alias.order={{EventKind::Message,0}};
    first19_expect_public("sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\"nowrap:Literal\"} as nowrap:Chosen\nA->>B: ping\n",alias);
    // If parsed AS equals the raw identity, addActor selects the literal
    // metadata alias. Prefix stripping must not run again on that winner.
    alias.actors[0].label="nowrap:Literal";
    first19_expect_public("sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\"nowrap:Literal\"} as nowrap:A\nA->>B: ping\n",alias);
    // extractWrap has no case-insensitive flag: uppercase text is data.
    parsed.actors[1].label="NOWRAP:Visible";parsed.messages[0].label="NOWRAP:message";
    parsed.notes[0].text="NOWRAP:note";parsed.fragments[0].label="NOWRAP:condition";
    first19_expect_public("sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\"nowrap:Literal\"}\n"
        "participant B as NOWRAP:Visible\nloop NOWRAP:condition\nA->>B: NOWRAP:message\nNote over A,B: NOWRAP:note\nend\n",parsed);
}

