// Additional source controls only. Do not change the frozen native184 prefix.
TEST(MermaidSequenceFirst19, StatementBoundariesAndRawMetadataBytesCannotBeHiddenByQuotes) {
    auto check=[](const std::string& source,const Model& model) {
        SCOPED_TRACE(source);Work work;check_event_model(model,work);
        const auto node=loom::ui::render_markdown(fenced(source,"mermaid"));
        const auto plain=loom::ui::render_markdown(fenced(source,"text"));
        node->ComputeRequirement();plain->ComputeRequirement();
        const int height=std::min(1040,std::max(40,std::max(node->requirement().min_y,plain->requirement().min_y)+12));
        const auto wide=capture(node,240,height),ordinary=capture(plain,240,height);
        const auto narrow=capture(node,40,height),small_plain=capture(plain,40,height),restored=capture(node,240,height);
        EXPECT_TRUE(wide==restored);
        for(const auto* frame:{&wide,&narrow,&restored})EXPECT_TRUE(complete_sequence_sentinel(*frame));
        EXPECT_FALSE(wide==ordinary)<<"Complete lexical-context positive remains source fallback";
        if(wide==ordinary)return;
        const auto errors=validate(wide,model,work.remaining);first19_no_resource_rejection(errors);
        for(const auto& error:errors)ADD_FAILURE()<<error;
        if(narrow!=small_plain){const auto small=validate(narrow,model,work.remaining);first19_no_resource_rejection(small);for(const auto& error:small)ADD_FAILURE()<<error;}
        if(!errors.empty())return;
        first19_reject_model(wide,model,[](Model& wrong){wrong.messages[0].label="Wrong";});
        first19_reject_model(wide,model,[](Model& wrong){std::swap(wrong.messages[0].from,wrong.messages[0].to);});
        first19_reject_model(wide,model,[](Model& wrong){
            const int removed=static_cast<int>(wrong.messages.size()-1);wrong.messages.pop_back();
            std::erase_if(wrong.order,[&](const OrderedEvent& event){return event.kind==EventKind::Message&&event.index==removed;});
        });
        first19_reject_model(wide,model,[](Model& wrong){
            wrong.messages.push_back({0,1,"extra",false});
            wrong.order.push_back({EventKind::Message,static_cast<int>(wrong.messages.size()-1)});
        });
    };
    Model split{{{"A","A"},{"B","B"},{"C","C"}},{{0,1,"\"one",false},{0,2,"two\"",false}},{}};
    split.order={{EventKind::Message,0},{EventKind::Message,1}};
    check("sequenceDiagram\nA->>B: \"one; A->>C: two\"\n",split);
    Model alias{{{"A","\"Alias"},{"B","B"}},{{0,1,"one",false}},{}};
    alias.order={{EventKind::Message,0}};
    check("sequenceDiagram\nparticipant A as \"Alias; A->>B: one\n",alias);
    alias.actors[0].label="\"Alias\"";
    check("sequenceDiagram\nparticipant A as \"Alias\"; A->>B: one\n",alias);
    Model line{{{"A","A"},{"B","B"}},{{0,1,"one",false}},{}};
    line.fragments={{"loop","\"phase",-1,{}}};
    line.order={{EventKind::Open,0},{EventKind::Message,0},{EventKind::Close,0}};
    check("sequenceDiagram\nloop \"phase; A->>B: one\nend\n",line);
    line.messages.push_back({1,0,"two",true});line.fragments={{"alt","\"yes",-1,{"\"no"}}};
    line.order={{EventKind::Open,0},{EventKind::Message,0},{EventKind::Divide,0},{EventKind::Message,1},{EventKind::Close,0}};
    check("sequenceDiagram\nalt \"yes; A->>B: one\nelse \"no; B-->>A: two\nend\n",line);
    Model config{{{"A","Semi;Literal",Role::Database},{"B","B"}},{{0,1,"after",false}},{}};
    config.order={{EventKind::Message,0}};
    check("sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\"Semi;Literal\"}; A->>B: after\n",config);
    // Preserve the already source-backed Go quoted-ID arrow/space extension.
    // A quoted-ID containing a semicolon is not newly claimed by this TEST.
    Model quoted{{{"A->B","A->B"},{"C","C"}},{{0,1,"quoted",false}},{}};
    quoted.order={{EventKind::Message,0}};
    check("sequenceDiagram\n\"A->B\" ->> C: quoted\n",quoted);
    quoted.actors={{"loop svc","loop svc"},{"B","B"}};quoted.messages[0].label="quoted keyword name";
    check("sequenceDiagram\n\"loop svc\" ->> B: quoted keyword name\n",quoted);
    // JSON escaped controls are valid source bytes and preserve existing Safe
    // display; raw forbidden bytes in YAML/JSON strings are a different gate.
    config.actors[0].label="X\\u{0000}Y";config.messages[0].label="ping";
    check("sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\"X\\u0000Y\"}\nA->>B: ping\n",config);
    config.actors[0].label="Safe";
    check("sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\"X\\u0000Y\"} as Safe\nA->>B: ping\n",config);
    for(const std::string_view source:{
        "sequenceDiagram\nparticipant A@{\"type\":\"database\",\"unknown\":\"Semi;Literal\"}; A->>B: after\n",
        "sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\"Semi;Literal\"; A->>B: after\n",
        "sequenceDiagram\nparticipant A@{\"type\":\"database\",\"alias\":\"Semi;Literal}; A->>B: after\n",
        "sequenceDiagram\nparticipant A@{\"type\":\"database\"}@{\"alias\":\"Semi;Literal\"}; A->>B: after\n"
    }){SCOPED_TRACE(std::string(source));text7_expect_source(source);}
    const std::array<std::string,8> forbidden{{std::string("\0",1),std::string("\x01",1),std::string("\x1B",1),
        std::string("\xC0\xAD",2),std::string("\xED\xA0\x80",3),std::string("\xF4\x90\x80\x80",4),
        std::string("\x80",1),std::string("\xE2\x82",2)}};
    for(std::size_t n=0;n<forbidden.size();++n)for(const bool quoted_scalar:{false,true})for(const bool as_override:{false,true}) {
        SCOPED_TRACE(std::to_string(n)+"/singlequoted="+std::to_string(quoted_scalar)+"/AS="+std::to_string(as_override));
        const auto scalar=std::string(quoted_scalar?"'X":"X")+forbidden[n]+(quoted_scalar?"Y'":"Y");
        const auto source="sequenceDiagram\nparticipant A@{type: database, alias: "+scalar+"}"+
            (as_override?" as Safe":"")+"\nA->>B: ping\n";
        text7_expect_source(source);
    }
}

