constexpr std::string_view kNonwrap42FactsPath="mermaid_native/sequence_merman280_nonwrap42_native_facts.json";
constexpr std::string_view kNonwrap42FactsSha="c7a46a7599bda5a88aee7814f37f3fda1661d8e0dcf93cbd36c7e2f7c3219eef";
constexpr std::string_view kNonwrap42ContractSha="5989b196e5f833930ff398254a5c52484d98c6999cc3c9a0fefc8e0f45dc1f22";
std::string nonwrap42_text(std::string_view text,Work& work) {
    // Source-integrity assertion only: these reviewed raw display fields use
    // the already admitted literal BR forms. This does not parse source/code.
    work.spend(text.size()*32+8);std::string out;out.reserve(text.size());
    for(std::size_t n=0;n<text.size();) {
        std::size_t length=0;
        for(const std::string_view br:{"<br>","<br/>","<br />"})if(text.substr(n).starts_with(br)){length=br.size();break;}
        if(length){out+='\n';n+=length;}else out+=text[n++];
    }
    return out;
}
void nonwrap42_span(JsonVal span,const std::string& source,Work& work) {
    termaid47_require(span.is_obj()&&span.get("offset_utf8_bytes").is_int()&&span.get("length_utf8_bytes").is_int(),"Nonwrap42 exact source span schema");
    const auto offset=span.get_int("offset_utf8_bytes"),length=span.get_int("length_utf8_bytes");
    termaid47_require(offset>=0&&length>=0&&static_cast<std::uint64_t>(offset)<=source.size()&&static_cast<std::uint64_t>(length)<=source.size()-static_cast<std::size_t>(offset),"Nonwrap42 source span bounds");
    work.spend(static_cast<std::size_t>(length)*3+64);const auto text=span.get_string("text");
    termaid47_require(text.size()==static_cast<std::size_t>(length)&&source.compare(static_cast<std::size_t>(offset),static_cast<std::size_t>(length),text)==0,"Nonwrap42 exact original source bytes");
    termaid47_require(loom::utils::crypto::sha256(text)==span.get_string("sha256"),"Nonwrap42 original source span digest");
}
void nonwrap42_raw_binding(JsonVal row,const Model& model,const std::string& source,Work& work) {
    const auto raw=row.get("complete_primary_model"),contract=row.get("nonwrap42_source_contract");
    termaid47_require(raw.is_obj()&&raw.get_string("type")=="sequence"&&contract.is_obj(),"Nonwrap42 full raw/contract binding");
    const auto actor_order=raw.get("actorOrder"),actors=raw.get("actors"),events=raw.get("messages");
    termaid47_require(actor_order.is_arr()&&actors.is_obj()&&events.is_arr()&&actor_order.size()==model.actors.size()&&actors.size()==model.actors.size(),"Nonwrap42 complete raw actors");
    work.spend(model.actors.size()*8+model.messages.size()*4+model.fragments.size()*8+events.size()*8+64);
    auto actor_index=[&](std::string_view id) {
        for(std::size_t n=0;n<model.actors.size();++n){work.spend();if(model.actors[n].id==id)return static_cast<int>(n);}
        throw std::runtime_error("Nonwrap42 raw event actor missing from complete Model");
    };
    std::size_t actor_at=0;
    actor_order.iter([&](JsonVal name){
        termaid47_require(name.is_str()&&name.as_str()==model.actors[actor_at].id,"Nonwrap42 source actor order/identity");
        const auto actual=actors.get(name.as_str());const auto& expected=model.actors[actor_at++];
        termaid47_require(actual.is_obj()&&actual.get_string("name")==expected.id&&actual.get("description").is_str(),"Nonwrap42 full raw actor record");
        termaid47_require(nonwrap42_text(actual.get("description").as_str(),work)==expected.label,"Nonwrap42 complete raw alias");
        termaid47_require(actual.get("wrap").is_bool()&&!actual.get("wrap").as_bool(),"Nonwrap42 actor wrapping is not omitted");
        constexpr std::array<std::pair<std::string_view,Role>,8> roles{{{"participant",Role::Participant},{"actor",Role::Actor},{"boundary",Role::Boundary},{"control",Role::Control},{"entity",Role::Entity},{"database",Role::Database},{"collections",Role::Collections},{"queue",Role::Queue}}};
        const auto role=actual.get_string("type");const auto found=std::ranges::find_if(roles,[&](const auto& entry){return entry.first==role;});
        termaid47_require(found!=roles.end()&&found->second==expected.role,"Nonwrap42 source role does not come from properties");
        termaid47_require(actual.get("links").is_obj()&&actual.get("properties").is_obj(),"Nonwrap42 original interaction maps retained");
    });
    std::size_t message_at=0,note_at=0,fragment_at=0,order_at=0;int number=1;bool visible=false;
    std::vector<bool> from_seen(model.messages.size()),to_seen(model.messages.size());
    std::vector<int> stack,dividers(model.fragments.size());std::optional<std::size_t> last_message;
    auto ordered=[&](EventKind kind,int index,int part=0){
        work.spend();termaid47_require(order_at<model.order.size(),"Nonwrap42 raw event missing native chronology");
        const auto e=model.order[order_at++];termaid47_require(e.kind==kind&&e.index==index&&e.part==part,"Nonwrap42 complete raw/native event chronology");
    };
    events.iter([&](JsonVal event){
        work.spend();termaid47_require(event.is_obj()&&event.get("type").is_int()&&event.get("wrap").is_bool()&&!event.get("wrap").as_bool(),"Nonwrap42 full raw event schema/wrap");
        const auto type=event.get_int("type");
        if(type==26){
            const auto setting=event.get("message");termaid47_require(setting.is_obj()&&setting.size()==1&&setting.get("visible").is_bool()&&setting.get("visible").as_bool(),"Nonwrap42 exact bare numbering command");
            visible=true;last_message.reset();return;
        }
        if(type==59||type==60){
            termaid47_require(last_message.has_value()&&event.get("from").is_str()&&event.get("to").is_null()&&event.get_string("message").empty(),"Nonwrap42 auxiliary central event binding");
            const auto& message=model.messages[*last_message];
            const auto endpoint=type==59?message.to:message.from;
            termaid47_require(actor_index(event.get("from").as_str())==endpoint,"Nonwrap42 actual central actor endpoint");
            auto& seen=type==59?to_seen:from_seen;
            termaid47_require(!seen[*last_message],"Nonwrap42 duplicate central source event");seen[*last_message]=true;return;
        }
        const bool business=type==0||type==1||type==3||type==4||type==5||type==6||type==24||type==25||type==33||type==34;
        if(business){
            termaid47_require(message_at<model.messages.size()&&event.get("from").is_str()&&event.get("to").is_str()&&event.get("message").is_str(),"Nonwrap42 complete business event binding");
            const auto& message=model.messages[message_at];
            const auto arrow=(type==0||type==1)?Arrow::Filled:(type==3||type==4)?Arrow::Cross:(type==5||type==6)?Arrow::Unheaded:(type==24||type==25)?Arrow::Async:Arrow::Both;
            const bool dashed=type==1||type==4||type==6||type==25||type==34;
            termaid47_require(message.from==actor_index(event.get("from").as_str())&&message.to==actor_index(event.get("to").as_str())&&message.arrow==arrow&&message.dashed==dashed,"Nonwrap42 full arrow/stroke/endpoints");
            termaid47_require(nonwrap42_text(event.get("message").as_str(),work)==message.label,"Nonwrap42 complete message text");
            termaid47_require(message.number==(visible?std::to_string(number):std::string{}),"Nonwrap42 exact display numbering and hidden advancement");++number;
            const int central=message.central_from?(message.central_to?61:60):(message.central_to?59:0);
            termaid47_require(event.get("activate").is_bool()&&event.get("activate").as_bool()==message.central_to,"Nonwrap42 raw central decoration is not activation");
            termaid47_require(central?(event.get("centralConnection").is_int()&&event.get_int("centralConnection")==central):!event.has("centralConnection"),"Nonwrap42 complete central flags");
            ordered(EventKind::Message,static_cast<int>(message_at));last_message=message_at++;return;
        }
        last_message.reset();
        if(type==2){
            termaid47_require(note_at<model.notes.size()&&event.get("from").is_str()&&event.get("to").is_str()&&event.get("message").is_str()&&event.get("placement").is_int(),"Nonwrap42 complete raw Note");
            const auto& note=model.notes[note_at];const int first=actor_index(event.get("from").as_str()),last=actor_index(event.get("to").as_str());
            const auto placement=event.get_int("placement");const auto position=placement==0?"left":placement==1?"right":placement==2?"over":"invalid";
            const bool targets=note.actors.size()==(first==last?1u:2u)&&note.actors[0]==first&&(first==last||note.actors[1]==last);
            termaid47_require(targets&&note.position==position&&note.after==static_cast<int>(message_at)-1&&note.text==nonwrap42_text(event.get("message").as_str(),work),"Nonwrap42 complete Note target/after/text");
            ordered(EventKind::Note,static_cast<int>(note_at++));return;
        }
        if(type==12||type==19){
            termaid47_require(fragment_at<model.fragments.size()&&event.get("message").is_str(),"Nonwrap42 complete raw fragment opening");
            const auto& fragment=model.fragments[fragment_at];
            termaid47_require(fragment.kind==(type==12?"alt":"par")&&fragment.label==nonwrap42_text(event.get("message").as_str(),work)&&fragment.parent==(stack.empty()?-1:stack.back()),"Nonwrap42 raw fragment type/parent/label");
            ordered(EventKind::Open,static_cast<int>(fragment_at));stack.push_back(static_cast<int>(fragment_at++));return;
        }
        if(type==13||type==20){
            termaid47_require(!stack.empty()&&event.get("message").is_str(),"Nonwrap42 raw divider has parent");const auto index=static_cast<std::size_t>(stack.back());const auto& fragment=model.fragments[index];auto& part=dividers[index];
            termaid47_require(fragment.kind==(type==13?"alt":"par")&&static_cast<std::size_t>(part)<fragment.dividers.size()&&fragment.dividers[static_cast<std::size_t>(part)]==nonwrap42_text(event.get("message").as_str(),work),"Nonwrap42 complete raw divider label/order");
            ordered(EventKind::Divide,static_cast<int>(index),part++);return;
        }
        if(type==14||type==21){
            termaid47_require(!stack.empty(),"Nonwrap42 raw fragment close has parent");const auto index=static_cast<std::size_t>(stack.back());
            termaid47_require(model.fragments[index].kind==(type==14?"alt":"par")&&dividers[index]==static_cast<int>(model.fragments[index].dividers.size()),"Nonwrap42 complete raw fragment close");
            ordered(EventKind::Close,static_cast<int>(index));stack.pop_back();return;
        }
        throw std::runtime_error("Unconsumed Nonwrap42 raw event kind");
    });
    termaid47_require(message_at==model.messages.size()&&note_at==model.notes.size()&&fragment_at==model.fragments.size()&&order_at==model.order.size()&&stack.empty(),"Nonwrap42 every complete field/event consumed");
    for(std::size_t n=0;n<model.messages.size();++n){work.spend();termaid47_require(from_seen[n]==model.messages[n].central_from&&to_seen[n]==model.messages[n].central_to,"Nonwrap42 every central raw record consumed");}
    termaid47_require(raw.get("createdActors").is_obj()&&!raw.get("createdActors").size()&&raw.get("destroyedActors").is_obj()&&!raw.get("destroyedActors").size(),"Nonwrap42 lifetime source is not silently omitted");
    termaid47_require(raw.get("notes").is_arr()&&raw.get("notes").size()==model.notes.size()&&raw.get("boxes").is_arr()&&raw.get("boxes").size()==model.boxes.size(),"Nonwrap42 complete Note/group collections");
    std::size_t raw_note_at=0;
    raw.get("notes").iter([&](JsonVal note){
        const auto& expected=model.notes[raw_note_at++];
        termaid47_require(note.get("actor").is_str()&&note.get("placement").is_int()&&note.get("message").is_str()&&note.get("wrap").is_bool()&&!note.get("wrap").as_bool(),"Nonwrap42 independent raw Note collection");
        const auto placement=note.get_int("placement");
        termaid47_require(expected.actors.size()==1&&expected.actors[0]==actor_index(note.get("actor").as_str())&&expected.position==(placement==0?"left":placement==1?"right":"invalid")&&expected.text==nonwrap42_text(note.get("message").as_str(),work),"Nonwrap42 every independent raw Note field");
    });
    std::size_t group_at=0;
    raw.get("boxes").iter([&](JsonVal box){
        const auto& group=model.boxes[group_at++];termaid47_require(box.get("wrap").is_bool()&&!box.get("wrap").as_bool()&&box.get("actorKeys").is_arr()&&box.get("actorKeys").size()==group.actors.size(),"Nonwrap42 full raw box/wrap");
        std::size_t n=0;box.get("actorKeys").iter([&](JsonVal id){termaid47_require(id.is_str()&&actor_index(id.as_str())==group.actors[n++],"Nonwrap42 full source group membership");});
        const auto caption=box.get("name");termaid47_require(caption.is_null()||caption.is_str(),"Nonwrap42 raw box caption type");
        termaid47_require(group.title==(caption.is_null()?std::string{}:nonwrap42_text(caption.as_str(),work)),"Nonwrap42 absent caption is not invented");
        const auto fill=box.get_string("fill");bool uncolored=false;
        if(group.color.empty()&&fill=="transparent"){
            work.spend(group.title.size()*3+32);const auto declaration="box"+(group.title.empty()?std::string{}:" "+group.title);
            contract.get("source_statements_consumed").iter([&](JsonVal statement){work.spend(statement.get("text").as_str().size()+1);uncolored|=statement.get("text").as_str()==declaration;});
        }
        termaid47_require(group.color==fill||uncolored,"Nonwrap42 raw default fill differs only from source-authored color disclosure");
    });
    const auto title=raw.get("title");termaid47_require(title.is_null()||title.is_str(),"Nonwrap42 raw title type");bool source_title=false;
    if(title.is_null()&&!model.title.empty())contract.get("source_config").iter([&](JsonVal config){
        const auto authored=config.get("literal_fields_before_primary_admission").get("title");work.spend();
        if(authored.is_str()){work.spend(authored.as_str().size()+1);source_title|=authored.as_str()==model.title;}
    });
    termaid47_require(title.is_str()?nonwrap42_text(title.as_str(),work)==model.title:(model.title.empty()||source_title),"Nonwrap42 source-authored title adaptation");
    termaid47_require(contract.get("raw_metadata_retained").is_bool()&&contract.get("raw_metadata_retained").as_bool()&&contract.get("original_predicates_still_pending").is_bool()&&contract.get("original_predicates_still_pending").as_bool(),"Nonwrap42 original metadata predicates remain independent");
    for(const std::string_view key:{"accTitle","accDescr"})termaid47_require(joined683_canonical(raw.get(key),work)==joined683_canonical(contract.get("primary_accessibility_values").get(key),work),"Nonwrap42 full a11y values retained");
    contract.get("source_config").iter([&](JsonVal config){nonwrap42_span(config.get("source_span"),source,work);});
    contract.get("interactions_in_source_order").iter([&](JsonVal command){nonwrap42_span(command.get("source_span"),source,work);});
}
Termaid47Mutations nonwrap42_adversaries(const Grid& good,const Model& model,std::size_t copy_charge) {
    Termaid47Mutations out;
    auto attempt=[&](std::string_view name,auto alter){
        Work work;work.spend(copy_charge);auto wrong=model;alter(wrong);
        try{check_event_model(wrong,work);}catch(const std::runtime_error& error){if(termaid47_resource(error.what()))throw;++out.skipped_schema[std::string(name)];return;}
        const auto errors=validate(good,wrong,work.remaining);
        for(const auto& error:errors)if(termaid47_resource(error))throw std::runtime_error("Nonwrap42 adversary resource failure is not geometry evidence: "+error);
        ++out.executed[std::string(name)];if(errors.empty())out.errors.emplace_back("Accepted schema-preserving Nonwrap42 adversary: "+std::string(name));
    };
    auto different=[](const std::string& value){return value=="Wrong"?std::string("Other"):std::string("Wrong");};
    for(std::size_t n=0;n<model.actors.size();++n){
        attempt("actor_alias",[&](Model& wrong){wrong.actors[n].label=different(wrong.actors[n].label);});
        attempt("actor_role",[&](Model& wrong){wrong.actors[n].role=wrong.actors[n].role==Role::Participant?Role::Actor:Role::Participant;});
    }
    for(std::size_t n=0;n<model.messages.size();++n){
        attempt("message_label",[&](Model& wrong){wrong.messages[n].label=different(wrong.messages[n].label);});
        attempt("message_arrow",[&](Model& wrong){wrong.messages[n].arrow=wrong.messages[n].arrow==Arrow::Cross?Arrow::Filled:Arrow::Cross;});
        attempt("message_stroke",[&](Model& wrong){wrong.messages[n].dashed=!wrong.messages[n].dashed;});
        attempt("number_visibility",[&](Model& wrong){wrong.messages[n].number=wrong.messages[n].number.empty()?"7":"";});
        if(!model.messages[n].number.empty())attempt("number_value",[&](Model& wrong){wrong.messages[n].number=wrong.messages[n].number=="7"?"8":"7";});
        attempt("central_from",[&](Model& wrong){wrong.messages[n].central_from=!wrong.messages[n].central_from;});
        attempt("central_to",[&](Model& wrong){wrong.messages[n].central_to=!wrong.messages[n].central_to;});
        if(model.actors.size()>1)attempt("business_endpoint",[&](Model& wrong){wrong.messages[n].to=(wrong.messages[n].to+1)%static_cast<int>(wrong.actors.size());});
        attempt("message_erasure",[&](Model& wrong){
            wrong.messages.erase(wrong.messages.begin()+static_cast<std::ptrdiff_t>(n));
            std::erase_if(wrong.order,[&](const OrderedEvent& event){return event.kind==EventKind::Message&&event.index==static_cast<int>(n);});
            for(auto& event:wrong.order)if(event.kind==EventKind::Message&&event.index>static_cast<int>(n))--event.index;
            for(auto& note:wrong.notes)if(note.after>=static_cast<int>(n))--note.after;
        });
    }
    if(!model.title.empty())attempt("title",[&](Model& wrong){wrong.title=different(wrong.title);});
    for(std::size_t n=0;n<model.notes.size();++n){
        attempt("note_text",[&](Model& wrong){wrong.notes[n].text=different(wrong.notes[n].text);});
        attempt("note_position",[&](Model& wrong){wrong.notes[n].position=wrong.notes[n].position=="left"?"right":"left";});
    }
    std::size_t expected_dividers=0;
    for(std::size_t n=0;n<model.fragments.size();++n){
        expected_dividers+=model.fragments[n].dividers.size();
        attempt("fragment_label",[&](Model& wrong){wrong.fragments[n].label=different(wrong.fragments[n].label);});
        for(std::size_t part=0;part<model.fragments[n].dividers.size();++part)attempt("fragment_divider",[&](Model& wrong){wrong.fragments[n].dividers[part]=different(wrong.fragments[n].dividers[part]);});
    }
    for(std::size_t n=0;n<model.boxes.size();++n){
        attempt("box_title",[&](Model& wrong){wrong.boxes[n].title=different(wrong.boxes[n].title);});
        attempt("box_color",[&](Model& wrong){wrong.boxes[n].color=wrong.boxes[n].color=="red"?"blue":"red";});
        attempt("box_erasure",[&](Model& wrong){wrong.boxes.erase(wrong.boxes.begin()+static_cast<std::ptrdiff_t>(n));});
    }
    Work work;work.spend(good.cells.size()*4+64);auto orphan=good;bool placed=false;
    for(int x=good.width-1;x>=0;--x){work.spend();if(good.at(x,0)!=" ")continue;orphan.put(x,0,"┼");placed=true;break;}
    if(!placed)out.errors.emplace_back("Nonwrap42 orphan has no independent blank witness");
    else{
        const auto errors=validate(orphan,model,work.remaining);
        for(const auto& error:errors)if(termaid47_resource(error))throw std::runtime_error("Nonwrap42 orphan resource failure is not geometry evidence: "+error);
        ++out.executed["orphan_ink"];if(errors.empty())out.errors.emplace_back("Accepted unrelated Nonwrap42 ink");
    }
    const auto visible=std::ranges::count_if(model.messages,[](const Message& message){return !message.number.empty();});
    for(const auto& [name,count]:std::array<std::pair<std::string_view,std::size_t>,20>{{
        {"actor_alias",model.actors.size()},{"actor_role",model.actors.size()},
        {"message_label",model.messages.size()},{"message_arrow",model.messages.size()},{"message_stroke",model.messages.size()},
        {"number_visibility",model.messages.size()},{"number_value",static_cast<std::size_t>(visible)},
        {"central_from",model.messages.size()},{"central_to",model.messages.size()},
        {"business_endpoint",model.actors.size()>1?model.messages.size():0u},{"message_erasure",model.messages.size()},
        {"title",model.title.empty()?0u:1u},{"note_text",model.notes.size()},{"note_position",model.notes.size()},
        {"fragment_label",model.fragments.size()},{"fragment_divider",expected_dividers},
        {"box_title",model.boxes.size()},{"box_color",model.boxes.size()},{"box_erasure",model.boxes.size()},{"orphan_ink",1u}}})
        if(out.executed[std::string(name)]!=static_cast<int>(count))out.errors.emplace_back("Nonwrap42 schedule-preserving mutation lower bound: "+std::string(name));
    return out;
}
