    EXPECT_EQ(actors,100);EXPECT_EQ(messages,113);EXPECT_EQ(notes,4);EXPECT_EQ(fragments,2);EXPECT_EQ(boxes,3);EXPECT_EQ(events,124);EXPECT_EQ(dividers,3);EXPECT_EQ(visible,48);EXPECT_EQ(central_from,19);EXPECT_EQ(central_to,19);
