TEST(MermaidMermanNonwrap42Native, All42WholeSourcesRequireIndependentTypedGeometryAndSemanticAdversaries) {
    Work setup;const auto bytes=joined683_fixture(kNonwrap42FactsPath,kNonwrap42FactsSha,setup);
    const auto facts=json::parse(bytes);ASSERT_TRUE(facts);ASSERT_EQ(facts->root().get("cases").size(),280u);
    json::JsonMutDoc report;auto root=report.object(),records=root.make_arr();
    root.set("kind","complete_merman_nonwrap42_source_first_native_geometry");root.set("facts_sha256",std::string(kNonwrap42FactsSha));
    root.set("qualification","42 independently source-reviewed whole Models. Old150 and remaining88 input/raw/Model rows retained. No new683 join or original metadata/API/pixel predicate certification.");
    int selected=0,matches=0,unmet=0,oracle_errors=0,observation_errors=0,mutated=0,header_only=0;
    std::map<std::string,int> executed,skipped;
    facts->root().get("cases").iter([&](JsonVal item){
        if(!item.get("nonwrap42_source_contract").is_obj())return;
        Work work;work.spend(item.get("input").as_str().size()*3+item.get("id").as_str().size()*2+512);
        ++selected;const auto id=item.get_string("id"),source=item.get_string("input");SCOPED_TRACE(id);
        auto row=records.make_obj();row.set("id",id);row.set("input_sha256",item.get_string("input_sha256"));row.set("native_model_sha256",item.get_string("native_model_sha256"));
        std::string phase="source_model_decode",outcome;std::vector<std::string> errors,observations;bool mutations_done=false;
        try{
            termaid47_require(loom::utils::crypto::sha256(source)==item.get_string("input_sha256"),"Nonwrap42 complete source digest");
            termaid47_require(item.get("native_model").is_obj()&&item.get_string("number_encoding")=="DisplayText","Nonwrap42 complete DisplayText Model");
            const auto encoded=joined683_canonical(item.get("native_model"),work);
            termaid47_require(loom::utils::crypto::sha256(encoded)==item.get_string("native_model_sha256"),"Nonwrap42 complete native Model digest");
            work.spend(encoded.size()*8+64);const auto model=lifecycle_fact_model(item.get("native_model"),NumberFactEncoding::DisplayText);check_event_model(model,work);
            if(model.messages.empty())++header_only;
            phase="public_render";const auto node=loom::ui::render_markdown(fenced(source,"mermaid")),plain_node=loom::ui::render_markdown(fenced(source,"text"));
            node->ComputeRequirement();plain_node->ComputeRequirement();const int height=std::min(1040,std::max(40,std::max(node->requirement().min_y,plain_node->requirement().min_y)+12));
            phase="public_capture";const auto wide=capture(node,240,height),plain=capture(plain_node,240,height),narrow=capture(node,40,height),small_plain=capture(plain_node,40,height),restored=capture(node,240,height);
            row.set("wide_source_fallback",wide==plain);row.set("narrow_source_fallback",narrow==small_plain);row.set("wide_frame_sha256",lifecycle_frame_hash(wide));row.set("narrow_frame_sha256",lifecycle_frame_hash(narrow));row.set("restored_frame_sha256",lifecycle_frame_hash(restored));row.set("frame_height",height);
            if(wide!=restored)observations.emplace_back("Nonwrap42 same-node restoration changed cells");
            for(const auto* frame:{&wide,&narrow,&restored})if(!complete_sequence_sentinel(*frame))observations.emplace_back("Nonwrap42 complete physical sentinel missing/repeated/changed");
            if(narrow!=small_plain){phase="narrow_native_geometry";const auto small=validate(narrow,model,work.remaining);errors.insert(errors.end(),small.begin(),small.end());}
            if(wide==plain){++unmet;outcome="source_positive_unmet";}
            else{
                phase="complete_native_geometry";const auto full=validate(wide,model,work.remaining);errors.insert(errors.end(),full.begin(),full.end());
                if(errors.empty()&&observations.empty()){
                    phase="schema_preserving_adversaries";const auto copy_charge=encoded.size()*8+(model.order.size()+2)*32+512;
                    const auto adversaries=nonwrap42_adversaries(wide,model,copy_charge);errors.insert(errors.end(),adversaries.errors.begin(),adversaries.errors.end());
                    auto counts=row.make_obj(),invalid=row.make_obj();
                    for(const auto& [name,count]:adversaries.executed){counts.set(name,count);executed[name]+=count;}
                    for(const auto& [name,count]:adversaries.skipped_schema){invalid.set(name,count);skipped[name]+=count;}
                    row.add("geometry_mutations_executed",counts);row.add("schema_invalid_candidates_not_geometry",invalid);mutations_done=true;++mutated;
                }
                outcome=errors.empty()&&observations.empty()?"native_geometry_match":"native_geometry_or_mutation_error";
                if(errors.empty()&&observations.empty())++matches;
            }
        }catch(const std::exception& error){errors.emplace_back(error.what());outcome=phase+"_exception";}
        if(!errors.empty())++oracle_errors;
        if(!observations.empty())++observation_errors;
        row.set("native_outcome",outcome);row.set("mutations_executed",mutations_done);
        auto failures=row.make_arr(),seen=row.make_arr();for(const auto& error:errors)failures.append(root.make_str(error));for(const auto& error:observations)seen.append(root.make_str(error));row.add("native_errors",failures);row.add("observation_errors",seen);records.append(row);
    });
    root.set("whole280_sources",280);root.set("complete_native_Models_in_asset",192);root.set("old150_retained",150);root.set("remaining_source_profiles_pending",88);
    root.set("selected_nonwrap42_sources",selected);root.set("native_geometry_matches",matches);root.set("source_positive_unmet",unmet);root.set("execution_or_native_errors",oracle_errors);root.set("observation_errors",observation_errors);root.set("sources_with_executed_mutations",mutated);root.set("header_only_drawing_sources",header_only);
    auto counts=root.make_obj(),invalid=root.make_obj();for(const auto& [name,count]:executed)counts.set(name,count);for(const auto& [name,count]:skipped)invalid.set(name,count);root.add("geometry_mutations_executed",counts);root.add("schema_invalid_candidates_not_geometry",invalid);root.add("cases",records);report.set_root(root);
    std::filesystem::create_directories(LOOM_MERMAID_REPORT_DIR);std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR)/"mermaid-merman-nonwrap42-source-semantics.json");output<<report.to_string()<<'\n';ASSERT_TRUE(output.good());
    EXPECT_EQ(selected,42);EXPECT_EQ(header_only,6);EXPECT_EQ(matches,42);EXPECT_EQ(unmet,0);EXPECT_EQ(oracle_errors,0);EXPECT_EQ(observation_errors,0);EXPECT_EQ(mutated,matches);
    if(matches==42){
        for(const auto& [name,count]:std::array<std::pair<std::string_view,int>,20>{{
            {"actor_alias",100},{"actor_role",100},{"message_label",113},{"message_arrow",113},{"message_stroke",113},
            {"number_visibility",113},{"number_value",48},{"central_from",113},{"central_to",113},
            {"business_endpoint",112},{"message_erasure",113},{"title",3},{"note_text",4},{"note_position",4},
            {"fragment_label",2},{"fragment_divider",3},{"box_title",3},{"box_color",3},{"box_erasure",3},{"orphan_ink",42}}})
            EXPECT_EQ(executed[std::string(name)],count)<<name;
    }
    // Remaining88 are retained source obligations, not successful drawings.
    // The unchanged full280/full683 gates keep that unresolved scope visible.
}

