constexpr std::string_view kOfficialFragment6FactsPath="mermaid_native/sequence_official_role_fragment6_facts.json";
constexpr std::string_view kOfficialFragment6FactsSha="11099c79ad2743267e943ae9343604497a8d72a6351bb7f7f421e3841843c21d";
json::JsonDoc official_fragment6_document() {
    Work setup;const auto bytes=joined683_fixture(kOfficialFragment6FactsPath,kOfficialFragment6FactsSha,setup);
    auto doc=json::parse(bytes);official_role38_require(doc.has_value(),"Official fragment6 malformed source facts");
    official_role38_require(doc->root().get_int("schema")==1&&doc->root().get("cases").is_arr()&&doc->root().get("cases").size()==3,"Official fragment6 complete case inventory");
    return std::move(*doc);
}
std::vector<std::string_view> official_fragment6_statements(std::string_view source,Work& work) {
    work.spend(source.size()*3+64);std::vector<std::string_view> result;
    while(!source.empty()) {
        const auto end=source.find('\n');auto line=source.substr(0,end);
        source=end==std::string_view::npos?std::string_view{}:source.substr(end+1);
        const auto first=line.find_first_not_of(" \t\r"),last=line.find_last_not_of(" \t\r");
        if(first!=std::string_view::npos)result.push_back(line.substr(first,last-first+1));
    }
    return result;
}
