struct Half21Witness {
    Arrow arrow;bool reverse;std::string_view right,left;Arrow opposite_owner,other_shape,other_fill;
};
// Independently authored hand literals. This table is not used by the oracle.
constexpr std::array<Half21Witness,8> kHalf21Hands{{
    {Arrow::FilledHalfTop,false,"◢","◣",Arrow::FilledHalfTopReverse,Arrow::FilledHalfBottom,Arrow::OpenHalfTop},
    {Arrow::FilledHalfBottom,false,"◥","◤",Arrow::FilledHalfBottomReverse,Arrow::FilledHalfTop,Arrow::OpenHalfBottom},
    {Arrow::OpenHalfTop,false,"╲","╱",Arrow::OpenHalfTopReverse,Arrow::OpenHalfBottom,Arrow::FilledHalfTop},
    {Arrow::OpenHalfBottom,false,"╱","╲",Arrow::OpenHalfBottomReverse,Arrow::OpenHalfTop,Arrow::FilledHalfBottom},
    {Arrow::FilledHalfTopReverse,true,"◢","◣",Arrow::FilledHalfTop,Arrow::FilledHalfBottomReverse,Arrow::OpenHalfTopReverse},
    {Arrow::FilledHalfBottomReverse,true,"◥","◤",Arrow::FilledHalfBottom,Arrow::FilledHalfTopReverse,Arrow::OpenHalfBottomReverse},
    {Arrow::OpenHalfTopReverse,true,"╲","╱",Arrow::OpenHalfTop,Arrow::OpenHalfBottomReverse,Arrow::FilledHalfTopReverse},
    {Arrow::OpenHalfBottomReverse,true,"╱","╲",Arrow::OpenHalfBottom,Arrow::OpenHalfTopReverse,Arrow::FilledHalfBottomReverse}}};
struct Half21Hand {
    Grid grid;Model model;int hx,hy,port_x,port_y,shaft_x,shaft_y;
};
void half21_header(Grid& grid,int left,int right,std::string_view label) {
    grid.put(left,1,"┌");grid.put(right,1,"┐");grid.put(left,3,"└");grid.put(right,3,"┘");
    for(int x=left+1;x<right;++x){grid.put(x,1,"─");grid.put(x,3,"─");}
    grid.put(left,2,"│");grid.put(right,2,"│");
    grid.text((left+right+1)/2-ftxui::string_width(std::string(label))/2,2,label);
}
Half21Hand half21_hand(const Half21Witness& witness,bool leftward,bool dashed,
                       bool self=false,bool central_from=false,bool central_to=false) {
    Grid grid{60,28,std::vector<std::string>(60*28," ")};
    half21_header(grid,5,11,"A");
    Model model;model.actors={{"A","A"}};
    if(!self){half21_header(grid,43,49,"B");model.actors.push_back({"B","B"});}
    for(int y=4;y<grid.height;++y){grid.put(8,y,"│");if(!self)grid.put(46,y,"│");}
    const int from=self?8:leftward?46:8,to=self?8:leftward?8:46;
    const int source_index=self?0:leftward?1:0,target_index=self?0:leftward?0:1;
    model.messages.push_back({source_index,target_index,"half",dashed,witness.arrow,central_from,central_to,{}});
    model.order={{EventKind::Message,0}};
    const int finish=self?11:8,turn=28,depart=self?1:leftward?-1:1,arrival=self?-1:depart;
    const auto horizontal=dashed?"┄":"─";
    grid.text(self?12:18,7,"half");
    if(self){
        for(int x=9;x<turn;++x){grid.put(x,8,horizontal);grid.put(x,finish,horizontal);}
        grid.put(turn,8,"┐");grid.put(turn,finish,"┘");
        for(int y=9;y<finish;++y)grid.put(turn,y,dashed?"┆":"│");
    }else for(int x=9;x<46;++x)grid.put(x,8,horizontal);
    const int sx=from+(central_from?depart:0),tx=to-(central_to?arrival:0);
    if(central_from)grid.put(from,8,"○");
    if(central_to)grid.put(to,finish,"○");
    if(witness.reverse){
        grid.put(sx,8,-depart>0?witness.right:witness.left);
        grid.put(tx,finish,central_to?horizontal:arrival>0?"┤":"├");
    }else{
        grid.put(sx,8,central_from?horizontal:depart>0?"├":"┤");
        grid.put(tx,finish,arrival>0?witness.right:witness.left);
    }
    return {std::move(grid),std::move(model),witness.reverse?sx:tx,witness.reverse?8:finish,
        witness.reverse?tx:sx,witness.reverse?finish:8,self?16:26,8};
}
TEST(MermaidHalf21Oracle, EveryHalfShapeOwnsExactlyOneAuthoredEndpointInBothDirectionsAndStyles) {
    int positives=0;
    for(const auto& witness:kHalf21Hands)for(const bool leftward:{false,true})for(const bool dashed:{false,true}){
        SCOPED_TRACE(static_cast<int>(witness.arrow));
        SCOPED_TRACE(leftward);
        SCOPED_TRACE(dashed);
        const auto hand=half21_hand(witness,leftward,dashed);
        const auto good=validate(hand.grid,hand.model);ASSERT_TRUE(good.empty())<<(good.empty()?"":good.front());++positives;
        first19_reject_model(hand.grid,hand.model,[&](Model& wrong){wrong.messages[0].arrow=witness.opposite_owner;});
        first19_reject_model(hand.grid,hand.model,[&](Model& wrong){wrong.messages[0].arrow=witness.other_shape;});
        first19_reject_model(hand.grid,hand.model,[&](Model& wrong){wrong.messages[0].arrow=witness.other_fill;});
        first19_reject_model(hand.grid,hand.model,[](Model& wrong){std::swap(wrong.messages[0].from,wrong.messages[0].to);});
        first19_reject_model(hand.grid,hand.model,[](Model& wrong){wrong.messages[0].dashed=!wrong.messages[0].dashed;});
        first19_reject_grid_mutation(hand.grid,hand.model,[&](Grid& wrong){wrong.put(hand.hx,hand.hy,"▶");});
        first19_reject_grid_mutation(hand.grid,hand.model,[&](Grid& wrong){wrong.put(hand.hx,hand.hy,hand.grid.at(hand.hx,hand.hy)==witness.right?witness.left:witness.right);});
        first19_reject_grid_mutation(hand.grid,hand.model,[&](Grid& wrong){wrong.put(hand.hx,hand.hy," ");});
        first19_reject_grid_mutation(hand.grid,hand.model,[&](Grid& wrong){wrong.put(hand.port_x,hand.port_y,"┼");});
        first19_reject_grid_mutation(hand.grid,hand.model,[&](Grid& wrong){wrong.put(hand.port_x,hand.port_y,witness.right);});
        first19_reject_grid_mutation(hand.grid,hand.model,[&](Grid& wrong){wrong.put(hand.shaft_x,hand.shaft_y,dashed?"─":"┄");});
        first19_reject_grid_mutation(hand.grid,hand.model,[&](Grid& wrong){wrong.put(hand.shaft_x,hand.shaft_y,"┼");});
        first19_reject_grid_mutation(hand.grid,hand.model,[](Grid& wrong){wrong.put(18,7,"x");});
        first19_reject_grid_mutation(hand.grid,hand.model,[](Grid& wrong){wrong.put(56,0,"╱");});
    }
    EXPECT_EQ(positives,32);
}
