TEST(MermaidMerman280Native, VersionedHalfAdmissionRetainsEveryOriginalFieldAndAddsExactlyTwentyOneCompleteModels) {
    Work old_setup,admitted_setup,half_setup;
    const auto old_bytes=joined683_fixture(kMerman280FactsPath,kMerman280FactsSha,old_setup);
    const auto admitted_bytes=joined683_fixture(kMerman280AdmittedFactsPath,kMerman280AdmittedFactsSha,admitted_setup);
    const auto half_bytes=joined683_fixture(kHalf21SourcePath,kHalf21SourceSha,half_setup);
    const auto old=json::parse(old_bytes),admitted=json::parse(admitted_bytes),half=json::parse(half_bytes);
    ASSERT_TRUE(old&&admitted&&half);
    ASSERT_EQ(admitted->root().get_string("kind"),"merman_complete280_source_first_native_facts");
    ASSERT_EQ(admitted->root().get_string("parent_native_facts_sha256"),kMerman280FactsSha);
    ASSERT_EQ(admitted->root().get_string("half21_source_contract_sha256"),kHalf21SourceSha);
    ASSERT_EQ(admitted->root().get_string("original_manifest_sha256"),kMerman280ManifestSha);
    ASSERT_EQ(old->root().get("cases").size(),280u);ASSERT_EQ(admitted->root().get("cases").size(),280u);
    ASSERT_EQ(half->root().get("cases").size(),21u);
    ASSERT_EQ(std::filesystem::file_size(std::filesystem::path(LOOM_TESTS_DIR)/"fixtures/mermaid_terminal/merman/cases.json"),static_cast<std::uintmax_t>(16326956));
    const auto vendor_bytes=fixture_bytes("mermaid_terminal/merman/cases.json");
    ASSERT_EQ(vendor_bytes.size(),16326956u);ASSERT_EQ(loom::utils::crypto::sha256(vendor_bytes),kMerman280ManifestSha);
    const auto vendor=json::parse(vendor_bytes);ASSERT_TRUE(vendor);
    // All owning JsonDocs outlive these views. Fixture setup never resets or
    // increases the per-scene Work used by complete geometry validation.
    std::map<std::string,JsonVal> prior,proposals;
    old->root().get("cases").iter([&](JsonVal row){
        old_setup.spend(row.get("id").as_str().size()+3);
        ASSERT_TRUE(prior.emplace(row.get_string("id"),row).second);
    });
    half->root().get("cases").iter([&](JsonVal row){
        half_setup.spend(row.get("id").as_str().size()+3);
        ASSERT_TRUE(row.get("native_model").is_null());
        ASSERT_TRUE(proposals.emplace(row.get_string("id"),row).second);
    });
    constexpr std::array<std::string_view,7> admission_fields{{
        "bulk_complete_model_authoring_eligible","native_model","native_model_schema",
        "native_model_sha256","native_model_status","native_shape_schema_blockers","number_encoding"}};
    std::set<std::string> seen,consumed;
    int unchanged=0,old_models=0,new_models=0,models=0,pending=0,core_admitted=0;
    int new_actors=0,new_messages=0,new_order=0;
    admitted->root().get("cases").iter([&](JsonVal row){
        Work work;work.spend(row.get("id").as_str().size()*2+row.get("input").as_str().size()*3+512);
        const auto id=row.get_string("id");SCOPED_TRACE(id);
        ASSERT_TRUE(seen.insert(id).second);ASSERT_TRUE(prior.contains(id));
        const auto before=prior.at(id);ASSERT_EQ(row.size(),before.size());
        ASSERT_TRUE(row.get("native_model").is_obj()||row.get("native_model").is_null());
        if(row.get("native_model").is_obj())++models;else ++pending;
        const auto original=pointer(vendor->root(),row.get_string("vendor_case_pointer"));
        ASSERT_EQ(original.get_string("id"),id);ASSERT_EQ(original.get_string("family"),"sequence");
        ASSERT_EQ(original.get_string("input"),row.get_string("input"));
        ASSERT_EQ(original.get_string("sha256"),row.get_string("input_sha256"));
        ASSERT_EQ(loom::utils::crypto::sha256(row.get("input").as_str()),row.get_string("input_sha256"));
        if(!proposals.contains(id)){
            ASSERT_EQ(joined683_canonical(row,work),joined683_canonical(before,work));++unchanged;
            if(before.get("native_model").is_obj())++old_models;
            return;
        }
        const auto proposal=proposals.at(id);ASSERT_TRUE(consumed.insert(id).second);
        ASSERT_TRUE(before.get("native_model").is_null());ASSERT_TRUE(row.get("native_model").is_obj());
        before.iter_obj([&](JsonVal key,JsonVal value){
            work.spend(key.as_str().size()+admission_fields.size()+1);
            if(std::ranges::find(admission_fields,key.as_str())!=admission_fields.end())return;
            ASSERT_EQ(joined683_canonical(row.get(key.as_str()),work),joined683_canonical(value,work))<<key.as_str();
        });
        ASSERT_EQ(row.get_string("input"),proposal.get_string("input"));
        ASSERT_EQ(row.get_string("input_sha256"),proposal.get_string("input_sha256"));
        ASSERT_EQ(row.get_string("vendor_case_pointer"),proposal.get_string("vendor_case_pointer"));
        ASSERT_EQ(row.get_string("case_canonical_sha256"),proposal.get_string("case_canonical_sha256"));
        ASSERT_TRUE(row.get("core_member").is_bool());ASSERT_TRUE(row.get("core_member").as_bool());++core_admitted;
        for(const auto& fields:std::array<std::pair<std::string_view,std::string_view>,4>{{
            {"physical_source_witnesses","physical_source_witnesses_sha256"},
            {"original_expectation","original_expectation_sha256"},
            {"original_provenance","original_provenance_sha256"},
            {"primary_field_accounting","primary_field_accounting_sha256"}}}){
            ASSERT_EQ(loom::utils::crypto::sha256(joined683_canonical(proposal.get(fields.first),work)),row.get_string(fields.second));
        }
        ASSERT_EQ(joined683_canonical(row.get("complete_primary_model"),work),joined683_canonical(proposal.get("complete_primary_model"),work));
        ASSERT_EQ(joined683_canonical(row.get("native_model"),work),joined683_canonical(proposal.get("proposed_native_model"),work));
        ASSERT_EQ(row.get_string("native_model_sha256"),proposal.get_string("proposed_native_model_sha256"));
        ASSERT_EQ(loom::utils::crypto::sha256(joined683_canonical(row.get("native_model"),work)),row.get_string("native_model_sha256"));
        ASSERT_TRUE(row.get("bulk_complete_model_authoring_eligible").is_bool());ASSERT_TRUE(row.get("bulk_complete_model_authoring_eligible").as_bool());
        ASSERT_EQ(row.get_string("native_model_schema"),"sequence_native_single_role_number_text/v1");
        ASSERT_EQ(row.get_string("number_encoding"),"DisplayText");
        ASSERT_EQ(row.get_string("native_model_status"),"independently_source_reviewed_half21_complete_native_profile");
        ASSERT_TRUE(row.get("native_shape_schema_blockers").is_arr());ASSERT_EQ(row.get("native_shape_schema_blockers").size(),0u);
        // The canonical precharge owns Model decode/copies as in all previous
        // source joins. No new Arrow converter, output inference or retry.
        const auto model=lifecycle_fact_model(row.get("native_model"),NumberFactEncoding::DisplayText);
        check_event_model(model,work);++new_models;
        new_actors+=static_cast<int>(model.actors.size());new_messages+=static_cast<int>(model.messages.size());new_order+=static_cast<int>(model.order.size());
    });
    EXPECT_EQ(seen.size(),280u);EXPECT_EQ(consumed.size(),21u);EXPECT_EQ(unchanged,259);EXPECT_EQ(old_models,150);
    EXPECT_EQ(new_models,21);EXPECT_EQ(models,171);EXPECT_EQ(pending,109);EXPECT_EQ(core_admitted,21);
    EXPECT_EQ(new_actors,40);EXPECT_EQ(new_messages,26);EXPECT_EQ(new_order,26);
    Work summary_work;
    EXPECT_EQ(joined683_canonical(admitted->root().get("summary").get("parent150_summary"),summary_work),joined683_canonical(old->root().get("summary"),summary_work));
    EXPECT_EQ(admitted->root().get("summary").get_int("complete_models"),171);
    EXPECT_EQ(admitted->root().get("summary").get_int("remaining_source_profiles"),109);
}
