TEST(MermaidMermanNonwrap42Native, UnknownDuplicateUnsafeAndIncompleteMetadataRemainsWholeSource) {
    for(const std::string prefix:{
        "%%{init: {'theme':'base',\"th\\u0065me\":\"dark\"}}%%\n",
        "%%{init: {'theme':'base',}}%%\n",
        "%%{init: {theme:'base'}}%%\n",
        "%%{init: {'securityLevel':'loose'}}%%\n",
        "%%{init: {'sequence':{'wrap':true}}}%%\n",
        "%%{init: {'sequence.wrap':false}}%%\n",
        "%%{init: {'config':{'sequence.wrap':false}}}%%\n",
        "%%{init: {'theme':'base'}\n",
        "%%{init: {'theme':'base'}}%% trailing\n",
        "---\nconfig:\n  look: classic\n  look: classic\n---\n",
        "---\nconfig:\n  sequence:\n    unknown: true\n---\n",
        "---\nconfig:\n  sequence:\n    forceMenus: [true]\n---\n"}) {
        SCOPED_TRACE(prefix);
        const auto source=prefix+"sequenceDiagram\nA->>B: ping\n";
        if(prefix=="%%{init: {'sequence':{'wrap':true}}}%%\n") EXPECT_TRUE(wrap227_migrated_public(source));
        else text7_expect_source(source);
    }
    for(const std::string_view fields:{"title: Plain\nconfig:\n", "config:\n  sequence:\n  theme: base\n", "config:\n  themeVariables:\n  theme: base\n"})
        text7_expect_source("---\n"+std::string(fields)+"---\nsequenceDiagram\nA->>B: ping\n");
    // Valid YAML title syntax, still an explicit old terminal-profile boundary.
    text7_expect_source("---\ntitle: \"nowrap:Literal\"\n---\nsequenceDiagram\nA->>B: ping\n");
    for(const std::string_view marker:{"\xef\xbb\xbf","\xe2\x80\x8b"})
        text7_expect_source("---\ntitle: A"+std::string(marker)+"B\n---\nsequenceDiagram\nA->>B: ping\n");
    // Preserve the existing open-box declaration-only terminal boundary.
    for(const std::string_view setter:{"links A: {}","accTitle: invisible"})
        text7_expect_source("sequenceDiagram\nbox Group\nparticipant A\n"+std::string(setter)+"\nend\nA->>B: ping\n");
    for(const std::string command:{
        "links A: {\"Docs\":\"x\",\"D\\u006fcs\":\"y\"}",
        "links A: {\"Docs\":2}",
        "links A: {\"Docs\":\"x\"} A->>B: decoy",
        "properties A: {\"payload\":{}} A->>B: decoy",
        "properties A: {\"payload\":\"raw; A->>B: decoy\"}",
        "properties A: {\"payload\":\"\\u0000\"}",
        "links A: {\"Docs\":\"raw # ordinary comment\"}",
        "link A: missing separator", "details A:", "accDescr {unterminated"}) {
        SCOPED_TRACE(command);text7_expect_source("sequenceDiagram\nA->>B: ping\n"+command+"\n");
    }
    for(const auto& bad:{std::string("x\x01y"),std::string("x\xc0\xafy")}) {
        text7_expect_source("sequenceDiagram\nA->>B: ping\nproperties A: {\"payload\":\""+bad+"\"}\n");
        text7_expect_source("sequenceDiagram\naccTitle: "+bad+"\nA->>B: ping\n");
        text7_expect_source("%%{init: {'config':{'actorFontFamily':'"+bad+"'}}}%%\nsequenceDiagram\nA->>B: ping\n");
    }
}

