TEST(MermaidMerman280Native, VersionedNonwrapAdmissionRetainsAll171ModelsAndEveryCompleteSourceField) {
    Work old_setup,current_setup,proposal_setup;
    const auto old_bytes=joined683_fixture(kMerman280AdmittedFactsPath,kMerman280AdmittedFactsSha,old_setup);
    const auto current_bytes=joined683_fixture(kMerman280CurrentFactsPath,kMerman280CurrentFactsSha,current_setup);
    const auto proposal_bytes=joined683_fixture(kNonwrap42FactsPath,kNonwrap42FactsSha,proposal_setup);
    const auto old=json::parse(old_bytes),current=json::parse(current_bytes),proposal=json::parse(proposal_bytes);
    ASSERT_TRUE(old&&current&&proposal);
    ASSERT_EQ(current->root().get_string("kind"),"merman_complete280_source_first_native_facts");
    ASSERT_EQ(current->root().get_string("parent_current171_asset_sha256"),kMerman280AdmittedFactsSha);
    ASSERT_EQ(current->root().get_string("nonwrap42_source_asset_sha256"),kNonwrap42FactsSha);
    ASSERT_EQ(current->root().get_string("original_manifest_sha256"),kMerman280ManifestSha);
    ASSERT_EQ(old->root().get("cases").size(),280u);ASSERT_EQ(current->root().get("cases").size(),280u);
    ASSERT_EQ(proposal->root().get("cases").size(),280u);
    // The existing immutable vendor-loader scope owns actual full manifest
    // bytes. No declared sidecar hash substitutes for reading that manifest.
    ASSERT_EQ(std::filesystem::file_size(std::filesystem::path(LOOM_TESTS_DIR)/"fixtures/mermaid_terminal/merman/cases.json"),static_cast<std::uintmax_t>(16326956));
    const auto vendor_bytes=fixture_bytes("mermaid_terminal/merman/cases.json");
    ASSERT_EQ(vendor_bytes.size(),16326956u);ASSERT_EQ(loom::utils::crypto::sha256(vendor_bytes),kMerman280ManifestSha);
    const auto vendor=json::parse(vendor_bytes);ASSERT_TRUE(vendor);
    // Every JsonDoc above owns all views until the complete assertions finish.
    std::map<std::string,JsonVal> prior,admissions;
    old->root().get("cases").iter([&](JsonVal row){
        old_setup.spend(row.get("id").as_str().size()+3);ASSERT_TRUE(prior.emplace(row.get_string("id"),row).second);
    });
    proposal->root().get("cases").iter([&](JsonVal row){
        proposal_setup.spend(row.get("id").as_str().size()+3);
        if(row.get("nonwrap42_source_contract").is_obj())ASSERT_TRUE(admissions.emplace(row.get_string("id"),row).second);
    });ASSERT_EQ(prior.size(),280u);ASSERT_EQ(admissions.size(),42u);
    std::set<std::string> seen,consumed;
    int unchanged=0,old_models=0,new_models=0,models=0,pending=0,core_new=0;
    int actors=0,messages=0,notes=0,fragments=0,boxes=0,events=0;
    std::array<int,6> complete_fields{};
    constexpr std::array<std::string_view,6> field_names{{"actors","messages","notes","fragments","boxes","order"}};
    current->root().get("cases").iter([&](JsonVal row){
        Work work;work.spend(row.get("id").as_str().size()*2+row.get("input").as_str().size()*3+512);
        const auto id=row.get_string("id"),source=row.get_string("input");SCOPED_TRACE(id);
        ASSERT_TRUE(seen.insert(id).second);ASSERT_TRUE(prior.contains(id));const auto before=prior.at(id);
        const auto original=pointer(vendor->root(),row.get_string("vendor_case_pointer"));
        ASSERT_EQ(original.get_string("id"),id);ASSERT_EQ(original.get_string("family"),"sequence");
        ASSERT_EQ(original.get_string("input"),source);ASSERT_EQ(original.get_string("sha256"),row.get_string("input_sha256"));
        ASSERT_EQ(loom::utils::crypto::sha256(source),row.get_string("input_sha256"));
        ASSERT_TRUE(row.get("native_model").is_obj()||row.get("native_model").is_null());
        if(row.get("native_model").is_obj()) {
            ++models;
            for(std::size_t n=0;n<field_names.size();++n){work.spend();complete_fields[n]+=static_cast<int>(row.get("native_model").get(field_names[n]).size());}
        } else ++pending;
        if(!admissions.contains(id)) {
            ASSERT_EQ(joined683_canonical(row,work),joined683_canonical(before,work));++unchanged;
            if(before.get("native_model").is_obj())++old_models;
            return;
        }
        ASSERT_TRUE(consumed.insert(id).second);ASSERT_TRUE(before.get("native_model").is_null());
        const auto selected=admissions.at(id);
        // Entire reviewed dictionary equality binds the complete source, raw
        // primary Model, witnesses, functions and adaptation, not just its SHA.
        ASSERT_EQ(joined683_canonical(row,work),joined683_canonical(selected,work));
        ASSERT_TRUE(row.get("core_member").is_bool());if(row.get("core_member").as_bool())++core_new;
        ASSERT_EQ(source,before.get_string("input"));ASSERT_EQ(row.get_string("input_sha256"),before.get_string("input_sha256"));
        ASSERT_EQ(row.get_string("vendor_case_pointer"),before.get_string("vendor_case_pointer"));
        ASSERT_EQ(row.get_string("case_canonical_sha256"),before.get_string("case_canonical_sha256"));
        ASSERT_EQ(row.get_string("number_encoding"),"DisplayText");ASSERT_EQ(row.get_string("native_model_schema"),"sequence_native_single_role_number_text/v1");
        const auto meaning=row.get("native_model");ASSERT_TRUE(meaning.is_obj());
        meaning.get("messages").iter([&](JsonVal message){work.spend();ASSERT_TRUE(message.get("number").is_str());});
        const auto encoded=joined683_canonical(meaning,work);
        ASSERT_EQ(loom::utils::crypto::sha256(encoded),row.get_string("native_model_sha256"));
        const auto contract=row.get("nonwrap42_source_contract");ASSERT_TRUE(contract.is_obj());
        ASSERT_EQ(contract.get_string("source_contract_sha256"),kNonwrap42ContractSha);
        ASSERT_EQ(loom::utils::crypto::sha256(joined683_canonical(contract,work)),row.get_string("nonwrap42_source_contract_sha256"));
        work.spend(encoded.size()*8+64);const auto model=lifecycle_fact_model(meaning,NumberFactEncoding::DisplayText);check_event_model(model,work);
        // This existing independent raw-event/source-span binding supplies
        // semantics beyond equality with a source-reviewed sidecar digest.
        nonwrap42_raw_binding(row,model,source,work);++new_models;
        actors+=static_cast<int>(model.actors.size());messages+=static_cast<int>(model.messages.size());notes+=static_cast<int>(model.notes.size());
        fragments+=static_cast<int>(model.fragments.size());boxes+=static_cast<int>(model.boxes.size());events+=static_cast<int>(model.order.size());
    });
    EXPECT_EQ(seen.size(),280u);EXPECT_EQ(consumed.size(),42u);EXPECT_EQ(unchanged,238);EXPECT_EQ(old_models,171);
    EXPECT_EQ(new_models,42);EXPECT_EQ(models,213);EXPECT_EQ(pending,67);EXPECT_EQ(core_new,38);
    EXPECT_EQ(actors,100);EXPECT_EQ(messages,113);EXPECT_EQ(notes,4);EXPECT_EQ(fragments,2);EXPECT_EQ(boxes,3);EXPECT_EQ(events,124);
    Work summary_work;const auto summary=current->root().get("summary");
    EXPECT_EQ(joined683_canonical(summary.get("parent171_summary"),summary_work),joined683_canonical(old->root().get("summary"),summary_work));
    for(std::size_t n=0;n<field_names.size();++n)EXPECT_EQ(summary.get("complete_model_fields").get_int(field_names[n]),complete_fields[n]);
    EXPECT_EQ(summary.get_int("complete_models"),213);EXPECT_EQ(summary.get_int("remaining_source_profiles"),67);
}
