std::string_view official_half16_trim(std::string_view text) {
    const auto first=text.find_first_not_of(" \t\r\n"),last=text.find_last_not_of(" \t\r\n");
    return first==std::string_view::npos?std::string_view{}:text.substr(first,last-first+1);
}
void official_half16_span(JsonVal span,const std::string& source,Work& work) {
    official_role38_require(span.is_obj()&&span.get("offset_utf8_bytes").is_int()&&span.get("byte_length").is_int(),"Official half16 physical span schema");
    const auto offset=span.get_int("offset_utf8_bytes"),length=span.get_int("byte_length");
    official_role38_require(offset>=0&&length>=0&&static_cast<std::uint64_t>(offset)<=source.size()&&static_cast<std::uint64_t>(length)<=source.size()-static_cast<std::size_t>(offset),"Official half16 physical span bounds");
    work.spend(static_cast<std::size_t>(length)*4+64);const auto text=span.get_string("text");
    official_role38_require(text.size()==static_cast<std::size_t>(length)&&source.compare(static_cast<std::size_t>(offset),text.size(),text)==0&&loom::utils::crypto::sha256(text)==span.get_string("sha256"),"Official half16 exact physical source span");
}
