        const auto pointers=row.get("model_pointers"),range=row.get("order_range");official_role38_require(pointers.is_arr()&&range.is_arr()&&range.size()==2u&&range.at(0).is_int()&&range.at(1).is_int(),"Config49 statement Model/episode range schema");
        official_role38_require(range.at(0).as_int()>=0&&range.at(1).as_int()>=range.at(0).as_int()&&static_cast<std::uint64_t>(range.at(1).as_int())<=model.get("order").size(),"Config49 complete episode range bounds");
        pointers.iter([&](JsonVal path){work.spend();official_role38_require(path.is_str()&&!path.as_str().empty(),"Config49 Model pointer type");const auto value=pointer(model,path.as_str());official_role38_require(static_cast<bool>(value),"Config49 physical pointer must resolve in whole Model");});
