    official_role38_require(path.starts_with("sequence/")&&path.find("..") == std::string_view::npos&&!body.empty()&&raw.size()<=65536&&body.size()<=65536,"Config49 safe complete source namespace/limit");
    work.spend(path.size()*4+raw.size()*6+body.size()*4+128);
