    official_role38_require(loom::utils::crypto::sha256(raw)==item.get_string("raw_sha256")&&loom::utils::crypto::sha256(body)==item.get_string("body_sha256"),"Config49 raw/body complete hashes");
    official_role38_require(item.get("body_offset_utf8_bytes").is_int()&&item.get_int("body_offset_utf8_bytes")>=0,"Config49 body offset type");const auto offset=static_cast<std::uint64_t>(item.get_int("body_offset_utf8_bytes"));
    official_role38_require(offset<=raw.size()&&raw.substr(static_cast<std::size_t>(offset))==body,"Config49 exact original body suffix");
    official_role38_require(fixture_bytes("mermaid_official/cases/"+std::string(path))==raw,"Config49 immutable raw fixture bytes");
    int found=0;manifest.get("fixtures").iter([&](JsonVal record){work.spend();if(record.get_string("path")!=path)return;++found;official_role38_require(joined683_canonical(record,work)==joined683_canonical(item.get("original_manifest_record"),work),"Config49 complete original manifest tuple");const auto diagnostic=record.get("diagnostic");official_role38_require(record.get_string("sha256")==item.get_string("raw_sha256")&&record.get("git_blob").is_str()&&diagnostic.get("offset").is_int()&&diagnostic.get_int("offset")==static_cast<std::int64_t>(offset)&&diagnostic.get_string("sha256")==item.get_string("body_sha256"),"Config49 original Git/blob/SHA/diagnostic binding");});
    official_role38_require(found==1,"Config49 original tuple must be unique");
    const auto model=item.get("full_native_model_candidate");config49_model_schema(model,work);
    official_role38_require(loom::utils::crypto::sha256(joined683_canonical(model,work))==item.get_string("model_canonical_sha256"),"Config49 complete seven-field Model digest");
