OfficialRole38Mutations config49_mutations(const Grid& good,const Model& model,std::size_t copy_charge) {
    auto out=official_role38_mutations(good,model);
    auto attempt=[&](std::string_view kind,auto mutate){
        Work work;work.spend(copy_charge);auto wrong=model;mutate(wrong);
        try{check_event_model(wrong,work);}catch(const std::runtime_error& error){if(termaid47_resource(error.what()))throw;++out.skipped_schema[std::string(kind)];return;}
        const auto rejected=validate(good,wrong,work.remaining);first19_no_resource_rejection(rejected);++out.executed[std::string(kind)];
        if(rejected.empty())out.errors.emplace_back("Accepted Config49 observable complete Model mutation: "+std::string(kind));
    };
    int half_count=0;
    for(std::size_t n=0;n<model.messages.size();++n) {
        attempt("number_visibility",[&](Model& wrong){wrong.messages[n].number=wrong.messages[n].number.empty()?"999":"";});
        attempt("number_value",[&](Model& wrong){wrong.messages[n].number=wrong.messages[n].number=="999"?"998":"999";});
        attempt("central_source_toggle",[&](Model& wrong){wrong.messages[n].central_from=!wrong.messages[n].central_from;});
        attempt("central_target_toggle",[&](Model& wrong){wrong.messages[n].central_to=!wrong.messages[n].central_to;});
        const auto hand=std::ranges::find_if(kHalf21Hands,[&](const auto& h){return h.arrow==model.messages[n].arrow;});
        if(hand!=kHalf21Hands.end()) {
            ++half_count;for(const auto replacement:{hand->opposite_owner,hand->other_shape,hand->other_fill})attempt("half_owner_shape_fill",[&](Model& wrong){wrong.messages[n].arrow=replacement;});
        }
        if(model.actors.size()>1) {
            attempt("sender_endpoint",[&](Model& wrong){wrong.messages[n].from=(wrong.messages[n].from+1)%static_cast<int>(wrong.actors.size());});
            attempt("self_nonself",[&](Model& wrong){auto& message=wrong.messages[n];message.to=message.from==message.to?(message.to+1)%static_cast<int>(wrong.actors.size()):message.from;});
        }
    }
    for(std::size_t n=0;n<model.notes.size();++n) {
        attempt("note_side",[&](Model& wrong){auto& note=wrong.notes[n];note.position=note.position=="left"?"right":"left";note.actors={note.actors.front()};});
        attempt("note_owner_complete",[&](Model& wrong){auto& note=wrong.notes[n];if(note.actors.size()>1)note.actors={note.actors.front()};else note.actors[0]=(note.actors[0]+1)%static_cast<int>(wrong.actors.size());});
        const auto note=std::ranges::find_if(model.order,[&](const OrderedEvent& e){return e.kind==EventKind::Note&&e.index==static_cast<int>(n);});
        official_role38_require(note!=model.order.end(),"Config49 Note chronology source event");
        // Move the complete Note across an adjacent business event and recompute
        // its zero-based prior index, including source Notes before message0.
        const auto at=static_cast<std::size_t>(note-model.order.begin());std::optional<std::size_t> previous;
        for(std::size_t k=0;k<at;++k)if(model.order[k].kind==EventKind::Message)previous=k;
        std::optional<std::size_t> next;for(std::size_t k=at+1;k<model.order.size();++k)if(model.order[k].kind==EventKind::Message){next=k;break;}
        official_role38_require(previous.has_value()||next.has_value(),"Config49 Note has adjacent business chronology witness");const auto destination=previous?*previous:*next;
        attempt("note_chronology",[&](Model& wrong){
            const auto event=wrong.order[at];wrong.order.erase(wrong.order.begin()+static_cast<std::ptrdiff_t>(at));wrong.order.insert(wrong.order.begin()+static_cast<std::ptrdiff_t>(destination),event);
            int before=-1;for(std::size_t k=0;k<destination;++k)if(wrong.order[k].kind==EventKind::Message)before=wrong.order[k].index;
            wrong.notes[n].after=before;
        });
    }
    // Source labels/numbers differ, so swapping complete first/last Messages
    // preserves schema while making their typed event order observably wrong.
    if(model.messages.size()>1)attempt("message_chronology",[](Model& wrong){std::swap(wrong.messages.front(),wrong.messages.back());});
    for(const auto key:{"number_visibility","number_value","central_source_toggle","central_target_toggle"})
        official_role38_require(out.executed[key]==static_cast<int>(model.messages.size()),"Config49 mandatory message mutation lower bound");
    official_role38_require(out.executed["half_owner_shape_fill"]==half_count*3,"Config49 mandatory half ownership mutation lower bound");
    official_role38_require(out.executed["note_side"]==static_cast<int>(model.notes.size())&&out.executed["note_owner_complete"]==static_cast<int>(model.notes.size())&&out.executed["note_chronology"]==static_cast<int>(model.notes.size()),"Config49 mandatory schema-valid Note mutation lower bound");
    if(model.actors.size()>1)official_role38_require(out.executed["sender_endpoint"]==static_cast<int>(model.messages.size())&&out.executed["self_nonself"]==static_cast<int>(model.messages.size()),"Config49 mandatory endpoint mutation lower bound");
    if(model.messages.size()>1)official_role38_require(out.executed["message_chronology"]==1,"Config49 mandatory complete chronology mutation");
    return out;
}
