Wrap43Mutations wrap43_mutations(const Grid& good,const Wrap43Scene& source) {
    Wrap43Mutations out;
    auto attempt=[&](std::string_view kind,auto change){
        Work work;const auto copied=wrap43_copy_charge(source.source,work);if(copied>work.remaining/4)throw std::runtime_error("Wrap43 mutation copy work exhausted");work.spend(copied*4+source.actors.size()+source.messages.size()+source.notes.size()+source.boxes.size()+64);auto wrong=source;change(wrong);
        try{check_event_model(wrong.source,work);}catch(const std::runtime_error& error){if(termaid47_resource(error.what()))throw;++out.schema_skips[std::string(kind)];return;}
        std::optional<Wrap43Plan> plan;try{plan=wrap43_plan(wrong,work);}catch(const Wrap43ProfileUnmet&){++out.profile_skips[std::string(kind)];return;}
        std::vector<std::pair<int,int>> owners;const auto hints=wrap43_constraints(*plan,owners,work);const auto errors=validate(good,plan->display,work.remaining,&hints);wrap43_no_protocol_or_resource(errors);++out.executed[std::string(kind)];if(errors.empty())out.errors.emplace_back("Accepted Wrap43 observable source mutation: "+std::string(kind));
    };
    for(std::size_t n=0;n<source.source.actors.size();++n){attempt("actor_alias",[&](Wrap43Scene& wrong){wrong.source.actors[n].label=wrong.source.actors[n].label=="Other"?"Else":"Other";});attempt("actor_role",[&](Wrap43Scene& wrong){wrong.source.actors[n].role=wrong.source.actors[n].role==Role::Database?Role::Control:Role::Database;});}
    for(std::size_t n=0;n<source.source.messages.size();++n){
        attempt("message_label",[&](Wrap43Scene& wrong){wrong.source.messages[n].label=wrong.source.messages[n].label=="Other"?"Else":"Other";});
        attempt("message_arrow",[&](Wrap43Scene& wrong){wrong.source.messages[n].arrow=wrong.source.messages[n].arrow==Arrow::Filled?Arrow::Cross:Arrow::Filled;});
        attempt("message_stroke",[&](Wrap43Scene& wrong){wrong.source.messages[n].dashed=!wrong.source.messages[n].dashed;});
        attempt("number",[&](Wrap43Scene& wrong){wrong.source.messages[n].number=wrong.source.messages[n].number=="999"?"998":"999";});
        if(source.source.actors.size()>1)attempt("endpoint",[&](Wrap43Scene& wrong){wrong.source.messages[n].to=(wrong.source.messages[n].to+1)%static_cast<int>(wrong.source.actors.size());});
        // Cardinalities and complete schedule change together. Native lifetime
        // attachment failures are schema skips, never geometry evidence.
        attempt("message_erasure",[&](Wrap43Scene& wrong){
            wrong.source.messages.erase(wrong.source.messages.begin()+static_cast<std::ptrdiff_t>(n));wrong.messages.erase(wrong.messages.begin()+static_cast<std::ptrdiff_t>(n));
            std::erase_if(wrong.source.order,[&](const OrderedEvent& e){return e.kind==EventKind::Message&&e.index==static_cast<int>(n);});
            for(auto& event:wrong.source.order)if(event.kind==EventKind::Message&&event.index>static_cast<int>(n))--event.index;
            for(auto& note:wrong.source.notes)if(note.after>=static_cast<int>(n))--note.after;
        });
    }
    for(std::size_t n=0;n<source.source.notes.size();++n){attempt("note_text",[&](Wrap43Scene& wrong){wrong.source.notes[n].text=wrong.source.notes[n].text=="Other"?"Else":"Other";});attempt("note_side",[&](Wrap43Scene& wrong){auto& note=wrong.source.notes[n];note.position=note.position=="right"?"left":"right";note.actors={note.actors.front()};});}
    for(std::size_t n=0;n<source.source.fragments.size();++n){attempt("fragment_label",[&](Wrap43Scene& wrong){wrong.source.fragments[n].label=wrong.source.fragments[n].label=="Other"?"Else":"Other";});for(std::size_t k=0;k<source.source.fragments[n].dividers.size();++k)attempt("fragment_divider",[&](Wrap43Scene& wrong){auto& value=wrong.source.fragments[n].dividers[k];value=value=="Other"?"Else":"Other";});}
    for(std::size_t n=0;n<source.source.boxes.size();++n)attempt("group_title",[&](Wrap43Scene& wrong){wrong.source.boxes[n].title=wrong.source.boxes[n].title=="Other"?"Else":"Other";});
    Work work;work.spend(good.cells.size()*4+64);auto ink=good;bool placed=false;for(int y=0;y<good.height&&!placed;++y)for(int x=0;x<good.width;++x){work.spend();if(good.at(x,y)==" "){ink.put(x,y,"*");placed=true;break;}}
    wrap43_require(placed,"Wrap43 orphan mutation requires a real blank cell");const auto plan=wrap43_plan(source,work);std::vector<std::pair<int,int>> owners;const auto hints=wrap43_constraints(plan,owners,work);const auto errors=validate(ink,plan.display,work.remaining,&hints);wrap43_no_protocol_or_resource(errors);++out.executed["orphan_ink"];if(errors.empty())out.errors.emplace_back("Accepted Wrap43 unowned ink");
    wrap43_require(out.executed["actor_alias"]==static_cast<int>(source.source.actors.size())&&out.executed["message_label"]==static_cast<int>(source.source.messages.size())&&out.executed["message_arrow"]==static_cast<int>(source.source.messages.size())&&out.executed["message_stroke"]==static_cast<int>(source.source.messages.size())&&out.executed["note_text"]==static_cast<int>(source.source.notes.size())&&out.executed["fragment_label"]==static_cast<int>(source.source.fragments.size())&&out.executed["group_title"]==static_cast<int>(source.source.boxes.size()),"Wrap43 mandatory schema-valid geometry adversaries completed");
    return out;
}
