    const int required=tiny?3:77;EXPECT_EQ(visited,required);EXPECT_EQ(observed,required);EXPECT_EQ(decoded,required);EXPECT_EQ(ready,required);EXPECT_EQ(matches,required);EXPECT_EQ(mutated,required);EXPECT_EQ(fallback,0);EXPECT_EQ(pending,0);EXPECT_EQ(errors,0);EXPECT_EQ(observations,0);
