namespace {
// Literal full scenes, authored from endpoint/lifetime/Note ownership. The
// message cross at (26,10), death at (26,12), and text cross at (26,16)
// in the over scene have three different owners.
Model dead_note_hand_model(int placement) {
    Model model{{{"A","A"},{"B","B"}},
        {{0,1,"hi",false},{0,1,"bye",false,Arrow::Cross}},
        {{{1},"la×te",placement==1?"left":placement==2?"right":"over",1}}};
    if(placement==3) model.notes[0].actors={0,1};
    model.order={{EventKind::Message,0},{EventKind::Message,1},
        {EventKind::Destroy,1},{EventKind::Note,0}};
    return model;
}
Grid dead_note_hand_grid(int placement) {
    Grid grid{52,26,std::vector<std::string>(1352," ")};
    grid.text(5,0,"┌─────┐");grid.text(5,1,"│  A  │");grid.text(5,2,"└─────┘");
    grid.text(23,0,"┌─────┐");grid.text(23,1,"│  B  │");grid.text(23,2,"└─────┘");
    for(int y=3;y<=21;++y)grid.put(8,y,"│");
    for(int y=3;y<=11;++y)grid.put(26,y,"│");
    grid.text(10,5,"hi");grid.text(10,9,"bye");
    for(const int y:{6,10}) {
        grid.put(8,y,"├");for(int x=9;x<26;++x)grid.put(x,y,"─");
    }
    grid.put(26,6,"▶");grid.put(26,10,"×");grid.put(26,12,"×");
    const int left=placement==1?12:placement==2?30:placement==3?4:21;
    const int right=placement==1?22:placement==2?40:placement==3?30:31;
    for(int x=left+1;x<right;++x) {grid.put(x,15,"─");grid.put(x,17,"─");}
    grid.put(left,15,"┌");grid.put(right,15,"┐");
    grid.put(left,17,"└");grid.put(right,17,"┘");
    for(int x=left;x<=right;++x)grid.put(x,16," ");
    grid.put(left,16,"│");grid.put(right,16,"│");
    grid.text(left+1+(right-left-1-5)/2,16,"la×te");
    if(placement==1) {
        grid.put(right,16,"├");for(int x=right+1;x<=26;++x)grid.put(x,16,"─");
    }else if(placement==2) {
        grid.put(left,16,"┤");for(int x=26;x<left;++x)grid.put(x,16,"─");
    }else if(placement==3) {
        // The live A owner retains both real rail junctions. Dead B has none.
        grid.put(8,15,"┴");grid.put(8,17,"┬");
    }
    grid.text(0,24,kSentinel);return grid;
}
void dead_note_require_schema(const Model& model) {Work work;check_event_model(model,work);}
void dead_note_expect_semantic_rejection(const Grid& grid,const Model& model) {
    ASSERT_NO_THROW(dead_note_require_schema(model));
    const auto errors=validate(grid,model);first19_no_resource_rejection(errors);
    EXPECT_FALSE(errors.empty());
}
}
TEST(MermaidLifecycleOracle, DestroyedNoteOwnerKeepsItsColumnWithoutInventingVerticalInk) {
    for(const int placement:{0,1,2,3}) {
        SCOPED_TRACE(placement);const auto model=dead_note_hand_model(placement);
        const auto good=dead_note_hand_grid(placement);
        ASSERT_NO_THROW(dead_note_require_schema(model));
        const auto errors=validate(good,model);first19_no_resource_rejection(errors);
        ASSERT_TRUE(errors.empty())<<(errors.empty()?"":errors.front());
        auto bad=good;bad.put(26,13,"│");dead_note_expect_semantic_rejection(bad,model);
        bad=good;bad.put(26,18,"│");dead_note_expect_semantic_rejection(bad,model);
        // Neither the message cross nor an owned Note-text cross can become death.
        bad=good;bad.put(26,12," ");dead_note_expect_semantic_rejection(bad,model);
        bad=good;bad.put(26,12,"│");dead_note_expect_semantic_rejection(bad,model);
        bad=good;bad.put(8,12,"×");dead_note_expect_semantic_rejection(bad,model);
        bad=good;bad.put(26,6," ");dead_note_expect_semantic_rejection(bad,model);
        bad=good;bad.put(26,10,"▶");dead_note_expect_semantic_rejection(bad,model);
        if(placement==0||placement==3) {
            bad=good;bad.put(26,15,"┴");dead_note_expect_semantic_rejection(bad,model);
            bad=good;bad.put(26,17,"┬");dead_note_expect_semantic_rejection(bad,model);
        }else {
            bad=good;bad.put(26,16,placement==1?"┤":"├");
            dead_note_expect_semantic_rejection(bad,model);
            bad=good;bad.put(24+(placement==2?4:0),16," ");
            dead_note_expect_semantic_rejection(bad,model);
        }
        if(placement==3) {
            bad=good;bad.put(8,15,"─");dead_note_expect_semantic_rejection(bad,model);
        }
        const int note_left=placement==1?12:placement==2?30:placement==3?4:21;
        bad=good;bad.put(note_left,15," ");dead_note_expect_semantic_rejection(bad,model);
        auto wrong=model;wrong.notes[0].text="late";dead_note_expect_semantic_rejection(good,wrong);
        wrong=model;wrong.notes[0].actors=placement==3?std::vector<int>{1}:std::vector<int>{0};dead_note_expect_semantic_rejection(good,wrong);
        wrong=model;wrong.notes[0].after=0;
        wrong.order={{EventKind::Message,0},{EventKind::Note,0},
            {EventKind::Message,1},{EventKind::Destroy,1}};
        dead_note_expect_semantic_rejection(good,wrong);
        wrong=model;wrong.order[2].index=0;dead_note_expect_semantic_rejection(good,wrong);
    }
    // This deliberate false Model is a schema control, never a geometry mutant.
    Model unborn{{{"A","A"},{"B","B"}},{{0,0,"before",false},{0,1,"born",false}},{{{1},"early","over",0}}};
    unborn.order={{EventKind::Message,0},{EventKind::Note,0},{EventKind::Create,1},{EventKind::Message,1}};
    EXPECT_THROW(dead_note_require_schema(unborn),std::runtime_error);
    const auto good=dead_note_hand_grid(0);const auto model=dead_note_hand_model(0);
    EXPECT_THROW(first19_no_resource_rejection(validate(good,model,0)),std::runtime_error);
}

namespace {
// Same public node is captured at all widths before the complete good Model is
// checked. This helper owns one scene budget; resources never count as rejection.
bool dead_note_public(std::string_view source,const Model& expected) {
    if(source.empty()||source.size()>65536)throw std::runtime_error("Dead Note public source domain");
    Work work;work.spend(source.size()*8+128);check_event_model(expected,work);
    const auto node=loom::ui::render_markdown(fenced(source,"mermaid"));
    const auto plain=loom::ui::render_markdown(fenced(source,"text"));
    node->ComputeRequirement();plain->ComputeRequirement();
    const int height=std::min(1040,std::max(40,std::max(node->requirement().min_y,plain->requirement().min_y)+12));
    work.spend(static_cast<std::size_t>(height)*(3*240+2*40)*8+256);
    const auto wide=capture(node,240,height),ordinary=capture(plain,240,height);
    const auto narrow=capture(node,40,height),small=capture(plain,40,height),restored=capture(node,240,height);
    bool good=wide==restored;EXPECT_TRUE(good);const bool fallback=wide==ordinary;EXPECT_FALSE(fallback);
    for(const auto* frame:{&wide,&narrow,&restored}) {const bool full=complete_sequence_sentinel(*frame);EXPECT_TRUE(full);good&=full;}
    const auto allowance=work.remaining;
    if(!fallback) {const auto errors=validate(wide,expected,allowance);first19_no_resource_rejection(errors);for(const auto& error:errors)ADD_FAILURE()<<error;good&=errors.empty();}
    if(narrow!=small) {const auto errors=validate(narrow,expected,allowance);first19_no_resource_rejection(errors);for(const auto& error:errors)ADD_FAILURE()<<error;good&=errors.empty();}
    if(fallback||!good)return false;
    auto reject=[&](const auto& change) {
        const auto copied=wrap43_copy_charge(expected,work);work.spend(copied*4+128);
        auto wrong=expected;change(wrong);check_event_model(wrong,work);
        const auto errors=validate(wide,wrong,work.remaining);first19_no_resource_rejection(errors);
        EXPECT_FALSE(errors.empty());good&=!errors.empty();
    };
    reject([](Model& model){model.notes[0].text+="?";});
    reject([](Model& model){model.notes[0].actors={0};});
    reject([](Model& model){model.notes[0].after=0;model.order={{EventKind::Message,0},
        {EventKind::Note,0},{EventKind::Message,1},{EventKind::Destroy,1}};});
    reject([](Model& model){model.order[2].index=0;});
    reject([](Model& model){model.order.erase(model.order.begin()+2);});
    reject([](Model& model){model.messages[1].arrow=model.messages[1].arrow==Arrow::Filled?Arrow::Cross:Arrow::Filled;});
    reject([](Model& model){model.messages[0].number="1";});
    return good;
}
}
