constexpr std::string_view kConfig116Legacy6FactsPath = "mermaid_native/sequence_official_config116_legacy6_facts.json";
constexpr std::string_view kConfig116Legacy6FactsSha = "9ca671329fdc3abc3c43177cf12315417c3277936f76cf53731fa8f0955308a7";

void config116_legacy6_binding(JsonVal item, JsonVal manifest, Work& work) {
    const auto input = item.get("input"), body = item.get("body"), path = item.get("path");
    official_role38_require(input.is_str() && body.is_str() && path.is_str() &&
        input.as_str().size() <= 65536 && body.as_str().size() <= 65536,
        "Config116 legacy6 complete source types/caps");
    work.spend(input.as_str().size() * 8 + body.as_str().size() * 4 + path.as_str().size() * 4 + 128);
    official_role38_require(loom::utils::crypto::sha256(input.as_str()) == item.get_string("input_sha256") &&
        loom::utils::crypto::sha256(body.as_str()) == item.get_string("body_sha256"),
        "Config116 legacy6 whole raw/body digests");
    official_role38_require(item.get("body_offset_utf8_bytes").is_int() &&
        item.get_int("body_offset_utf8_bytes") >= 0, "Config116 legacy6 exact suffix offset type");
    const auto offset = static_cast<std::uint64_t>(item.get_int("body_offset_utf8_bytes"));
    official_role38_require(offset <= input.as_str().size() && input.as_str().substr(offset) == body.as_str(),
        "Config116 legacy6 complete suffix retains every business statement");
    description77_physical(item.get("raw_physical_lines"), input.as_str(), work);
    official_role38_require(path.as_str().starts_with("sequence/") &&
        path.as_str().find("..") == std::string_view::npos, "Config116 legacy6 original namespace");
    work.spend(input.as_str().size() * 3 + 64);
    official_role38_require(fixture_bytes("mermaid_official/cases/" + std::string(path.as_str())) == input.as_str(),
        "Config116 legacy6 original full physical file");
    int found = 0;
    manifest.get("fixtures").iter([&](JsonVal record) {
        work.spend();
        if (record.get_string("path") != path.as_str()) return;
        ++found;
        official_role38_require(joined683_canonical(record, work) ==
            joined683_canonical(item.get("original_manifest_record"), work),
            "Config116 legacy6 original manifest dictionary");
        official_role38_require(record.get_string("sha256") == item.get_string("input_sha256") &&
            record.get("diagnostic").get("offset").is_int() &&
            record.get("diagnostic").get_int("offset") == static_cast<std::int64_t>(offset) &&
            record.get("diagnostic").get_string("sha256") == item.get_string("body_sha256"),
            "Config116 legacy6 raw and diagnostic tuple");
    });
    official_role38_require(found == 1, "Config116 legacy6 original path binds once");
    const auto entries = item.get("frontmatter_node_tree").get("entries");
    official_role38_require(entries.is_arr() && entries.size() == 2 &&
        entries.at(0).get("key").get_string("value") == "description" &&
        entries.at(1).get("key").get_string("value") == "config" &&
        item.get("config_complete_leaf_inventory").is_arr(),
        "Config116 legacy6 complete description/config provenance");
    const auto authority = item.get("body_authority");
    const auto file = authority.get("fixture_path");
    official_role38_require(file.is_str() && authority.get("case_index").is_int() &&
        authority.get_int("case_index") >= 0, "Config116 legacy6 complete body authority types");
    work.spend(file.as_str().size() * 4 + 64);
    official_role38_require(file.as_str() == "mermaid_native/sequence_official_side_notes_facts.json" ||
        file.as_str() == "mermaid_native/sequence_official_fragments_facts.json" ||
        file.as_str() == "mermaid_native/sequence_official_activation_facts.json",
        "Config116 legacy6 fixed test authority namespace");
    const auto bytes = joined683_fixture(file.as_str(), authority.get("file").get_string("sha256"), work);
    const auto document = json::parse(bytes);
    official_role38_require(document.has_value() && document->root().get("cases").is_arr() &&
        static_cast<std::uint64_t>(authority.get_int("case_index")) < document->root().get("cases").size(),
        "Config116 legacy6 entire authority file/row");
    const auto original = document->root().get("cases").at(static_cast<std::size_t>(authority.get_int("case_index")));
    official_role38_require(original.get_string("path") == path.as_str() &&
        original.get_string("raw_sha256") == item.get_string("input_sha256") &&
        original.get_string("body_sha256") == item.get_string("body_sha256") &&
        original.get("body_offset_utf8_bytes").is_int() &&
        original.get_int("body_offset_utf8_bytes") == static_cast<std::int64_t>(offset),
        "Config116 legacy6 existing complete body source tuple");
    official_role38_require(joined683_canonical(original.get("model"), work) ==
        joined683_canonical(authority.get("model_verbatim"), work) &&
        loom::utils::crypto::sha256(joined683_canonical(original.get("model"), work)) ==
            authority.get_string("model_sha256"), "Config116 legacy6 body Model remains verbatim");
}

void config116_legacy6_label_binding(JsonVal item, const Wrap43Scene& scene, Work& work) {
    const auto leaves = item.get("config_complete_leaf_inventory");
    official_role38_require(leaves.is_arr() && leaves.size() == 1 &&
        leaves.at(0).get_string("path") == "sequence.wrap" &&
        leaves.at(0).get_string("yaml_tag") == "tag:yaml.org,2002:bool" &&
        leaves.at(0).get_string("value") == "true", "Config116 inherited source wrap boolean");
    for (const auto* flags : {&scene.actors, &scene.messages, &scene.notes, &scene.boxes})
        for (const bool flag : *flags) { work.spend(); official_role38_require(flag, "Config116 complete inherited Label flags"); }
    const auto spans = item.get("source_label_witnesses"), raw = item.get("input");
    const auto total = scene.source.messages.size() + scene.source.notes.size();
    official_role38_require(spans.is_arr() && spans.size() == total && total <= 256,
        "Config116 every authored signal and Note Label has one source witness");
    work.spend(total * 128 + 64);
    std::vector<bool> messages(scene.source.messages.size()), notes(scene.source.notes.size());
    spans.iter([&](JsonVal span) {
        official_role38_require(span.get("index").is_int() && span.get_int("index") >= 0 &&
            span.get("raw_offset_utf8_bytes").is_int() && span.get_int("raw_offset_utf8_bytes") >= 0 &&
            span.get("whole_line").is_str() && span.get("authored_label").is_str() &&
            span.get("effective_wrap").is_bool() && span.get("effective_wrap").as_bool(),
            "Config116 complete authored Label witness types");
        const auto text = span.get("whole_line").as_str();
        work.spend(text.size() * 4 + span.get("authored_label").as_str().size() * 2 + 64);
        const auto offset = static_cast<std::uint64_t>(span.get_int("raw_offset_utf8_bytes"));
        official_role38_require(offset <= raw.as_str().size() && text.size() <= raw.as_str().size() - offset &&
            raw.as_str().substr(offset, text.size()) == text &&
            loom::utils::crypto::sha256(text) == span.get_string("whole_line_sha256"),
            "Config116 authored Label whole physical source line");
        const auto index = static_cast<std::uint64_t>(span.get_int("index"));
        if (span.get_string("field") == "message") {
            official_role38_require(index < messages.size() && !messages[index] &&
                scene.source.messages[index].label == span.get("authored_label").as_str(),
                "Config116 unique raw message Label");
            messages[index] = true;
        } else {
            official_role38_require(span.get_string("field") == "note" && index < notes.size() && !notes[index] &&
                scene.source.notes[index].text == span.get("authored_label").as_str(),
                "Config116 unique raw Note Label");
            notes[index] = true;
        }
    });
}

// A selected complete source executes a strong assertion. true means selected,
// never that fallback or a failed assertion has become successful geometry.
bool config116_legacy_raw(std::string_view source) {
    Work work;
    work.spend(source.size() + 32);
    if (!source.starts_with("---\n")) return false;
    const auto bytes = joined683_fixture(kConfig116Legacy6FactsPath, kConfig116Legacy6FactsSha, work);
    const auto facts = json::parse(bytes);
    official_role38_require(facts.has_value() && facts->root().get("schema").is_int() &&
        facts->root().get_int("schema") == 1 &&
        facts->root().get_string("kind") == "official_config116_legacy6_native_source_execution/proposed-v1" &&
        facts->root().get("cases").is_arr() && facts->root().get("cases").size() == 6,
        "Config116 legacy6 closed source asset");
    std::optional<JsonVal> selected;
    facts->root().get("cases").iter([&](JsonVal item) {
        const auto input = item.get("input");
        official_role38_require(input.is_str(), "Config116 legacy6 source type");
        work.spend(input.as_str().size() + source.size() + 32);
        if (input.as_str() != source) return;
        official_role38_require(!selected, "Config116 legacy6 whole source selected once");
        selected = item;
    });
    if (!selected) return false;
    const auto item = *selected;
    SCOPED_TRACE(item.get_string("path"));
    bool observed = false, decoded = false, good = false, mutated = false, fallback = true;
    std::string phase = "complete_source_capture";
    std::vector<std::string> errors;
    json::JsonMutDoc report;
    auto row = report.object();
    row.set("path", item.get_string("path"));
    row.set("input_sha256", item.get_string("input_sha256"));
    row.set("model_sha256", item.get_string("model_sha256"));
    row.set("facts_sha256", std::string(kConfig116Legacy6FactsSha));
    try {
        work.spend(source.size() * 6 + 128);
        const auto input = std::string(source);
        const auto node = loom::ui::render_markdown(fenced(input, "mermaid"));
        const auto plain_node = loom::ui::render_markdown(fenced(input, "text"));
        node->ComputeRequirement(); plain_node->ComputeRequirement();
        const int height = std::min(1040, std::max(40,
            std::max(node->requirement().min_y, plain_node->requirement().min_y) + 12));
        work.spend(static_cast<std::size_t>(height) * (3 * 240 + 2 * 40 + 2 * 240 + 40) * 8 + 256);
        const auto wide = capture(node, 240, height), plain = capture(plain_node, 240, height);
        const auto narrow = capture(node, 40, height), small = capture(plain_node, 40, height);
        const auto restored = capture(node, 240, height);
        observed = true; fallback = wide == plain;
        row.set("wide_source_fallback", fallback); row.set("narrow_source_fallback", narrow == small);
        row.set("restored_identically", wide == restored);
        if (wide != restored) errors.emplace_back("Config116 legacy6 same-Node restoration differs");
        for (const auto* frame : {&wide, &narrow, &restored})
            if (!complete_sequence_sentinel(*frame)) errors.emplace_back("Config116 legacy6 physical sentinel differs");
        for (const auto& [name, frame] : std::array<std::pair<std::string_view, const Grid*>, 3>{{
            {"wide_frame", &wide}, {"narrow_frame", &narrow}, {"restored_frame", &restored}}}) {
            auto lines = row.make_arr();
            for (int y = 0; y < frame->height; ++y) lines.append(row.make_str(frame->row(y)));
            row.add(name, lines);
        }
        row.set("frame_width", wide.width); row.set("frame_height", wide.height);
        row.set("wide_frame_sha256", lifecycle_frame_hash(wide));
        row.set("narrow_frame_sha256", lifecycle_frame_hash(narrow));
        row.set("restored_frame_sha256", lifecycle_frame_hash(restored));
        phase = "complete_original_and_Model_binding";
        // Original manifest setup is an independently bounded immutable load;
        // the source assertion never resets its own capture/decode remainder.
        Work setup;
        const auto manifest_bytes = joined683_fixture("mermaid_official/manifest.json", kOfficialRole38ManifestSha, setup);
        const auto manifest = json::parse(manifest_bytes);
        official_role38_require(manifest.has_value(), "Config116 legacy6 original manifest parse");
        config116_legacy6_binding(item, manifest->root(), work);
        phase = "complete_scene_geometry";
        if (item.get_string("profile") == "fixed") {
            const auto model = description77_fixed_model(item, work);
            decoded = true;
            const auto allowance = work.remaining;
            if (!fallback) {
                const auto found = validate(wide, model, allowance);
                first19_no_resource_rejection(found); errors.insert(errors.end(), found.begin(), found.end());
            }
            if (narrow != small) {
                const auto found = validate(narrow, model, allowance);
                first19_no_resource_rejection(found); errors.insert(errors.end(), found.begin(), found.end());
            }
            good = !fallback && errors.empty();
            if (good) {
                phase = "schema_valid_mutations";
                const auto encoded = joined683_canonical(item.get("model"), work);
                const auto changes = description77_fixed_mutations(wide, model,
                    encoded.size() * 8 + model.order.size() * 32 + 256);
                work.spend((changes.executed.size() + changes.skipped_schema.size()) * 256 + 64);
                errors.insert(errors.end(), changes.errors.begin(), changes.errors.end());
                mutated = changes.errors.empty();
                auto counts = row.make_obj(), skips = row.make_obj();
                for (const auto& [key, count] : changes.executed) counts.set(key, count);
                for (const auto& [key, count] : changes.skipped_schema) skips.set(key, count);
                row.add("geometry_mutations_executed", counts); row.add("schema_invalid_not_geometry", skips);
            }
        } else {
            official_role38_require(item.get_string("profile") == "source_wrap" &&
                item.get_string("number_encoding") == "DisplayText", "Config116 legacy6 explicit Label profile");
            const auto encoded = joined683_canonical(item.get("model"), work);
            official_role38_require(loom::utils::crypto::sha256(encoded) == item.get_string("model_sha256"),
                "Config116 legacy6 complete Label Model digest");
            const auto scene = wrap43_codec(item.get("model"), work);
            decoded = true;
            config116_legacy6_label_binding(item, scene, work);
            const auto plan = wrap43_plan(scene, work);
            std::vector<std::pair<int, int>> owners;
            const auto hints = wrap43_constraints(plan, owners, work);
            const auto allowance = work.remaining;
            if (!fallback) {
                const auto found = validate(wide, plan.display, allowance, &hints);
                wrap43_no_protocol_or_resource(found); errors.insert(errors.end(), found.begin(), found.end());
            }
            if (narrow != small) {
                const auto found = validate(narrow, plan.display, allowance, &hints);
                wrap43_no_protocol_or_resource(found); errors.insert(errors.end(), found.begin(), found.end());
            }
            good = !fallback && errors.empty();
            if (good) {
                phase = "schema_valid_Label_mutations";
                auto changes = wrap43_mutations(wide, scene);
                Work title_work;
                const auto copy = wrap43_copy_charge(plan.display, title_work);
                if (copy > title_work.remaining / 4) throw std::runtime_error("Config116 Label title copy work exhausted");
                title_work.spend(copy * 4 + 64);
                auto wrong_title = plan.display;
                wrong_title.title = "Wrong";
                check_event_model(wrong_title, title_work);
                const auto title_errors = validate(wide, wrong_title, title_work.remaining, &hints);
                wrap43_no_protocol_or_resource(title_errors);
                ++changes.executed["visible_title"];
                if (title_errors.empty()) changes.errors.emplace_back("Accepted Config116 Label visible title mutation");
                work.spend((changes.executed.size() + changes.schema_skips.size() +
                    changes.profile_skips.size()) * 256 + 64);
                errors.insert(errors.end(), changes.errors.begin(), changes.errors.end());
                mutated = changes.errors.empty();
                auto counts = row.make_obj(), skips = row.make_obj(), profiles = row.make_obj();
                for (const auto& [key, count] : changes.executed) counts.set(key, count);
                for (const auto& [key, count] : changes.schema_skips) skips.set(key, count);
                for (const auto& [key, count] : changes.profile_skips) profiles.set(key, count);
                row.add("geometry_mutations_executed", counts); row.add("schema_invalid_not_geometry", skips);
                row.add("profile_pending_not_geometry", profiles);
            }
        }
    } catch (const std::exception& error) {
        errors.emplace_back(phase + ": " + error.what());
    }
    const bool matched = observed && decoded && good && mutated && errors.empty();
    row.set("observed", observed); row.set("Model_decoded", decoded);
    row.set("good_before_mutations", good); row.set("mutations_completed", mutated); row.set("matched", matched);
    row.set("phase", phase); row.set("original_foreign_predicates_certified", 0);
    auto failures = row.make_arr();
    for (const auto& error : errors) { failures.append(row.make_str(error)); ADD_FAILURE() << error; }
    row.add("errors", failures); report.set_root(row);
#ifdef LOOM_MERMAID_REPORT_DIR
    std::filesystem::create_directories(LOOM_MERMAID_REPORT_DIR);
    const auto name = "mermaid-config116-legacy6-" + item.get_string("input_sha256") + ".json";
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR) / name, std::ios::binary);
    EXPECT_TRUE(output && (output << report.to_pretty_string() << '\n'));
#endif
    EXPECT_TRUE(observed); EXPECT_TRUE(decoded); EXPECT_FALSE(fallback);
    EXPECT_TRUE(good); EXPECT_TRUE(mutated); EXPECT_TRUE(matched);
    return true;
}
