// Fixed coordinates are authored independently of the producer. These are
// native projection witnesses, not copies of upstream ASCII/SVG output.
Grid par_over_literal_wide_hand(bool nested) {
    const int height=nested?30:28,last=nested?26:24,footer=nested?24:22;
    Grid grid{80,height,std::vector<std::string>(static_cast<std::size_t>(80*height)," ")};
    for(const int center:{8,32,60}) {
        grid.text(center-3,0,"┌─────┐");grid.text(center-3,2,"└─────┘");
        for(int y=3;y<=last;++y)grid.put(center,y,"│");
    }
    grid.text(5,1,"│  A  │");grid.text(29,1,"│  B  │");grid.text(57,1,"│  C  │");
    auto frame=[&](int left,int top,int right,int bottom,int text_x,std::string_view caption) {
        for(int y=top+1;y<bottom;++y){grid.put(left,y,"│");grid.put(right,y,"│");}
        for(const int y:{top,top+2,bottom})for(int x=left+1;x<right;++x)
            grid.put(x,y,x==8||x==32||x==60?"┼":"─");
        grid.put(left,top,"┌");grid.put(right,top,"┐");
        grid.put(left,top+2,"├");grid.put(right,top+2,"┤");
        grid.put(left,bottom,"└");grid.put(right,bottom,"┘");
        for(int x=left+1;x<right;++x)grid.put(x,top+1," ");
        grid.text(text_x,top+1,caption);
    };
    frame(0,5,76,footer,30,"par_over Everyone");
    if(nested)frame(2,9,74,20,26,"rect rgba(0,0,0,0.1)");
    const int label=nested?12:10,top=nested?16:14;
    grid.text(10,label,"Work");grid.put(8,label+1,"├");grid.put(32,label+1,"▶");
    for(int x=9;x<32;++x)grid.put(x,label+1,"─");
    grid.text(37,top,"┌─────────────────┐");
    grid.text(37,top+1,"┤    wide note    │");
    grid.text(37,top+2,"└─────────────────┘");
    grid.put(32,top+1,"├");for(int x=33;x<37;++x)grid.put(x,top+1,"─");
    grid.text(0,height-2,kSentinel);return grid;
}
Model par_over_literal_wide_model(bool nested) {
    Model model{{{"A","A"},{"B","B"},{"C","C"}},{{0,1,"Work",false}},{{{1},"wide note","right",0}}};
    model.fragments={{"par_over","Everyone",-1,{}}};
    model.order={{EventKind::Open,0}};
    if(nested){model.fragments.push_back({"rect","rgba(0,0,0,0.1)",0,{}});model.order.push_back({EventKind::Open,1});}
    model.order.push_back({EventKind::Message,0});model.order.push_back({EventKind::Note,0});
    if(nested)model.order.push_back({EventKind::Close,1});
    model.order.push_back({EventKind::Close,0});return model;
}
Grid par_over_literal_lifetime_hand() {
    Grid grid{80,34,std::vector<std::string>(2720," ")};
    grid.text(5,0,"┌─────┐");grid.text(5,1,"│  A  │");grid.text(5,2,"└─────┘");
    grid.text(33,0,"┌─────┐");grid.text(33,1,"│  B  │");grid.text(33,2,"└─────┘");
    for(int y=3;y<=30;++y)grid.put(8,y,"│");
    for(int y=10;y<=19;++y)grid.put(36,y,"│");
    for(int y=6;y<28;++y){grid.put(0,y,"│");grid.put(76,y,"│");}
    for(const int y:{5,7,28})for(int x=1;x<76;++x)grid.put(x,y,x==8?"┼":"─");
    grid.put(0,5,"┌");grid.put(76,5,"┐");grid.put(0,7,"├");grid.put(76,7,"┤");
    grid.put(0,28,"└");grid.put(76,28,"┘");
    for(int x=1;x<76;++x)grid.put(x,6," ");grid.text(32,6,"par_over Both");
    grid.text(10,11,"born");grid.put(8,12,"├");grid.put(36,12,"▶");
    for(int x=9;x<36;++x)grid.put(x,12,"─");
    grid.text(10,17,"bye");grid.put(8,18,"◀");grid.put(36,18,"┤");
    for(int x=9;x<36;++x)grid.put(x,18,"┄");grid.put(36,20,"×");
    grid.text(3,23,"┌─────────────────┐");grid.text(3,24,"│      kept       │");grid.text(3,25,"└─────────────────┘");
    grid.put(8,23,"┴");grid.put(8,25,"┬");grid.text(0,32,kSentinel);return grid;
}
Model par_over_literal_lifetime_model() {
    Model model{{{"A","A"},{"B","B"}},{{0,1,"born",false},{1,0,"bye",true}},{{{0},"kept","over",1}}};
    model.fragments={{"par_over","Both",-1,{}}};
    model.order={{EventKind::Open,0},{EventKind::Create,1},{EventKind::Message,0},
        {EventKind::Message,1},{EventKind::Destroy,1},{EventKind::Note,0},{EventKind::Close,0}};return model;
}

