TEST(MermaidParOverOracle, CompleteWideBackgroundKeepsUnusedActorAndEveryOwnedNote) {
    for(const bool nested:{false,true}) {
        SCOPED_TRACE(nested);
        const auto good=par_over_literal_wide_hand(nested);
        const auto model=par_over_literal_wide_model(nested);
        ASSERT_TRUE(remaining24_good(good,model));
        // Existing wrappers pay the copy before mutation, then share one Work
        // remainder across schema and geometry. Resource errors cannot reject.
        remaining24_pixel_bad(good,model,[](Grid& bad){bad.put(76,12," ");});
        remaining24_pixel_bad(good,model,[](Grid& bad){bad.put(60,5,"─");});
        remaining24_pixel_bad(good,model,[&](Grid& bad){bad.put(32,nested?17:15,"│");});
        remaining24_pixel_bad(good,model,[&](Grid& bad){bad.put(35,nested?17:15," ");});
        remaining24_pixel_bad(good,model,[&](Grid& bad){bad.put(32,nested?13:11," ");});
        remaining24_model_bad(good,model,[](Model& wrong){wrong.fragments[0].kind="par";});
        remaining24_model_bad(good,model,[](Model& wrong){wrong.fragments[0].label="Other";});
    }
    // All A/B routes and the Note remain complete inside this narrower frame.
    // C's untouched identity/rail is outside: only par_over's explicit full-scene
    // background contract distinguishes this from an ordinary child envelope.
    const auto model=par_over_literal_wide_model(false);
    const auto whole=par_over_literal_wide_hand(false);
    remaining24_pixel_bad(whole,model,[](Grid& narrow){
        for(int y=5;y<=22;++y)for(int x=57;x<=76;++x)narrow.put(x,y,x==60?"│":" ");
        for(int y=6;y<22;++y)narrow.put(56,y,"│");
        narrow.put(56,5,"┐");narrow.put(56,7,"┤");narrow.put(56,22,"┘");
        for(int x=1;x<56;++x)narrow.put(x,6," ");
        narrow.text(20,6,"par_over Everyone");
    });
}
TEST(MermaidParOverOracle, WholeFramePreservesBirthDeathAndSurvivingNoteWithoutGhostRails) {
    const auto good=par_over_literal_lifetime_hand();
    const auto model=par_over_literal_lifetime_model();
    ASSERT_TRUE(remaining24_good(good,model));
    remaining24_pixel_bad(good,model,[](Grid& bad){bad.put(36,8,"│");});
    // Create owns a birth somewhere before its associated message label,
    // not a source-authored fixed Y coordinate. Removing only row10 shifts
    // the continuous valid rail to row11; it is a genuine positive variant.
    {
        Work work;
        work.spend(good.cells.size()*8+64);
        auto later_birth=good;
        later_birth.put(36,10," ");
        check_event_model(model,work);
        const auto errors=validate(later_birth,model,work.remaining);
        first19_no_resource_rejection(errors);
        ASSERT_TRUE(errors.empty())<<(errors.empty()?"":errors.front());
    }
    // Removing the whole eligible gap (rows10 and11) leaves no owned birth
    // before the creating label at11; the route endpoint at12 remains intact.
    remaining24_pixel_bad(good,model,[](Grid& bad){
        bad.put(36,10," ");bad.put(36,11," ");
    });
    remaining24_pixel_bad(good,model,[](Grid& bad){bad.put(36,20," ");});
    remaining24_pixel_bad(good,model,[](Grid& bad){bad.put(36,22,"│");});
    remaining24_pixel_bad(good,model,[](Grid& bad){bad.put(36,28,"┼");});
    remaining24_pixel_bad(good,model,[](Grid& bad){bad.put(8,25,"─");});
    remaining24_model_bad(good,model,[](Model& wrong){wrong.messages[1].dashed=false;});
    remaining24_model_bad(good,model,[](Model& wrong){wrong.notes[0].actors={1};});
}

