bool literal6_complete_tiny_public(std::string_view source, const Model& model, Work& work) {
    if (source.empty() || source.size() > 65536) throw std::runtime_error("Literal6 tiny source domain");
    work.spend(source.size() * 2 + 64);
    const auto input = std::string(source);
    const auto frames = literal6_capture(input, work);
    const bool good = literal6_geometry(frames, model, work);
    EXPECT_TRUE(good);
    if (!good) return false;
    const auto copied = wrap43_copy_charge(model, work);
    const auto changes = description77_fixed_mutations(frames.wide, model, copied);
    for (const auto& error : changes.errors) ADD_FAILURE() << error;
    return changes.errors.empty();
}
// This precise legacy join asserts complete source geometry and mutations;
// true denotes a selected source, including any explicit failed assertion.
bool literal6_migrated_public(std::string_view source) {
    Work work;
    work.spend(kLiteral6LegacyModels.size() * 4 + source.size() + 128);
    const auto owner = json::parse(kLiteral6LegacyModels);
    official_role38_require(owner.has_value() && owner->root().get("cases").is_arr() &&
        owner->root().get("cases").size() == 8, "Literal6 complete legacy tiny source set");
    std::optional<JsonVal> selected;
    owner->root().get("cases").iter([&](JsonVal item) {
        official_role38_require(item.get("input").is_str(), "Literal6 exact source type");
        work.spend(item.get("input").as_str().size() + source.size() + 32);
        if (item.get("input").as_str() != source) return;
        official_role38_require(!selected, "Literal6 legacy source is unique"); selected = item;
    });
    if (!selected) return false;
    bool complete = false;
    try {
        const auto item = *selected;
        work.spend(source.size() * 2 + 64);
        official_role38_require(loom::utils::crypto::sha256(source) == item.get_string("input_sha256") &&
            item.get_string("number_encoding") == "DisplayText", "Literal6 exact raw tiny source/number schema");
        const auto model = remaining24_model(item.get("model"), item.get_string("model_sha256"), work);
        complete = literal6_complete_tiny_public(source, model, work);
    } catch (const std::exception& error) { ADD_FAILURE() << "Literal6 whole tiny assertion: " << error.what(); }
    EXPECT_TRUE(complete);
    return true;
}
TEST(MermaidLiteralPunctuation6, CompletePrimaryBrTokensKeepCaseAsciiWhitespaceAndFieldOwnership) {
    // This independently authored paper already passed the first Literal6 hand
    // gate. Complete BR spelling supplies the same two literal rows L/R.
    Work paper_work;paper_work.spend(256);
    const auto model = literal6_model(4);
    const auto paper = literal6_paper(4, paper_work);
    ASSERT_TRUE(remaining24_good(paper, model));
    remaining24_model_bad(paper, model, [](Model& wrong) { wrong.messages[0].label = "LR"; });
    remaining24_pixel_bad(paper, model, [](Grid& wrong) { wrong.put(22, 5, " "); });
    const std::array<std::string_view, 10> tags{{"<br>", "<BR>", "<Br/>", "<bR />", "<br  />",
        "<br\t/>", "<br\v/>", "<br\f/>", "<br\r/>", "<BR \t\v\f\r/>"}};
    int projected = 0, public_cases = 0, physical_cr_deferred = 0;
    for (const auto tag : tags) {
        SCOPED_TRACE(std::string(tag));
        for (const bool wrapped : {false, true}) {
            Work work;work.spend(tag.size() * 4 + 256);
            const auto raw = "L" + std::string(tag) + "R";
            EXPECT_EQ(wrap43_project_label(raw, wrapped, 76, work), "L\nR"); ++projected;
            const auto source = (wrapped ? std::string("%%{init: {\"sequence\":{\"wrap\":true}}}%%\n") : std::string{}) +
                "sequenceDiagram\nA->>B: " + raw;
            if (tag.find('\r') != std::string_view::npos) {
                // Physical CR is normalized to a statement LF before the pinned
                // source lexer. This is an unreviewed whole-source boundary,
                // not an upstream-invalid source or a completed BR scene.
                text7_expect_source(source); ++physical_cr_deferred;
            } else {
                EXPECT_TRUE(literal6_complete_tiny_public(source, model, work)); ++public_cases;
            }
        }
    }
    // Full Label-layer LF is a BR whitespace byte. A physical source newline
    // is also a statement delimiter: this direct projection is not a claim
    // that a multiline TXT or JSON metadata alias source profile has passed.
    for (const bool wrapped : {false, true}) {
        Work work;EXPECT_EQ(wrap43_project_label("L<br\n/>R", wrapped, 76, work), "L\nR");++projected;
    }
    // Selected metadata labels retain the same raw-BR ownership; JSON escapes
    // transport CR without introducing a physical source statement separator.
    for (const auto tag : {std::string_view("<BR>"), std::string_view("<br\r/>")})
        for (const bool wrapped : {false, true}) {
            Work work;work.spend(tag.size() * 8 + 1024);
            json::JsonMutDoc encoded;auto text = encoded.string("L" + std::string(tag) + "R");encoded.set_root(text);
            const auto source = (wrapped ? std::string("%%{init: {\"sequence\":{\"wrap\":true}}}%%\n") : std::string{}) +
                "sequenceDiagram\nparticipant A@{\"alias\":" + encoded.to_string() + "}\nA->>B: one";
            auto expected = literal6_model(4);expected.actors[0].label = "L\nR";expected.messages[0].label = "one";
            EXPECT_TRUE(literal6_complete_tiny_public(source, expected, work));++public_cases;
        }
    // Malformed/raw tags still contain source-owned physical CR. They cannot
    // enter the new literal path and acquire a synthetic Safe CR disclosure.
    for (const auto raw : {std::string_view("L<br\rX>R"), std::string_view("L<tag\r/>R")})
        for (const bool wrapped : {false, true}) {
            const auto source = (wrapped ? std::string("%%{init: {\"sequence\":{\"wrap\":true}}}%%\n") : std::string{}) +
                "sequenceDiagram\nA->>B: " + std::string(raw);
            text7_expect_source(source); ++physical_cr_deferred;
        }
    // Raw Text ownership precedes trim, prefix selection and AS splitting.
    // These CR bytes must not disappear before the source-boundary decision.
    for (const auto body : {"A->>B:\r<tag>", "A->>B: nowrap:\r<tag>",
         "participant A as \r<tag>\nA->>B: one",
         "participant A@{\"alias\":\"Meta\"} as \r<tag>\nA->>B: one"})
        for (const bool wrapped : {false, true}) {
            const auto source = (wrapped ? std::string("%%{init: {\"sequence\":{\"wrap\":true}}}%%\n") : std::string{}) +
                "sequenceDiagram\n" + std::string(body);
            text7_expect_source(source); ++physical_cr_deferred;
        }
    EXPECT_EQ(projected, 22);EXPECT_EQ(public_cases, 20);EXPECT_EQ(physical_cr_deferred, 16);
    // Neither a complete BR spelling nor literal tags broaden these roles.
    for (const auto source : {"sequenceDiagram\ntitle <tag>\nA->>B: one",
         "sequenceDiagram\nbox <tag>\nparticipant A\nend\nA->>B: one"}) text7_expect_source(source);
    Work empty;empty.remaining = 0;
    EXPECT_THROW(wrap43_source_atoms("L<BR>R", empty), std::runtime_error);
}

