TEST(MermaidLiteralPunctuation6, InitialHashAfterSemicolonKeepsWholeFieldsAndProtectedAtoms) {
    struct Partner {std::string_view source,id,label,message;};
    constexpr std::array<Partner,6> positives{{
        {"sequenceDiagram;# comment\nA->>B: one\n","A","A","one"},
        {"sequenceDiagram\nA->>B: one; # comment\n","A","A","one"},
        {"sequenceDiagram\nA->>B: literal #38; data;# comment\n","A","A","literal & data"},
        {"sequenceDiagram\nA->>B: before #lt;br#gt; after; # comment\n","A","A","before <br> after"},
        {"sequenceDiagram\nparticipant \"A#35;\"\n\"A#35;\"->>B: one;# comment\n","A#35;","A#35;","one"},
        {"sequenceDiagram\nparticipant A@{\"alias\":\"Meta#38; #lt;tag#gt;\"}\nA->>B: one; # comment\n","A","Meta& <tag>","one"},
    }};
    int completed=0;
    for (const auto& partner:positives) {
        SCOPED_TRACE(std::string(partner.source));
        try {
            Work work;work.spend(partner.source.size()*8+2048);
            auto expected=literal6_model(4);
            expected.actors[0].id=std::string(partner.id);
            expected.actors[0].label=std::string(partner.label);
            expected.messages[0].label=std::string(partner.message);
            completed+=literal6_complete_tiny_public(partner.source,expected,work)?1:0;
        } catch(const std::exception& error) {
            ADD_FAILURE()<<"INITIAL-comment whole-source/schema/resource error, not rejection credit: "<<error.what();
        }
    }
    EXPECT_EQ(completed,6);
    // These preserve closed source profiles, not schema/geometry negatives.
    // In particular raw CR may introduce another primary business statement.
    constexpr std::array<std::string_view,6> closed{{
        "sequenceDiagram\nA->>B: #unknown;\n",
        "sequenceDiagram\nA->>B: #35\n",
        "sequenceDiagram\nA->>B: #59\n",
        "sequenceDiagram;#unknown;\nA->>B: one\n",
        "sequenceDiagram\nparticipant A@{\"alias\":\"#unknown;\"}\nA->>B: one;# comment\n",
        "sequenceDiagram\nA->>B: one;# comment\rA->>C: extra\n",
    }};
    for(const auto source:closed) {
        SCOPED_TRACE(std::string(source));
        try {
            Work work;
            // Exact existing text7_expect_source captures one initial wide,
            // then node/source at240/40/240, all with physical sentinel.
            // Prepay those seven fixed240-high frames and complete source copies.
            work.spend((5u*240u+2u*40u)*240u*8u+source.size()*8u+1024u);
            text7_expect_source(source);
        } catch(const std::exception& error) {ADD_FAILURE()<<"Closed source observation/resource error: "<<error.what();}
    }
}
