constexpr std::string_view kFinal3FactsPath = "mermaid_native/sequence_remaining24_final3_facts.json";
constexpr std::string_view kFinal3FactsSha = "1a525d44f48d4d81996832ef0e9b17ade78d261ed33daa16f932586ebcecc623";
constexpr std::string_view kFinal3ModelSha = "fec9cc5289022e607427aabd19f0be0676a2ed2bb81dbd77ab9c4a683cf228dc";
json::JsonDoc final3_document() {
    Work setup;
    const auto bytes = joined683_fixture(kFinal3FactsPath, kFinal3FactsSha, setup);
    auto doc = json::parse(bytes);
    official_role38_require(doc.has_value(), "Final3 complete source asset parse");
    const auto root = doc->root();
    official_role38_require(root.get("schema").is_int() && root.get_int("schema") == 1 &&
        root.get_string("kind") == "remaining24_final_three_native_source_first/v1" &&
        root.get_string("source_review_sha256") == "ec3e5eb72808546bfe14336c474006d7d09dc73c7c2a0a684e8a5c19ec3f0f56" &&
        root.get("whole_original_cases").get("cases").size() == 3,
        "Final3 immutable source selection and independent source review");
    return std::move(*doc);
}
// Independent literal Model for the one drawing source; every logical event is
// retained. This constructor never calls a renderer or weakens the old codec.
Model final3_literal_model(Work& work) {
    work.spend(1024);
    Model m{{{"A", "A"}, {"B", "B"}},
            {{0, 1, "Work", false}, {0, 1, "Bye", true, Arrow::Cross}}, {}};
    m.order = {{EventKind::Activate, 1}, {EventKind::Message, 0},
               {EventKind::Message, 1}, {EventKind::Destroy, 1}, {EventKind::Deactivate, 1}};
    return m;
}
void final3_logical_source_binding(JsonVal postdeath, const Model& m, Work& work) {
    const auto source = postdeath.get("input");
    official_role38_require(source.is_str() && source.as_str().size() == 100,
                            "Final3 complete postdeath source bytes");
    work.spend(source.as_str().size() * 4 + 128);
    official_role38_require(loom::utils::crypto::sha256(source.as_str()) ==
        "33aea29bc46bd1fd8f76d139414061aaa31d2d4aa0773937dd744300bad649f0",
        "Final3 complete postdeath source digest");
    const auto meaning = postdeath.get("proposed_native_model");
    official_role38_require(loom::utils::crypto::sha256(joined683_canonical(meaning, work)) == kFinal3ModelSha,
                            "Final3 reviewed complete Model digest");
    const auto expected = final3_literal_model(work);
    official_role38_require(joined683_same_model(expected, m, work),
                            "Final3 complete source logical five-event binding");
    const auto primary = postdeath.get("primary_model_original");
    official_role38_require(primary.get("messages").size() == 4 &&
        primary.get("messages").at(0).get_int("type") == 17 &&
        primary.get("messages").at(1).get_int("type") == 0 &&
        primary.get("messages").at(2).get_int("type") == 4 &&
        primary.get("messages").at(3).get_int("type") == 18 &&
        primary.get("destroyedActors").get_int("B") == 2,
        "Final3 primary start/two-signals/end and destruction episode retained");
}
Grid final3_literal_hand(Work& work) {
    work.spend(60 * 30 * 4 + 256);
    Grid g{60, 30, std::vector<std::string>(60 * 30, " ")};
    g.text(5, 0, "┌─────┐"); g.text(5, 1, "│ A   │"); g.text(5, 2, "└─────┘");
    g.text(33, 0, "┌─────┐"); g.text(33, 1, "│ B   │"); g.text(33, 2, "└─────┘");
    for (int y = 3; y <= 26; ++y) g.put(8, y, "│");
    for (int y = 3; y <= 14; ++y) g.put(36, y, y >= 5 ? "┃" : "│");
    g.text(35, 5, "╺╋╸");
    g.text(14, 7, "Work"); g.put(8, 8, "├"); g.put(36, 8, "▶");
    for (int x = 9; x < 36; ++x) g.put(x, 8, "─");
    g.text(14, 11, "Bye"); g.put(8, 12, "├"); g.put(36, 12, "×");
    for (int x = 9; x < 36; ++x) g.put(x, 12, "┄");
    g.put(36, 15, "×"); g.text(0, 28, kSentinel);
    return g;
}
struct Final3Observation { Grid wide, narrow, restored, ordinary, small_ordinary; };
Final3Observation final3_capture(std::string_view source, Work& work) {
    official_role38_require(!source.empty() && source.size() <= 65536,
                            "Final3 complete source admission");
    // Five complete captures, their string/cell storage, and two fenced inputs.
    // This is one scene ledger; none of the geometry below receives a reset.
    work.spend(4 * (3 * 240 + 2 * 40) * 1024 + source.size() * 8 + 1024);
    auto node = loom::ui::render_markdown(fenced(source, "mermaid"));
    auto text = loom::ui::render_markdown(fenced(source, "text"));
    Final3Observation out{capture(node, 240, 1024), capture(node, 40, 1024),
        capture(node, 240, 1024), capture(text, 240, 1024), capture(text, 40, 1024)};
    official_role38_require(out.wide == out.restored, "Final3 same-Node complete240 restoration");
    for (const auto* frame : {&out.wide, &out.narrow, &out.restored, &out.ordinary, &out.small_ordinary}) {
        work.spend(frame->cells.size() + 1);
        official_role38_require(complete_sequence_sentinel(*frame), "Final3 complete physical following sentinel");
    }
    return out;
}
TEST(MermaidRemainingFinal3Native, CompleteThreeSourcesRetainWholePrimaryFunctionsAndDistinctDispositions) {
    const auto facts = final3_document();
    // Existing immutable vendor-file loader scope: this16MB I/O is source
    // integrity, not a scene budget or a claim of production resource parity.
    const auto bytes = fixture_bytes("mermaid_terminal/merman/cases.json");
    ASSERT_EQ(bytes.size(), 16326956u);
    ASSERT_EQ(loom::utils::crypto::sha256(bytes), kMerman280ManifestSha);
    const auto vendor = json::parse(bytes); ASSERT_TRUE(vendor);
    int bound = 0;
    facts.root().get("whole_original_cases").get("cases").iter([&](JsonVal item) {
        Work work;
        const auto original = item.get("frozen_source_case");
        const auto source = original.get("input");
        ASSERT_TRUE(source.is_str()); work.spend(source.as_str().size() * 4 + 256);
        ASSERT_EQ(loom::utils::crypto::sha256(source.as_str()), original.get_string("input_sha256"));
        ASSERT_EQ(loom::utils::crypto::sha256(joined683_canonical(original, work)), item.get_string("frozen_case_sha256"));
        const auto live = pointer(vendor->root(), original.get_string("vendor_case_pointer"));
        ASSERT_EQ(live.get_string("id"), item.get_string("id"));
        ASSERT_EQ(live.get("input").as_str(), source.as_str());
        ASSERT_EQ(joined683_canonical(live, work), joined683_canonical(item.get("whole_vendor_case"), work));
        ASSERT_EQ(loom::utils::crypto::sha256(joined683_canonical(live, work)), item.get_string("whole_vendor_case_sha256"));
        ASSERT_TRUE(original.get("native_model").is_null());
        item.get("physical_source_witnesses").iter([&](JsonVal line) {
            const auto offset = static_cast<std::size_t>(line.get_int("offset_utf8_bytes"));
            const auto size = static_cast<std::size_t>(line.get_int("byte_length"));
            work.spend(size * 4 + 64);
            ASSERT_LE(offset, source.as_str().size()); ASSERT_LE(size, source.as_str().size() - offset);
            ASSERT_EQ(source.as_str().substr(offset, size), line.get("text").as_str());
            ASSERT_EQ(loom::utils::crypto::sha256(line.get("text").as_str()), line.get_string("sha256"));
        });
        const auto primary = original.get("primary_ref");
        if (primary.is_obj()) {
            const auto primary_bytes = joined683_fixture("mermaid_terminal/merman/" + primary.get_string("path"), primary.get_string("sha256"), work);
            const auto parsed = json::parse(primary_bytes); ASSERT_TRUE(parsed);
            ASSERT_EQ(joined683_canonical(parsed->root(), work), joined683_canonical(original.get("complete_primary_model"), work));
        } else ASSERT_TRUE(original.get("complete_primary_model").is_null());
        original.get("original_complete_functions").iter([&](JsonVal function) {
            const auto path = "mermaid_terminal/merman/" + function.get_string("path");
            const auto text = joined683_fixture(path, function.get_string("sha256"), work);
            ASSERT_FALSE(text.empty());
        });
        ++bound;
    });
    EXPECT_EQ(bound, 3);
    const auto postdeath = facts.root().get("postdeath"); Work binding;
    const auto full = final3_literal_model(binding);
    EXPECT_NO_THROW(final3_logical_source_binding(postdeath, full, binding));
    binding.spend(1024); auto omitted = full; omitted.order.pop_back();
    try { final3_logical_source_binding(postdeath, omitted, binding); ADD_FAILURE() << "Invisible end omission escaped source binding"; }
    catch (const std::runtime_error& e) { EXPECT_EQ(std::string_view(e.what()), "Final3 complete source logical five-event binding"); }
    binding.spend(1024); auto moved = full; std::swap(moved.order[3], moved.order[4]);
    try { final3_logical_source_binding(postdeath, moved, binding); ADD_FAILURE() << "Invisible end reorder escaped source binding"; }
    catch (const std::runtime_error& e) { EXPECT_EQ(std::string_view(e.what()), "Final3 complete source logical five-event binding"); }
    const auto paper = facts.root().get("literal_hand"); const auto literal = final3_literal_hand(binding);
    ASSERT_EQ(paper.get_int("width"), literal.width); ASSERT_EQ(paper.get_int("height"), literal.height);
    ASSERT_EQ(paper.get("literal_rows").size(), static_cast<std::size_t>(literal.height));
    for (int y = 0; y < literal.height; ++y) {
        binding.spend(static_cast<std::size_t>(literal.width) * 4 + 64);
        EXPECT_EQ(literal.row(y), paper.get("literal_rows").at(static_cast<std::size_t>(y)).as_str());
    }
}
TEST(MermaidRemainingFinal3Native, IndependentDeathTruncatedStripKeepsLogicalEndWithoutGhostInk) {
    Work work; const auto model = final3_literal_model(work); const auto good = final3_literal_hand(work);
    // These are positive assertions: the first run must retain the old
    // checker's genuine profile/schema failure instead of treating it as a bad
    // drawing. No counterexample is credited until the complete good passes.
    EXPECT_NO_THROW(check_event_model(model, work));
    const auto errors = validate(good, model, work.remaining); first19_no_resource_rejection(errors);
    EXPECT_TRUE(errors.empty()) << (errors.empty() ? "" : errors.front());
    if (!errors.empty()) return;
    for (const auto& point : std::array<std::tuple<int,int,std::string_view>, 5>{{
        {36,14," "}, {36,15,"│"}, {36,18,"┃"}, {36,23,"│"}, {36,12,"▶"}}}) {
        Work mutant; mutant.spend(good.cells.size() * 4 + 1024);
        auto bad = good; bad.put(std::get<0>(point), std::get<1>(point), std::get<2>(point));
        const auto rejected = validate(bad, model, mutant.remaining); first19_no_resource_rejection(rejected);
        EXPECT_FALSE(rejected.empty());
    }
    Work ghost_work; ghost_work.spend(good.cells.size() * 4 + 1024);
    auto ghost = good; ghost.text(35,18,"╺╋╸");
    const auto ghost_errors = validate(ghost, model, ghost_work.remaining); first19_no_resource_rejection(ghost_errors);
    EXPECT_FALSE(ghost_errors.empty());
    Work earlier; earlier.spend(1024); auto visible_close = model;
    visible_close.order = {{EventKind::Activate,1},{EventKind::Message,0},{EventKind::Deactivate,1},
                          {EventKind::Message,1},{EventKind::Destroy,1}};
    ASSERT_NO_THROW(check_event_model(visible_close, earlier));
    const auto rejected = validate(good, visible_close, earlier.remaining); first19_no_resource_rejection(rejected);
    EXPECT_FALSE(rejected.empty()) << "A genuinely visible earlier end needs its own cap";
    // Actual resource failure remains an oracle failure, never geometry credit.
    const auto zero = validate(good, model, 0); ASSERT_FALSE(zero.empty());
    EXPECT_TRUE(std::ranges::any_of(zero, [](const auto& e) { return termaid47_resource(e); }));
}
