NoteAlignment config38_alignment(std::string_view value){
    if(value=="left")return NoteAlignment::Left;if(value=="center")return NoteAlignment::Center;if(value=="right")return NoteAlignment::Right;
    throw std::runtime_error("Config38 Note alignment enum protocol");
}
std::string_view config38_name(NoteAlignment value){
    if(value==NoteAlignment::Left)return "left";if(value==NoteAlignment::Center)return "center";if(value==NoteAlignment::Right)return "right";
    throw std::runtime_error("Config38 Note alignment enum protocol");
}
void config38_alignment_binding(JsonVal item,const NoteAlignment& requested,Work& work){
    work.spend(256);const auto expected=config38_name(requested);const auto leaves=item.get("config_complete_leaf_inventory");
    official_role38_require(leaves.is_arr(),"Config38 alignment leaf array protocol");int found=0;
    leaves.iter([&](JsonVal leaf){
        const auto path=leaf.get("path");official_role38_require(path.is_str(),"Config38 alignment leaf path protocol");work.spend(path.as_str().size()+1);
        if(path.as_str()!="sequence.noteAlign")return;
        config110_keys(leaf,{"path","kind","yaml_tag","value"},work);const auto value=leaf.get("value");
        official_role38_require(leaf.get("kind").is_str()&&leaf.get_string("kind")=="scalar"&&leaf.get("yaml_tag").is_str()&&leaf.get_string("yaml_tag")=="tag:yaml.org,2002:str"&&value.is_str(),"Config38 alignment source scalar protocol");
        work.spend(value.as_str().size()+64);const auto actual=config38_alignment(value.as_str());
        official_role38_require(actual==requested&&value.as_str()==expected,"Config38 source alignment differs");++found;
    });official_role38_require(found==1,"Config38 source alignment cardinality protocol");
}
void config38_no_protocol_or_resource(const std::vector<std::string>& errors){
    first19_no_resource_rejection(errors);for(const auto& error:errors)if(error.starts_with("Config38 "))throw std::runtime_error("Config38 protocol error is not geometry rejection: "+error);
}
void config38_pin_binding(JsonVal item,const Config38Pin& pin,Work& work){
    work.spend(pin.id.size()+pin.source_sha.size()+pin.model_sha.size()+pin.leaves_sha.size()+128);
    official_role38_require(item.get("ordinal").is_int()&&item.get_int("ordinal")==static_cast<std::int64_t>(pin.ordinal)&&item.get("id").as_str()==pin.id&&item.get("input_sha256").as_str()==pin.source_sha&&item.get("model_sha256").as_str()==pin.model_sha&&item.get("config_leaves_sha256").as_str()==pin.leaves_sha&&item.get("profile").as_str()=="fixed","Config38 exact whole selected source/Model/config pins");
    if(pin.note_alignment>=0){const auto alignment=static_cast<NoteAlignment>(pin.note_alignment);config38_alignment_binding(item,alignment,work);}
}
Rect config38_rect(JsonVal value,Work& work){
    official_role38_require(value.is_arr()&&value.size()==4,"Config38 paper rectangle protocol");int v[4]{};
    for(std::size_t n=0;n<4;++n){work.spend();official_role38_require(value.at(n).is_int()&&value.at(n).as_int()>=0&&value.at(n).as_int()<80,"Config38 paper rectangle domain protocol");v[n]=static_cast<int>(value.at(n).as_int());}
    official_role38_require(v[0]+3<v[2]&&v[1]+1<v[3]&&v[3]<32,"Config38 paper rectangle domain protocol");return {v[0],v[1],v[2],v[3]};
}
Grid config38_note_paper(JsonVal paper,const Model& model,Work& work){
    official_role38_require(model.actors.size()==2&&model.messages.empty()&&model.notes.size()==3&&model.fragments.empty()&&model.boxes.empty(),"Config38 whole paper Model protocol");
    const int shift=model.title.empty()?0:2;official_role38_require(model.title.empty()||rows(model.title).size()==1,"Config38 title paper protocol");
    const int width=80,height=33+shift;work.spend(static_cast<std::size_t>(width*height)*(sizeof(std::string)+8u)+256u);Grid grid{width,height,std::vector<std::string>(static_cast<std::size_t>(width*height)," ")};
    if(shift){work.spend(model.title.size()*4+64);grid.text(0,0,model.title);}
    auto box=[&](Rect r){
        for(int y=r.t;y<=r.b;++y)for(int x=r.l;x<=r.r;++x){work.spend();grid.put(x,y+shift," ");}
        grid.put(r.l,r.t+shift,"┌");grid.put(r.r,r.t+shift,"┐");grid.put(r.l,r.b+shift,"└");grid.put(r.r,r.b+shift,"┘");
        for(int x=r.l+1;x<r.r;++x){work.spend(2);grid.put(x,r.t+shift,"─");grid.put(x,r.b+shift,"─");}
        for(int y=r.t+1;y<r.b;++y){work.spend(2);grid.put(r.l,y+shift,"│");grid.put(r.r,y+shift,"│");}
    };
    for(std::size_t a=0;a<2;++a){
        const auto r=config38_rect(paper.get("actor_rectangles").at(a),work);box(r);work.spend(model.actors[a].label.size()*4+64);const auto text=rows(model.actors[a].label);const auto starts=paper.get("literal_actor_row_starts").at(a);
        official_role38_require(starts.is_arr()&&starts.size()==text.size()&&text.size()==static_cast<std::size_t>(r.b-r.t-1),"Config38 literal actor rows protocol");
        for(std::size_t row=0;row<text.size();++row){official_role38_require(starts.at(row).is_int(),"Config38 literal start protocol");work.spend(text[row].size()*4+1);const auto start=starts.at(row).as_int();const int cells=ftxui::string_width(text[row]);official_role38_require(cells>=0&&start>r.l&&start<r.r&&start+cells<=r.r,"Config38 literal row bounds protocol");grid.text(static_cast<int>(start),r.t+1+static_cast<int>(row)+shift,text[row]);}
        const int center=a==0?23:66;for(int y=r.b+1;y<32;++y){work.spend();grid.put(center,y+shift,"│");}
    }
    for(std::size_t n=0;n<3;++n){
        const auto r=config38_rect(paper.get("note_rectangles").at(n),work);box(r);work.spend(model.notes[n].text.size()*4+64);const auto text=rows(model.notes[n].text);const auto starts=paper.get("literal_note_row_starts").at(n);
        official_role38_require(starts.is_arr()&&starts.size()==text.size()&&text.size()==static_cast<std::size_t>(r.b-r.t-1),"Config38 literal Note rows protocol");
        for(std::size_t row=0;row<text.size();++row){official_role38_require(starts.at(row).is_int(),"Config38 literal start protocol");work.spend(text[row].size()*4+1);const auto start=starts.at(row).as_int();const int cells=ftxui::string_width(text[row]);official_role38_require(cells>=0&&start>r.l&&start<r.r&&start+cells<=r.r,"Config38 literal row bounds protocol");grid.text(static_cast<int>(start),r.t+1+static_cast<int>(row)+shift,text[row]);}
        if(n==0){const int port=(r.t+r.b)/2;grid.put(r.r,port+shift,"├");for(int x=r.r+1;x<23;++x){work.spend();grid.put(x,port+shift,"─");}grid.put(23,port+shift,"┤");}
        else if(n==1){const int port=(r.t+r.b)/2;grid.put(r.l,port+shift,"┤");for(int x=24;x<r.l;++x){work.spend();grid.put(x,port+shift,"─");}grid.put(23,port+shift,"├");}
        else{grid.put(23,r.t+shift,"┴");grid.put(23,r.b+shift,"┬");}
    }
    work.spend(kSentinel.size()*4+64);grid.text(0,32+shift,kSentinel);return grid;
}
TEST(MermaidConfig38Native, LiteralWholeNotesBindAlignmentToTheChosenRectAndPreserveDefaultGeometry){
    Work setup;setup.spend(kConfig38Hands.size()*3+256);const auto document=json::parse(kConfig38Hands);ASSERT_TRUE(document);ASSERT_EQ(document->root().size(),7u);int good_count=0,position_rejected=0,other_rejected=0;
    document->root().iter([&](JsonVal paper){SCOPED_TRACE(paper.get_string("name"));try{
        Work work;const auto source=paper.get("source");official_role38_require(source.is_str()&&source.as_str().size()<=65536,"Config38 paper source protocol");work.spend(source.as_str().size()*2+128);official_role38_require(loom::utils::crypto::sha256(source.as_str())==paper.get_string("source_sha256"),"Config38 paper complete source digest");
        const auto model=remaining24_model(paper.get("model"),paper.get_string("model_sha256"),work);const auto alignment=config38_alignment(paper.get_string("alignment"));const auto good=config38_note_paper(paper,model,work);const auto allowance=work.remaining;
        const auto legacy=validate(good,model,allowance);first19_no_resource_rejection(legacy);ASSERT_TRUE(legacy.empty())<<(legacy.empty()?std::string{}:legacy.front());
        const auto accepted=validate(good,model,allowance,nullptr,&alignment);config38_no_protocol_or_resource(accepted);ASSERT_TRUE(accepted.empty())<<(accepted.empty()?std::string{}:accepted.front());++good_count;
        auto reject=[&](auto change,bool legacy_still_good,bool position){Work mutation;mutation.spend(good.cells.size()*(sizeof(std::string)+8u)+256u);auto wrong=good;change(wrong);if(legacy_still_good){const auto old=validate(wrong,model,mutation.remaining);first19_no_resource_rejection(old);ASSERT_TRUE(old.empty())<<"Position-only mutant must retain complete old semantics: "<<(old.empty()?std::string{}:old.front());}const auto errors=validate(wrong,model,mutation.remaining,nullptr,&alignment);config38_no_protocol_or_resource(errors);EXPECT_FALSE(errors.empty())<<"Accepted same-Rect Note adversary";if(!errors.empty()){if(position)++position_rejected;else ++other_rejected;}};
        const int offset=model.title.empty()?0:2;const int start=static_cast<int>(paper.get("literal_note_row_starts").at(0).at(0).as_int());work.spend(model.notes[0].text.size()*4u+64u);const auto rows_of_note=rows(model.notes[0].text);const auto& label=rows_of_note.front();const int cells=ftxui::string_width(label);
        reject([&](Grid& wrong){for(int x=start;x<start+cells;++x)wrong.put(x,6+offset," ");wrong.text(start+1,6+offset,label);},true,true);
        const int cjk_row=static_cast<int>(rows_of_note.size()-1),cjk_start=static_cast<int>(paper.get("literal_note_row_starts").at(0).at(static_cast<std::size_t>(cjk_row)).as_int());const int continuation=cjk_start+ftxui::string_width(rows_of_note.back())-1;
        reject([&](Grid& wrong){official_role38_require(wrong.at(continuation,6+cjk_row+offset).empty(),"Config38 actual CJK continuation witness protocol");wrong.put(continuation,6+cjk_row+offset," ");},false,false);
        reject([&](Grid& wrong){wrong.put(21,6+offset," ");},false,false);
        reject([&](Grid& wrong){wrong.put(0,30+offset,"X");},false,false);
        // The same words in the chosen B header are deliberately not governed
        // by Note alignment. Its first row can retain legacy padding freedom.
        Work header_work;header_work.spend(good.cells.size()*(sizeof(std::string)+8u)+256u);auto shifted_header=good;header_work.spend(model.actors[1].label.size()*4u+64u);const auto header_rows=rows(model.actors[1].label);const int header_start=static_cast<int>(paper.get("literal_actor_row_starts").at(1).at(0).as_int()),header_width=ftxui::string_width(header_rows.front());for(int x=header_start;x<header_start+header_width;++x)shifted_header.put(x,1+offset," ");shifted_header.text(header_start+1,1+offset,header_rows.front());const auto header_errors=validate(shifted_header,model,header_work.remaining,nullptr,&alignment);config38_no_protocol_or_resource(header_errors);EXPECT_TRUE(header_errors.empty())<<(header_errors.empty()?std::string{}:header_errors.front());
        const auto invalid=static_cast<NoteAlignment>(99);const auto protocol=validate(good,model,allowance,nullptr,&invalid);ASSERT_EQ(protocol.size(),1u);EXPECT_EQ(protocol.front(),"Config38 Note alignment enum protocol");
        const auto exhausted=validate(good,model,0,nullptr,&alignment);EXPECT_TRUE(std::ranges::any_of(exhausted,[](const auto& value){return termaid47_resource(value);}));
    }catch(const std::exception& error){ADD_FAILURE()<<error.what();}});
    EXPECT_EQ(good_count,7);EXPECT_EQ(position_rejected,7);EXPECT_EQ(other_rejected,21);
}
// Small hand-source public controls reuse the same complete Model reader and
// whole validator, not config110's immutable-manifest adapter or a new parser.
void config38_public_partner(JsonVal partner){
    Work work;const auto raw=partner.get("source");official_role38_require(raw.is_str()&&raw.as_str().size()<=65536,"Config38 partner complete source protocol");work.spend(raw.as_str().size()*6+256);const auto source=std::string(raw.as_str());
    official_role38_require(loom::utils::crypto::sha256(source)==partner.get_string("source_sha256"),"Config38 partner source digest");
    const auto node=loom::ui::render_markdown(fenced(source,"mermaid")),plain=loom::ui::render_markdown(fenced(source,"text"));node->ComputeRequirement();plain->ComputeRequirement();const int height=std::min(1040,std::max(40,std::max(node->requirement().min_y,plain->requirement().min_y)+12));work.spend(static_cast<std::size_t>(height)*(3u*240u+2u*40u)*8u+256u);
    const auto wide=capture(node,240,height),ordinary=capture(plain,240,height),narrow=capture(node,40,height),small=capture(plain,40,height),restored=capture(node,240,height);EXPECT_EQ(wide,restored);for(const auto* frame:{&wide,&narrow,&restored}){work.spend(frame->cells.size()+1);EXPECT_TRUE(complete_sequence_sentinel(*frame));}
    const auto expected=partner.get_string("expected");official_role38_require(expected=="whole_scene"||expected=="whole_source_closed_profile","Config38 partner expectation protocol");
    if(expected=="whole_source_closed_profile"){EXPECT_EQ(wide,ordinary);EXPECT_EQ(narrow,small);EXPECT_EQ(restored,ordinary);return;}
    std::size_t copy=0;const auto model=remaining24_model(partner.get("model"),partner.get_string("model_sha256"),work,&copy);const auto allowance=work.remaining;ASSERT_NE(wide,ordinary)<<"Complete Config38 partner is mandatory positive";
    const auto large=validate(wide,model,allowance);first19_no_resource_rejection(large);ASSERT_TRUE(large.empty())<<(large.empty()?std::string{}:large.front());if(narrow!=small){const auto errors=validate(narrow,model,allowance);first19_no_resource_rejection(errors);ASSERT_TRUE(errors.empty())<<(errors.empty()?std::string{}:errors.front());}
    const auto changes=description77_fixed_mutations(wide,model,copy);EXPECT_TRUE(changes.errors.empty())<<(changes.errors.empty()?std::string{}:changes.errors.front());
}
