    const auto docs=config110_documents();std::set<std::string_view> selected;int note_sources=0;
    for(const auto& pin:kConfig38Pins){SCOPED_TRACE(std::string(pin.id));try{Work work;work.spend(pin.id.size()+64);official_role38_require(selected.insert(pin.id).second,"Config38 duplicate selected source");const auto item=docs.facts.root().get("cases").at(pin.ordinal);config110_binding(item,docs.manifest.root(),work);config38_pin_binding(item,pin,work);static_cast<void>(remaining24_model(item.get("model"),item.get_string("model_sha256"),work));note_sources+=pin.note_alignment>=0;}catch(const std::exception& error){ADD_FAILURE()<<error.what();}}
