TEST(MermaidConfig38Native, FiniteCssGrammarConsumesWholeSourceBeyondOriginalColorPayloads) {
    Work setup;setup.spend(kConfig38CssBoundarySources.size()*3+256);
    const auto cases=json::parse(kConfig38CssBoundarySources);ASSERT_TRUE(cases);ASSERT_EQ(cases->root().size(),13u);
    int visited=0,positive=0,closed=0;
    cases->root().iter([&](JsonVal item) {
        ++visited;SCOPED_TRACE(item.get_string("name"));
        if(item.get_string("expected")=="whole_scene")++positive;else ++closed;
        try {config38_public_partner(item);}
        catch(const std::exception& error) {ADD_FAILURE()<<error.what();}
    });
    EXPECT_EQ(visited,13);EXPECT_EQ(positive,3);EXPECT_EQ(closed,10);
}
TEST(MermaidConfig38Native, NewTypedLeavesKeepNumericBooleanEnumAndNamespaceBoundaries) {
    Work setup;setup.spend(kConfig38TypedBoundarySources.size()*3+256);
    const auto cases=json::parse(kConfig38TypedBoundarySources);ASSERT_TRUE(cases);ASSERT_EQ(cases->root().size(),18u);
    int visited=0,positive=0,closed=0;
    cases->root().iter([&](JsonVal item) {
        ++visited;SCOPED_TRACE(item.get_string("name"));
        if(item.get_string("expected")=="whole_scene")++positive;else ++closed;
        try {config38_public_partner(item);}
        catch(const std::exception& error) {ADD_FAILURE()<<error.what();}
    });
    EXPECT_EQ(visited,18);EXPECT_EQ(positive,2);EXPECT_EQ(closed,16);
}
