namespace {
// Future source-backed migration only after the original first-red is frozen.
// The old body assertions remain in their existing TEST; this owns only the
// ten exact raw applications, using the immutable complete raw Model/hint.
struct Config38LegacyRaw {std::string_view path;std::size_t ordinal;};
constexpr std::array<Config38LegacyRaw,10> kConfig38LegacyRaw{{
    {"sequence/nightly-check/should-render-different-note-fonts-when-configured.mmd",54},
    {"sequence/nightly-check/should-render-multi-line-notes-aligned-to-the-left-when-configured.mmd",61},
    {"sequence/nightly-check/should-render-multi-line-notes-aligned-to-the-right-when-configured.mmd",62},
    {"sequence/nightly-check/should-render-notes-aligned-to-the-left-when-configured.mmd",63},
    {"sequence/nightly-check/should-render-notes-aligned-to-the-right-when-configured.mmd",64},
    {"sequence/nightly-check/should-render-alt-else-section-titles-with-label-box-backgrounds.mmd",28},
    {"sequence/nightly-check/should-render-autonumber-when-configured-with-such.mmd",29},
    {"sequence/visual-check/usemaxwidth-false.mmd",105},
    {"sequence/visual-check/usemaxwidth-true.mmd",106},
    {"sequence/visual-check/with-boxes.mmd",109},
}};
bool config38_legacy_raw(std::string_view path,std::string_view source) {
    Work identity;
    const Config38LegacyRaw* selected=nullptr;
    for(const auto& application:kConfig38LegacyRaw) {
        identity.spend(path.size()+application.path.size()+8);
        if(path!=application.path)continue;
        official_role38_require(!selected,"Config38 legacy exact raw path selected once");
        selected=&application;
    }
    if(!selected)return false;
    // Existing config110_documents owns its unchanged bounded immutable setup.
    // Identity/pin assertions are separate from config110_public's one source
    // ledger, whose capture/binding/codec/hint/geometry remainder stays intact.
    const auto docs=config110_documents();
    const auto item=docs.facts.root().get("cases").at(selected->ordinal);
    identity.spend(path.size()*4+source.size()*4+256);
    official_role38_require(item.get("path").as_str()==path&&item.get("input").as_str()==source,
                            "Config38 legacy whole raw source and path");
    const Config38Pin* reviewed=nullptr;
    for(const auto& pin:kConfig38Pins) {
        identity.spend();
        if(pin.ordinal!=selected->ordinal)continue;
        official_role38_require(!reviewed,"Config38 legacy source pin selected once");reviewed=&pin;
    }
    official_role38_require(reviewed!=nullptr,"Config38 legacy belongs to reviewed38");
    config38_pin_binding(item,*reviewed,identity);
    std::optional<NoteAlignment> alignment;
    if(reviewed->note_alignment>=0)alignment=static_cast<NoteAlignment>(reviewed->note_alignment);
    json::JsonMutDoc observations;auto root=observations.object(),rows=root.make_arr();
    const auto result=config110_public(item,docs.manifest.root(),root,rows,alignment?&*alignment:nullptr);
    for(const auto& error:result.errors)ADD_FAILURE()<<error;
    for(const auto& error:result.observations)ADD_FAILURE()<<error;
    EXPECT_TRUE(result.observed&&result.decoded&&result.ready&&!result.pending&&!result.fallback&&
                result.matched&&result.errors.empty()&&result.observations.empty())
        <<"Complete configured RAW Model, owned Note alignment, geometry and mutations are mandatory: "<<path;
    EXPECT_EQ(rows.size(),1u);
    // true means this exact known input was fully asserted, not that a failed
    // assertion passed. Returning false would wrongly rerun an obsolete fallback.
    return true;
}
} // namespace


