void config8ab33_span(JsonVal item,JsonVal value,int expected_line,Work& work) {
    config110_keys(value,{"line","offset_utf8_bytes","bytes","sha256"},work);
    official_role38_require(value.get("line").is_int()&&value.get_int("line")==expected_line,
        "Config8ab33 protocol: declaration physical line");
    const auto lines=item.get("raw_physical_lines");
    official_role38_require(lines.is_arr()&&expected_line>0&&static_cast<std::size_t>(expected_line)<=lines.size(),
        "Config8ab33 protocol: physical span domain");
    const auto line=lines.at(static_cast<std::size_t>(expected_line-1));
    official_role38_require(value.get("offset_utf8_bytes").is_int()&&value.get("bytes").is_int()&&
        value.get_int("offset_utf8_bytes")==line.get_int("offset_utf8_bytes")&&value.get_int("bytes")==line.get_int("bytes")&&
        value.get("sha256").is_str()&&value.get("sha256").as_str()==line.get("sha256").as_str(),
        "Config8ab33 protocol: physical span tuple");
    const auto raw=item.get("input").as_str();const auto offset=value.get_int("offset_utf8_bytes"),length=value.get_int("bytes");
    official_role38_require(offset>=0&&length>0&&static_cast<std::uint64_t>(offset)<=raw.size()&&
        static_cast<std::uint64_t>(length)<=raw.size()-static_cast<std::size_t>(offset),
        "Config8ab33 protocol: physical span bounds");
    work.spend(static_cast<std::size_t>(length)*2u+64u);
    official_role38_require(loom::utils::crypto::sha256(raw.substr(static_cast<std::size_t>(offset),static_cast<std::size_t>(length)))==value.get("sha256").as_str(),
        "Config8ab33 protocol: physical span source");
}
// Called only after config110_binding has consumed the complete immutable row.
// The default-null public path never enters this supplementary source protocol.
void config8ab33_binding(JsonVal item,JsonVal supplement,Work& work) {
    official_role38_require(item.get("profile").as_str()=="pending"&&item.get("model").is_null()&&
        item.get("model_sha256").is_null()&&item.get("number_encoding").is_null(),
        "Config8ab33 protocol: supplement requires original pending null row");
    config110_keys(supplement,{"schema","kind","source_review_sha256","role_source_proposal_sha256","source_binding","model","model_sha256","declarations","destroy_maps","creating_receivers","logical_guard_after_signals","number_encoding"},work);
    official_role38_require(supplement.get("schema").is_int()&&supplement.get_int("schema")==1&&
        supplement.get("kind").as_str()=="config110_masked_destroy_native_supplement/v1"&&
        supplement.get("number_encoding").as_str()=="DisplayText"&&
        supplement.get("source_review_sha256").as_str()=="7f819194fb862dd0f62c9449f86e8ecd3c5f6cb0e607c46357608416c177c5d3"&&
        supplement.get("role_source_proposal_sha256").as_str()=="8e8a5ac892f0f8cfc6e3ff63676e629982e920784b4f7cdd12f0aa5e7584be98",
        "Config8ab33 protocol: reviewed source schema");
    const auto binding=supplement.get("source_binding");
    config110_keys(binding,{"id","ordinal","original116_ordinal","path","input_sha256","body_offset_utf8_bytes","body_sha256","original_row_canonical_sha256"},work);
    official_role38_require(binding.get("ordinal").is_int()&&binding.get_int("ordinal")==99&&
        binding.get("original116_ordinal").is_int()&&binding.get_int("original116_ordinal")==103&&
        binding.get("body_offset_utf8_bytes").is_int()&&binding.get_int("body_offset_utf8_bytes")==268&&
        binding.get("id").as_str()=="official-raw-sequence/8ab33aac13881555"&&
        binding.get("path").as_str()=="sequence/nightly-check/v2-classic-participant-creation-and-destruction.mmd"&&
        binding.get("input_sha256").as_str()=="8ab33aac1388155585c1d7f386c029a65b82b0f94b4d956950e0098f94dfcdad"&&
        binding.get("body_sha256").as_str()=="acf8179406d9fbcfaaceb09f5d728b552838d7d61a14d2f25583b78800fad74e"&&
        binding.get("original_row_canonical_sha256").as_str()==kConfig8abRowSha,
        "Config8ab33 protocol: unique reviewed raw source tuple");
    for(const auto key:{"id","path","input_sha256","body_sha256"}){
        work.spend(binding.get(key).as_str().size()+1u);
        official_role38_require(item.get(key).is_str()&&item.get(key).as_str()==binding.get(key).as_str(),
            "Config8ab33 protocol: supplement bound to another source");
    }
    official_role38_require(item.get("ordinal").is_int()&&item.get_int("ordinal")==99&&
        item.get("original116_ordinal").is_int()&&item.get_int("original116_ordinal")==103&&
        item.get("body_offset_utf8_bytes").is_int()&&item.get_int("body_offset_utf8_bytes")==268,
        "Config8ab33 protocol: supplement original ordinals");
    official_role38_require(loom::utils::crypto::sha256(joined683_canonical(item,work))==kConfig8abRowSha,
        "Config8ab33 protocol: entire original null dictionary");
    official_role38_require(supplement.get("model_sha256").is_str()&&supplement.get("model_sha256").as_str()==kConfig8abModelSha&&
        loom::utils::crypto::sha256(joined683_canonical(supplement.get("model"),work))==kConfig8abModelSha,
        "Config8ab33 protocol: complete independently corrected Model");
    const auto declarations=supplement.get("declarations");
    official_role38_require(declarations.is_arr()&&declarations.size()==kConfig8abDeclarations.size(),
        "Config8ab33 protocol: all 24 original declarations");
    int early=0,creating=0;
    for(std::size_t n=0;n<kConfig8abDeclarations.size();++n){
        work.spend(64);const auto value=declarations.at(n);const auto& expected=kConfig8abDeclarations[n];
        config110_keys(value,{"line","id","authored_type","description","early_return","creating","span"},work);
        official_role38_require(value.get("line").is_int()&&value.get_int("line")==expected.line&&
            value.get("id").is_str()&&value.get("id").as_str()==expected.id&&
            value.get("authored_type").is_str()&&value.get("authored_type").as_str()==expected.authored&&
            value.get("description").is_null()&&value.get("early_return").is_bool()&&value.get("early_return").as_bool()==expected.early&&
            value.get("creating").is_bool()&&value.get("creating").as_bool()==expected.creating,
            "Config8ab33 protocol: null-description role ownership");
        config8ab33_span(item,value.get("span"),expected.line,work);early+=expected.early;creating+=expected.creating;
    }
    official_role38_require(early==14&&creating==8,"Config8ab33 protocol: initial role and creating counts");
    const auto destroyed=supplement.get("destroy_maps");
    official_role38_require(destroyed.is_arr()&&destroyed.size()==4,"Config8ab33 protocol: four destroy declarations retained");
    for(std::size_t n=0;n<4;++n){
        const auto value=destroyed.at(n);work.spend(64);
        config110_keys(value,{"actor","message_index","created_receiver","span"},work);
        official_role38_require(value.get("actor").is_str()&&value.get("actor").as_str()==kConfig8abDestroy[n].second&&
            value.get("message_index").is_int()&&value.get_int("message_index")==static_cast<std::int64_t>(2*n+1)&&
            value.get("created_receiver").is_str()&&value.get("created_receiver").as_str()==kConfig8abReceivers[2*n+1],
            "Config8ab33 protocol: indexed destroy map source ownership");
        config8ab33_span(item,value.get("span"),kConfig8abDestroy[n].first,work);
    }
    const auto receivers=supplement.get("creating_receivers"),logical=supplement.get("logical_guard_after_signals");
    official_role38_require(receivers.is_arr()&&logical.is_arr()&&receivers.size()==8&&logical.size()==8,
        "Config8ab33 protocol: eight complete signal witnesses");
    for(std::size_t n=0;n<8;++n){
        work.spend(64);official_role38_require(receivers.at(n).is_str()&&receivers.at(n).as_str()==kConfig8abReceivers[n],
            "Config8ab33 protocol: creating receiver priority");
        official_role38_require(kConfig8abLogicalAfter[n].empty()?logical.at(n).is_null():
            logical.at(n).is_str()&&logical.at(n).as_str()==kConfig8abLogicalAfter[n],
            "Config8ab33 protocol: masked logical destroy guard");
    }
}
Config8abDocuments config8ab33_documents(){
    Work setup;auto originals=config110_documents(&setup);
    const auto supplement_bytes=joined683_fixture(kConfig8abSupplementPath,kConfig8abSupplementSha,setup);
    const auto partner_bytes=joined683_fixture(kConfig8abPartnerPath,kConfig8abPartnersSha,setup);
    auto supplement=json::parse(supplement_bytes);auto partners=json::parse(partner_bytes);
    official_role38_require(supplement.has_value()&&partners.has_value()&&partners->root().is_arr()&&partners->root().size()==8,
        "Config8ab33 immutable supplementary documents parse");
    setup.spend(512);
    return {std::move(originals),std::move(*supplement),std::move(*partners),setup.remaining};
}

TEST(MermaidConfig110LifetimeSupplement, WholeNullSourceAndAllLogicalDeclarationsBindToTheCorrectedModel){
    const auto docs=config8ab33_documents();const auto item=docs.originals.facts.root().get("cases").at(99);const auto supplement=docs.supplement.root();
    ASSERT_GT(docs.setup_remaining,0u);Work work;config110_binding(item,docs.originals.manifest.root(),work);config8ab33_binding(item,supplement,work);
    const auto model=remaining24_model(supplement.get("model"),kConfig8abModelSha,work);
    EXPECT_EQ(model.actors.size(),10u);EXPECT_EQ(model.messages.size(),8u);EXPECT_EQ(model.order.size(),16u);
    EXPECT_EQ(model.actors[0].role,Role::Participant);EXPECT_EQ(model.actors[1].role,Role::Participant);
    int creates=0,destroys=0;for(const auto& event:model.order){work.spend();creates+=event.kind==EventKind::Create;destroys+=event.kind==EventKind::Destroy;}EXPECT_EQ(creates,8);EXPECT_EQ(destroys,0);
    auto bad=[&](auto change,std::string_view diagnostic){
        Work proof;const auto encoded=joined683_canonical(supplement,proof);proof.spend(encoded.size()*8u+4096u);
        json::JsonMutDoc mutation;auto value=mutation.copy_val(supplement);change(value,mutation,proof);mutation.set_root(value);
        const auto bytes=mutation.to_string();proof.spend(bytes.size()*3u+64u);
        // Refresh the outer digest, then invoke the specific parsed guard.
        EXPECT_EQ(loom::utils::crypto::sha256(bytes).size(),64u);const auto parsed=json::parse(bytes);ASSERT_TRUE(parsed);
        bool rejected=false;try{config8ab33_binding(item,parsed->root(),proof);}catch(const std::runtime_error& error){first19_no_resource_rejection({error.what()});rejected=true;EXPECT_NE(std::string_view(error.what()).find(diagnostic),std::string_view::npos)<<error.what();}EXPECT_TRUE(rejected)<<diagnostic;
    };
    bad([](auto value,auto&,auto&){value.set("schema",2);},"reviewed source schema");
    bad([](auto value,auto&,auto&){value.set("unknown",true);},"object field count");
    bad([](auto value,auto&,auto&){value.get("source_binding").set("ordinal",98);},"unique reviewed raw source tuple");
    bad([](auto value,auto&,auto&){value.get("model").get("actors").at(0).set("role","Queue");},"complete independently corrected Model");
    bad([](auto value,auto&,auto&){value.get("declarations").at(3).set("early_return",false);},"null-description role ownership");
    bad([](auto value,auto&,auto&){value.get("declarations").at(0).get("span").set("line",11);},"declaration physical line");
    bad([](auto value,auto&,auto&){value.get("declarations").at(0).get("span").set("offset_utf8_bytes",0);},"physical span tuple");
    bad([](auto value,auto&,auto&){value.get("destroy_maps").at(0).set("actor","A");},"indexed destroy map source ownership");
    bad([](auto value,auto&,auto&){value.get("destroy_maps").at(0).set("message_index",0);},"indexed destroy map source ownership");
    bad([](auto value,auto&,auto&){auto replacement=value.make_arr();value.get("creating_receivers").iter([&](auto old,std::size_t n){replacement.append(value.make_str(n==1?std::string_view("participant0"):old.as_str()));});value.add("creating_receivers",replacement);},"creating receiver priority");
    bad([](auto value,auto&,auto&){auto replacement=value.make_arr();value.get("logical_guard_after_signals").iter([&](auto old,std::size_t n){replacement.append(n==1||old.is_null()?value.make_null():value.make_str(old.as_str()));});value.add("logical_guard_after_signals",replacement);},"masked logical destroy guard");
    bad([](auto value,auto&,auto&){value.add("destroy_maps",value.make_arr());},"four destroy declarations retained");
    bad([](auto value,auto&,auto&){value.add("declarations",value.make_arr());},"all 24 original declarations");
    for(const auto profile:{"fixed","source_wrap"}){
        Work proof;const auto encoded=joined683_canonical(item,proof);proof.spend(encoded.size()*8u+4096u);json::JsonMutDoc mutation;auto value=mutation.copy_val(item);value.set("profile",profile);mutation.set_root(value);const auto bytes=mutation.to_string();proof.spend(bytes.size()*3u+64u);const auto parsed=json::parse(bytes);ASSERT_TRUE(parsed);
        bool rejected=false;try{config8ab33_binding(parsed->root(),supplement,proof);}catch(const std::runtime_error& error){first19_no_resource_rejection({error.what()});rejected=true;EXPECT_NE(std::string_view(error.what()).find("original pending null row"),std::string_view::npos);}EXPECT_TRUE(rejected);
    }
    {Work proof;const auto encoded=joined683_canonical(item,proof);proof.spend(encoded.size()*8u+4096u);json::JsonMutDoc mutation;auto value=mutation.copy_val(item);value.set("id","official-raw-sequence/wrong");mutation.set_root(value);const auto bytes=mutation.to_string();proof.spend(bytes.size()*3u+64u);const auto parsed=json::parse(bytes);ASSERT_TRUE(parsed);bool rejected=false;try{config8ab33_binding(parsed->root(),supplement,proof);}catch(const std::runtime_error& error){first19_no_resource_rejection({error.what()});rejected=true;EXPECT_NE(std::string_view(error.what()).find("another source"),std::string_view::npos);}EXPECT_TRUE(rejected);}
    Work exhausted;exhausted.remaining=0;EXPECT_THROW(config8ab33_binding(item,supplement,exhausted),std::runtime_error);
}

Grid config8ab33_paper(int which,Work& work){
    official_role38_require(which>=0&&which<5,"Config8ab33 paper selector");
    work.spend(80u*38u*64u+1024u);Grid good{80,38,std::vector<std::string>(80u*38u," ")};
    if(which==4){
        // Independently authored whole no-Death EOF paper; these literal cells
        // match the source-only paper asset, with no message or borrowed cap.
        good.text(5,4,"┌─────┐");good.text(5,5,"│ A   │");good.text(5,6,"└─────┘");
        good.text(33,4,"┌─────┐");good.text(33,5,"│ D   │");good.text(33,6,"└─────┘");
        for(int y=7;y<=32;++y){good.put(8,y,"│");good.put(36,y,"│");}
    }else if(which<2){
        role_stage2_hand_header(good,5,4,"A");role_stage2_hand_header(good,33,4,"B");
        if(which==1)role_stage2_hand_figure(good,Role::Queue,8,4);
        for(int y=7;y<=32;++y){good.put(8,y,"│");good.put(36,y,"│");}
        good.text(10,13,"ping");good.put(8,14,"├");for(int x=9;x<36;++x)good.put(x,14,"─");good.put(36,14,"▶");
    }else{
        for(const auto& [x,label]:std::array<std::pair<int,const char*>,3>{{{8,"A"},{36,"D"},{64,"C"}}})role_stage2_hand_header(good,x-3,4,label);
        for(int y=7;y<=32;++y){good.put(8,y,"│");good.put(36,y,"│");}
        for(int y=12;y<=32;++y)good.put(64,y,"│");
        good.text(10,13,"born");good.put(8,14,"├");for(int x=9;x<64;++x)good.put(x,14,"─");good.put(36,14,"┼");good.put(64,14,"▶");
        if(which==3){
            good.text(10,21,"alive");good.put(8,22,"◀");for(int x=9;x<36;++x)good.put(x,22,"─");good.put(36,22,"┤");
            good.put(36,24,"×");for(int y=25;y<=32;++y)good.put(36,y," ");
        }
    }
    good.text(0,36,kSentinel);return good;
}
void config8ab33_rejected(const std::vector<std::string>& errors){
    first19_no_resource_rejection(errors);EXPECT_FALSE(errors.empty())<<"Accepted Config8ab33 observable geometry adversary";
}
TEST(MermaidConfig110LifetimeSupplement, IndependentWholePapersAndAllLogicalPublicPartnersMustMatch){
    const auto docs=config8ab33_documents();const std::array<std::size_t,5> partners{{0,1,3,4,7}};int papers=0;
    for(int n=0;n<5;++n){SCOPED_TRACE(n);try{
        Work work;const auto partner=docs.partners.root().at(partners[static_cast<std::size_t>(n)]);std::size_t copied=0;
        const auto model=remaining24_model(partner.get("model"),partner.get_string("model_sha256"),work,&copied);const auto good=config8ab33_paper(n,work);const auto allowance=work.remaining;
        const auto errors=validate(good,model,allowance);first19_no_resource_rejection(errors);EXPECT_TRUE(errors.empty())<<(errors.empty()?std::string{}:errors.front());
        if(!errors.empty()){continue;}
        ++papers;
        auto model_bad=[&](auto change){Work adversary;adversary.spend(copied);auto wrong=model;change(wrong);check_event_model(wrong,adversary);config8ab33_rejected(validate(good,wrong,adversary.remaining));};
        model_bad([&](Model& wrong){wrong.actors[0].role=n==1?Role::Participant:Role::Queue;});
        if(n<4){
            model_bad([](Model& wrong){wrong.messages[0].label="wrong";});
            model_bad([](Model& wrong){wrong.messages[0].arrow=Arrow::Unheaded;});
        }else{
            model_bad([](Model& wrong){wrong.actors[1].label="Wrong";});
            model_bad([](Model& wrong){wrong.messages.push_back({0,1,"phantom",false});wrong.order.push_back({EventKind::Message,0});});
        }
        if(n==2||n==3)model_bad([](Model& wrong){wrong.order.erase(wrong.order.begin());});
        if(n==3)model_bad([](Model& wrong){wrong.order.pop_back();});
        auto pixel_bad=[&](int x,int y,std::string_view replacement){Work adversary;adversary.spend(good.cells.size()*64u+copied+256u);auto wrong=good;wrong.put(x,y,std::string(replacement));config8ab33_rejected(validate(wrong,model,adversary.remaining));};
        if(n<4)pixel_bad(15,14," ");else{
            pixel_bad(5,4," ");pixel_bad(8,15," ");pixel_bad(36,24,"×");
        }
        pixel_bad(77,29,"x");
        if(n==2||n==3)pixel_bad(64,8,"│");
        if(n==3){pixel_bad(36,24," ");pixel_bad(36,25,"│");}
        if(n==1)pixel_bad(8,1," ");
        EXPECT_TRUE(complete_sequence_sentinel(good));const auto zero=validate(good,model,0);EXPECT_TRUE(std::ranges::any_of(zero,[](const auto& error){return termaid47_resource(error);}));
    }catch(const std::exception& error){ADD_FAILURE()<<"Whole paper oracle error: "<<error.what();}}
    EXPECT_EQ(papers,5);
    int attempted=0,positive=0,closed=0;
    docs.partners.root().iter([&](JsonVal partner){++attempted;SCOPED_TRACE(partner.get_string("name"));if(partner.get_string("expected")=="whole_scene")++positive;else ++closed;try{
        // Reuse Config38's paid whole-public-source composition and exact decoder;
        // no fake manifest adapter or independently reset hand_matches path.
        config38_public_partner(partner);
    }catch(const std::exception& error){ADD_FAILURE()<<"Public partner observation/oracle error: "<<error.what();}});
    EXPECT_EQ(attempted,8);EXPECT_EQ(positive,7);EXPECT_EQ(closed,1);
}

