json::JsonDoc config8ab_terminal_controls(){
    Work setup;
    const auto bytes=joined683_fixture(kConfig8abTerminalControlsPath,kConfig8abTerminalControlsSha,setup);
    auto parsed=json::parse(bytes);
    official_role38_require(parsed.has_value(),"Config8ab terminal controls immutable parse");
    const auto root=parsed->root();
    config110_keys(root,{"schema","terminal_source_contract_sha256","original_partner_sources_asset_sha256","counts","cases"},setup);
    official_role38_require(root.get("schema").is_int()&&root.get_int("schema")==1&&
        root.get("terminal_source_contract_sha256").is_str()&&root.get_string("terminal_source_contract_sha256")=="d7ffa151d6c55bb3083771c40b09e74c076b9e91d0f05df34de1ebaa20e2bb7a"&&
        root.get("original_partner_sources_asset_sha256").is_str()&&root.get_string("original_partner_sources_asset_sha256")=="365aabfbb8cec29dab78039bb870a1b9431385009799b39fe75ec80ffb86e865",
        "Config8ab terminal controls reviewed source contract");
    const auto counts=root.get("counts");
    config110_keys(counts,{"cases","whole_scene","whole_source","new_declaration_boundaries","existing_own_control_migrations"},setup);
    for(const auto& [key,wanted]:std::array<std::pair<std::string_view,int>,5>{{
        {"cases",13},{"whole_scene",12},{"whole_source",1},{"new_declaration_boundaries",8},{"existing_own_control_migrations",5}}}){
        setup.spend();
        official_role38_require(counts.get(key).is_int()&&counts.get(key).as_int()==wanted,
            "Config8ab terminal controls exact counts");
    }
    const auto cases=root.get("cases");
    official_role38_require(cases.is_arr()&&cases.size()==kConfig8abTerminalControlPins.size(),
        "Config8ab terminal controls complete source inventory");
    for(std::size_t n=0;n<kConfig8abTerminalControlPins.size();++n){
        const auto value=cases.at(n);const auto& pin=kConfig8abTerminalControlPins[n];
        config110_keys(value,{"name","source","source_sha256","expected","model","model_sha256","origin","source_authority_case_sha256"},setup);
        for(const auto key:{"name","source","source_sha256","expected","origin","source_authority_case_sha256"})
            official_role38_require(value.get(key).is_str(),"Config8ab terminal controls string protocol");
        const auto source=value.get("source").as_str();
        official_role38_require(!source.empty()&&source.size()<=65536,"Config8ab terminal controls whole source bound");
        setup.spend(source.size()*2u+pin.name.size()+pin.origin.size()+320u);
        official_role38_require(value.get_string("name")==pin.name&&value.get_string("expected")==pin.expected&&
            value.get_string("origin")==pin.origin&&value.get_string("source_authority_case_sha256")==pin.authority_sha&&
            value.get_string("source_sha256")==pin.source_sha&&loom::utils::crypto::sha256(source)==pin.source_sha,
            "Config8ab terminal controls exact source and authority");
        if(pin.model_sha.empty()){
            official_role38_require(pin.expected=="whole_source_closed_profile"&&value.get("model").is_null()&&value.get("model_sha256").is_null(),
                "Config8ab terminal controls explicit box conflict");
        }else{
            official_role38_require(pin.expected=="whole_scene"&&value.get("model").is_obj()&&value.get("model_sha256").is_str()&&
                value.get_string("model_sha256")==pin.model_sha&&
                loom::utils::crypto::sha256(joined683_canonical(value.get("model"),setup))==pin.model_sha,
                "Config8ab terminal controls complete reviewed Model");
        }
    }
    // Source-integrity checking above is not Model decoding or geometry. The
    // existing public helper captures each complete source before strict decode.
    return std::move(*parsed);
}
