TEST(MermaidSequenceTerminalV2WrapReplacement, WholeScenesKeepClearedRetainedAndIndependentWrappedOwners) {
    Work setup;
    setup.spend(kWrapReplacementControls.size() * 3 + 64);
    ASSERT_EQ(loom::utils::crypto::sha256(kWrapReplacementControls), kWrapReplacementControlsSha);
    const auto document = json::parse(kWrapReplacementControls);
    ASSERT_TRUE(document);
    ASSERT_TRUE(document->root().is_arr());
    ASSERT_EQ(document->root().size(), 3u);
    int visited = 0, matched = 0;
    document->root().iter([&](JsonVal row) {
        ++visited;
        Work source_work;
        const auto name = row.get("name");
        ASSERT_TRUE(name.is_str());
        source_work.spend(name.as_str().size() * 4 + 64);
        SCOPED_TRACE(std::string(name.as_str()));
        const auto source = row.get("source");
        ASSERT_TRUE(source.is_str());
        // Borrow the owned document through the complete synchronous call.
        // The helper charges source/capture/canonical/codec/plan against this
        // same ledger, and observes all three widths before typed decoding.
        matched += wrap227_migrated_public(source.as_str(), &row, &source_work);
    });
    EXPECT_EQ(visited, 3);
    EXPECT_EQ(matched, 3);
}
