struct Body22Documents {
    json::JsonDoc refs, description, config, supplement;
};

Body22Documents body22_documents(Work& setup) {
    auto load = [&](std::string_view path, std::string_view sha, std::size_t size) {
        official_role38_require(std::filesystem::file_size(std::filesystem::path(LOOM_TESTS_DIR) /
                                                           "fixtures" / path) == size,
                                "Body22 immutable authority size");
        const auto bytes = joined683_fixture(path, sha, setup);
        auto parsed = json::parse(bytes);
        official_role38_require(parsed.has_value(), "Body22 immutable authority JSON");
        return std::move(*parsed);
    };
    auto refs = load(kBody22Path, kBody22Sha, 40076);
    auto description = load(kDescription77FactsPath, kDescription77FactsSha, 1211414);
    auto config = load(kConfig110Path, kConfig110Sha, 1161434);
    auto supplement = load(kConfig8abSupplementPath, kConfig8abSupplementSha, 15064);
    const auto root = refs.root();
    config110_keys(
        root, {"schema", "qualification", "immutable_manifest_sha256", "whole_body_count", "cases"},
        setup);
    official_role38_require(
        root.get("schema").is_str() &&
            root.get("schema").as_str() ==
                "official_sequence_body22_authority_references/proposed-v1" &&
            root.get("immutable_manifest_sha256").is_str() &&
            root.get("immutable_manifest_sha256").as_str() == kOfficialRole38ManifestSha &&
            root.get("whole_body_count").is_int() && root.get_int("whole_body_count") == 22 &&
            root.get("cases").is_arr() && root.get("cases").size() == 22,
        "Body22 closed source denominator");
    official_role38_require(
        description.root().get("cases").is_arr() && description.root().get("cases").size() == 77 &&
            config.root().get("cases").is_arr() && config.root().get("cases").size() == 110,
        "Body22 exact original authority denominators");
    setup.spend(2048u);  // Fixed document views and eventual report root metadata.
    return {std::move(refs), std::move(description), std::move(config), std::move(supplement)};
}

struct Body22Views {
    JsonVal raw, model;
};

Body22Views body22_views(const Body22Documents& docs, const Body22Pin& pin, Work& work) {
    work.spend(64u);
    const auto raw = pin.kind == 0 ? docs.description.root().get("cases").at(pin.ordinal)
                                   : docs.config.root().get("cases").at(pin.ordinal);
    return {raw, pin.kind == 2 ? docs.supplement.root().get("model") : raw.get("model")};
}

void body22_binding(JsonVal item, JsonVal raw, JsonVal meaning, const Body22Pin& pin, Work& work) {
    config110_keys(item,
                   {"baseline_expectation_canonical_sha256", "body_offset_utf8_bytes", "id",
                    "input", "input_sha256", "input_utf8_bytes", "model_authority", "model_schema",
                    "model_sha256", "number_encoding", "path", "profile", "source_note_alignment",
                    "source_rect_constraints", "track", "whole_raw_sha256"},
                   work);
    for (const auto key : {"id", "input", "input_sha256", "whole_raw_sha256", "path", "track",
                           "profile", "model_schema", "model_sha256", "number_encoding",
                           "baseline_expectation_canonical_sha256"})
        official_role38_require(item.get(key).is_str(), "Body22 exact source scalar type");
    const auto source = item.get("input").as_str();
    official_role38_require(!source.empty() && source.size() <= 65536,
                            "Body22 whole body source cap");
    work.spend(source.size() * 8 + pin.path.size() * 8 + 2048);
    official_role38_require(item.get("path").as_str() == pin.path &&
                                item.get("track").as_str() == "body_diagnostic",
                            "Body22 original body path/track");
    official_role38_require(item.get("input_sha256").as_str() == pin.body_sha &&
                                loom::utils::crypto::sha256(source) == pin.body_sha &&
                                item.get("input_utf8_bytes").is_int() &&
                                item.get_int("input_utf8_bytes") ==
                                    static_cast<std::int64_t>(source.size()),
                            "Body22 complete body identity");
    work.spend(pin.body_sha.size() + 32);
    const auto expected_id = "official-body22/" + std::string(pin.body_sha);
    official_role38_require(item.get("id").as_str() == expected_id,
                            "Body22 original application identity");
    official_role38_require(item.get("whole_raw_sha256").as_str() == pin.raw_sha &&
                                raw.get("path").is_str() && raw.get("path").as_str() == pin.path &&
                                raw.get("input").is_str() && raw.get("input_sha256").is_str() &&
                                raw.get("input_sha256").as_str() == pin.raw_sha,
                            "Body22 same complete raw authority");
    const auto whole = raw.get("input").as_str();
    work.spend(whole.size() * 8 + 128);
    official_role38_require(whole.size() <= 65536 &&
                                loom::utils::crypto::sha256(whole) == pin.raw_sha,
                            "Body22 complete authority raw digest");
    official_role38_require(item.get("body_offset_utf8_bytes").is_int() &&
                                item.get_int("body_offset_utf8_bytes") == pin.offset &&
                                raw.get("body_offset_utf8_bytes").is_int() &&
                                raw.get_int("body_offset_utf8_bytes") == pin.offset &&
                                static_cast<std::size_t>(pin.offset) <= whole.size() &&
                                whole.substr(static_cast<std::size_t>(pin.offset)) == source &&
                                raw.get("body_sha256").is_str() &&
                                raw.get("body_sha256").as_str() == pin.body_sha,
                            "Body22 entire same-body suffix, all directives retained");
    description77_physical(raw.get("raw_physical_lines"), whole, work);
    work.spend(whole.size() * 3 + pin.path.size() + 64);
    official_role38_require(fixture_bytes("mermaid_official/cases/" + std::string(pin.path)) ==
                                whole,
                            "Body22 original physical whole raw source");
    const auto original = raw.get("original_manifest_record"), diag = original.get("diagnostic");
    official_role38_require(
        original.get("path").is_str() && original.get("path").as_str() == pin.path &&
            original.get("sha256").is_str() && original.get("sha256").as_str() == pin.raw_sha &&
            diag.get("offset").is_int() && diag.get_int("offset") == pin.offset &&
            diag.get("sha256").is_str() && diag.get("sha256").as_str() == pin.body_sha,
        "Body22 complete original manifest tuple");
    official_role38_require(
        item.get("baseline_expectation_canonical_sha256").as_str() == pin.diagnostic_sha &&
            loom::utils::crypto::sha256(joined683_canonical(diag, work)) == pin.diagnostic_sha,
        "Body22 original diagnostic expectation dictionary");
    official_role38_require(item.get("number_encoding").as_str() == "DisplayText" &&
                                item.get("profile").as_str() ==
                                    (pin.wrap ? "source_wrap" : "fixed") &&
                                item.get("model_schema").as_str() ==
                                    (pin.wrap ? "sequence_native_source_wrap_number_text/v1"
                                              : "sequence_native_single_role_number_text/v1"),
                            "Body22 exact active profile and DisplayText codec");
    official_role38_require(item.get("source_note_alignment").is_null() &&
                                item.get("source_rect_constraints").is_arr() &&
                                item.get("source_rect_constraints").size() == 0,
                            "Body22 default same-chosen NoteRect constraints");
    const auto authority = item.get("model_authority");
    config110_keys(authority,
                   {"authority_file", "authority_file_sha256", "canonical_sha256",
                    "freeze_file_index", "json_pointer"},
                   work);
    const std::array<std::string_view, 3> files{
        {"tests/fixtures/mermaid_native/"
         "sequence_official_description77_par_over_admitted_facts.json",
         "tests/fixtures/mermaid_native/sequence_official_config110_facts.json",
         "tests/fixtures/mermaid_native/sequence_official_config110_lifetime_supplement.json"}};
    const std::array<std::string_view, 3> hashes{
        {kDescription77FactsSha, kConfig110Sha, kConfig8abSupplementSha}};
    official_role38_require(authority.get("authority_file").is_str() &&
                                authority.get("authority_file").as_str() ==
                                    files[static_cast<std::size_t>(pin.kind)] &&
                                authority.get("authority_file_sha256").is_str() &&
                                authority.get("authority_file_sha256").as_str() ==
                                    hashes[static_cast<std::size_t>(pin.kind)] &&
                                authority.get("json_pointer").is_str() &&
                                authority.get("json_pointer").as_str() == pin.pointer &&
                                authority.get("freeze_file_index").is_int() &&
                                authority.get_int("freeze_file_index") == pin.freeze,
                            "Body22 strict immutable Model authority pointer");
    official_role38_require(item.get("model_sha256").as_str() == pin.model_sha &&
                                authority.get("canonical_sha256").is_str() &&
                                authority.get("canonical_sha256").as_str() == pin.model_sha,
                            "Body22 same whole Model identity");
    if (pin.kind != 2)
        official_role38_require(raw.get("model_sha256").is_str() &&
                                    raw.get("model_sha256").as_str() == pin.model_sha &&
                                    raw.get("number_encoding").is_str() &&
                                    raw.get("number_encoding").as_str() == "DisplayText",
                                "Body22 original active authority Model/number encoding");
    else
        official_role38_require(raw.get("model").is_null() && raw.get("number_encoding").is_null(),
                                "Body22 historical null lineage stays null");
    official_role38_require(meaning.is_obj(), "Body22 complete Model object");
}

void body22_frame_report(const Grid& grid, std::string_view name, json::JsonMutVal row,
                         Work& work) {
    std::size_t bytes = 0;
    for (const auto& cell : grid.cells) {
        work.spend();
        if (bytes > work.remaining || cell.size() > work.remaining - bytes)
            throw std::runtime_error("Body22 frame text work exhausted");
        bytes += cell.size();
    }
    if (bytes > work.remaining / 6) throw std::runtime_error("Body22 frame copy work exhausted");
    // Row construction, JSON storage/escaping and physical hash payload/scan
    // share this prepayment. Per-cell length prefixes and row nodes are paid
    // separately; this also funds the final report serialization.
    work.spend(bytes * 6 + grid.cells.size() * 6 + static_cast<std::size_t>(grid.height) * 8 + 128);
    auto lines = row.make_arr();
    for (int y = 0; y < grid.height; ++y)
        lines.append(row.make_str(grid.row(y)));
    row.add(name, lines);
}

TEST(MermaidOfficialBody22Native,
     CompleteSourceAndActiveModelReferencesRetainAllTwentyTwoApplications) {
    Work setup;
    const auto docs = body22_documents(setup);
    std::set<std::string> paths;
    int wrap = 0, fixed = 0, supplements = 0, actors = 0, messages = 0, notes = 0, fragments = 0,
        boxes = 0, order = 0, numbered = 0;
    for (std::size_t n = 0; n < kBody22Pins.size(); ++n) {
        const auto& pin = kBody22Pins[n];
        setup.spend(pin.path.size() * 3 + 128);
        SCOPED_TRACE(std::string(pin.path));
        EXPECT_TRUE(paths.emplace(pin.path).second);
        try {
            Work work;
            const auto item = docs.refs.root().get("cases").at(n);
            const auto views = body22_views(docs, pin, work);
            body22_binding(item, views.raw, views.model, pin, work);
            if (pin.kind == 2) {
                config8ab33_binding(views.raw, docs.supplement.root(), work);
                ++supplements;
            }
            if (pin.wrap) {
                const auto encoded = joined683_canonical(views.model, work);
                official_role38_require(loom::utils::crypto::sha256(encoded) == pin.model_sha,
                                        "Body22 complete Label Model digest");
                const auto scene = wrap43_codec(views.model, work);
                check_event_model(scene.source, work);
                ++wrap;
            } else {
                static_cast<void>(remaining24_model(views.model, pin.model_sha, work));
                ++fixed;
            }
            actors += static_cast<int>(views.model.get("actors").size());
            messages += static_cast<int>(views.model.get("messages").size());
            notes += static_cast<int>(views.model.get("notes").size());
            fragments += static_cast<int>(views.model.get("fragments").size());
            boxes += static_cast<int>(views.model.get("boxes").size());
            order += static_cast<int>(views.model.get("order").size());
            views.model.get("messages").iter([&](JsonVal m) {
                work.spend();
                official_role38_require(m.get("number").is_str(),
                                        "Body22 all message numbers are exact text");
                numbered += !m.get("number").as_str().empty();
            });
        } catch (const std::exception& error) {
            ADD_FAILURE() << error.what();
        }
    }
    EXPECT_EQ(wrap, 17);
    EXPECT_EQ(fixed, 5);
    EXPECT_EQ(supplements, 1);
    EXPECT_EQ(actors, 64);
    EXPECT_EQ(messages, 176);
    EXPECT_EQ(notes, 32);
    EXPECT_EQ(fragments, 10);
    EXPECT_EQ(boxes, 0);
    EXPECT_EQ(order, 251);
    EXPECT_EQ(numbered, 119);
    const auto& pin = kBody22Pins.front();
    const auto item = docs.refs.root().get("cases").at(0);
    const auto views = body22_views(docs, pin, setup);
    auto reject = [&](std::string_view reason, auto change) {
        Work work;
        const auto encoded = joined683_canonical(item, work);
        work.spend(encoded.size() * 8 + 256);
        json::JsonMutDoc mutation;
        auto row = mutation.copy_val(item);
        change(row);
        mutation.set_root(row);
        const auto text = mutation.to_string();
        work.spend(text.size() * 3);
        const auto parsed = json::parse(text);
        ASSERT_TRUE(parsed);
        bool rejected = false;
        try {
            body22_binding(parsed->root(), views.raw, views.model, pin, work);
        } catch (const std::runtime_error& error) {
            if (termaid47_resource(error.what())) throw;
            rejected = std::string_view(error.what()) == reason;
        }
        EXPECT_TRUE(rejected) << reason;
    };
    reject("Config110 exact object field count", [](auto row) { row.set("unknown", true); });
    reject("Body22 original body path/track", [](auto row) { row.set("track", "original"); });
    reject("Body22 complete body identity",
           [](auto row) { row.set("input", "sequenceDiagram\nA->>B: wrong\n"); });
    reject("Body22 entire same-body suffix, all directives retained",
           [](auto row) { row.set("body_offset_utf8_bytes", 0); });
    reject("Body22 exact active profile and DisplayText codec",
           [](auto row) { row.set("number_encoding", "LegacyInteger"); });
    reject("Body22 default same-chosen NoteRect constraints",
           [](auto row) { row.set("source_note_alignment", "left"); });
    reject("Body22 strict immutable Model authority pointer",
           [](auto row) { row.get("model_authority").set("json_pointer", "/cases/9/model"); });
    reject("Body22 same whole Model identity",
           [](auto row) { row.set("model_sha256", std::string(64, '0')); });
    for (const std::size_t index : {0u, 2u}) {
        Work work;
        const auto& model_pin = kBody22Pins[index];
        const auto chosen = body22_views(docs, model_pin, work);
        const auto encoded = joined683_canonical(chosen.model, work);
        work.spend(encoded.size() * 8 + 256);
        json::JsonMutDoc mutation;
        auto meaning = mutation.copy_val(chosen.model);
        meaning.set("unknown_Model_field", true);
        mutation.set_root(meaning);
        const auto bytes = mutation.to_string();
        work.spend(bytes.size() * 3);
        const auto parsed = json::parse(bytes);
        ASSERT_TRUE(parsed);
        const auto changed_sha =
            loom::utils::crypto::sha256(joined683_canonical(parsed->root(), work));
        bool rejected = false;
        try {
            if (model_pin.wrap)
                static_cast<void>(wrap43_codec(parsed->root(), work));
            else
                static_cast<void>(remaining24_model(parsed->root(), changed_sha, work));
        } catch (const std::runtime_error& error) {
            if (termaid47_resource(error.what())) throw;
            rejected = std::string_view(error.what()) ==
                       (model_pin.wrap ? "Wrap43 exact object fields"
                                       : "Remaining24 exact object field count");
        }
        EXPECT_TRUE(rejected);
    }
    Work zero;
    zero.remaining = 0;
    bool resource = false;
    try {
        static_cast<void>(body22_documents(zero));
    } catch (const std::runtime_error& error) {
        resource = termaid47_resource(error.what());
    }
    EXPECT_TRUE(resource) << "Zero setup is not source/Model rejection";
}

TEST(MermaidOfficialBody22Native, EveryWholeBodyRequiresCompleteGeometryBeforeMeaningfulMutations) {
    Work setup;
    const auto docs = body22_documents(setup);
    json::JsonMutDoc report;
    auto root = report.object(), rows = root.make_arr();
    int observed = 0, decoded = 0, ready = 0, matched = 0, mutated = 0, unmet = 0, failures = 0,
        observation_errors = 0, pending = 0;
    for (std::size_t n = 0; n < kBody22Pins.size(); ++n) {
        const auto& pin = kBody22Pins[n];
        Work work;
        // Reserve diagnostic/error/counter copies before capture or decode can
        // exhaust the scene ledger. This permits every later source to remain
        // observed; it is deducted from this same8M, never a fresh allowance.
        work.spend(pin.path.size() * 4 + pin.body_sha.size() * 4 + 131072);
        SCOPED_TRACE(std::string(pin.path));
        auto row = root.make_obj();
        row.set("path", std::string(pin.path));
        row.set("track", "body_diagnostic");
        row.set("input_sha256", std::string(pin.body_sha));
        row.set("raw_context_sha256", std::string(pin.raw_sha));
        row.set("model_sha256", std::string(pin.model_sha));
        row.set("number_encoding", "DisplayText");
        row.set("profile", pin.wrap ? "source_wrap" : "fixed");
        row.add("source_note_alignment", row.make_null());
        std::string phase = "whole_body_capture_before_Model_decode";
        bool captured = false, model_decoded = false, profile_ready = false, fallback = false,
             changed = false, profile_pending = false;
        std::vector<std::string> errors, observations;
        try {
            const auto item = docs.refs.root().get("cases").at(n);
            const auto source_value = item.get("input");
            official_role38_require(source_value.is_str() && !source_value.as_str().empty() &&
                                        source_value.as_str().size() <= 65536,
                                    "Body22 public complete source cap");
            work.spend(source_value.as_str().size() * 6 + 256);
            const auto source = std::string(source_value.as_str());
            const auto node = loom::ui::render_markdown(fenced(source, "mermaid")),
                       ordinary = loom::ui::render_markdown(fenced(source, "text"));
            node->ComputeRequirement();
            ordinary->ComputeRequirement();
            const int height = std::min(1040, std::max(40, std::max(node->requirement().min_y,
                                                                    ordinary->requirement().min_y) +
                                                               12));
            work.spend(static_cast<std::size_t>(height) * (3u * 240u + 2u * 40u) * 8u + 256);
            const auto wide = capture(node, 240, height), plain = capture(ordinary, 240, height),
                       narrow = capture(node, 40, height), small = capture(ordinary, 40, height),
                       restored = capture(node, 240, height);
            captured = true;
            ++observed;
            fallback = wide == plain;
            if (wide != restored)
                observations.emplace_back("Body22 same-Node restoration changed cells");
            for (const auto* grid : {&wide, &narrow, &restored}) {
                work.spend(grid->cells.size() + 1);
                if (!complete_sequence_sentinel(*grid))
                    observations.emplace_back("Body22 complete physical sentinel missing/repeated");
            }
            row.set("wide_source_fallback", fallback);
            row.set("narrow_source_fallback", narrow == small);
            row.set("restored_identically", wide == restored);
            row.set("following_content_retained", observations.empty());
            row.set("frame_width", wide.width);
            row.set("frame_height", height);
            body22_frame_report(wide, "wide_frame", row, work);
            body22_frame_report(narrow, "narrow_frame", row, work);
            body22_frame_report(restored, "restored_frame", row, work);
            row.set("wide_frame_sha256", lifecycle_frame_hash(wide));
            row.set("narrow_frame_sha256", lifecycle_frame_hash(narrow));
            row.set("restored_frame_sha256", lifecycle_frame_hash(restored));
            phase = "same_body_source_and_whole_Model_binding";
            const auto views = body22_views(docs, pin, work);
            body22_binding(item, views.raw, views.model, pin, work);
            if (pin.kind == 2) config8ab33_binding(views.raw, docs.supplement.root(), work);
            if (!pin.wrap) {
                std::size_t copy = 0;
                const auto model = remaining24_model(views.model, pin.model_sha, work, &copy);
                model_decoded = true;
                ++decoded;
                profile_ready = true;
                ++ready;
                const auto allowance = work.remaining;
                phase = "whole_fixed_body_geometry";
                if (!fallback) {
                    const auto result = validate(wide, model, allowance);
                    first19_no_resource_rejection(result);
                    errors.insert(errors.end(), result.begin(), result.end());
                }
                if (narrow != small) {
                    const auto result = validate(narrow, model, allowance);
                    first19_no_resource_rejection(result);
                    errors.insert(errors.end(), result.begin(), result.end());
                }
                if (!fallback && errors.empty() && observations.empty()) {
                    phase = "schema_valid_fixed_body_mutations";
                    const auto result = description77_fixed_mutations(wide, model, copy);
                    work.spend((result.executed.size() + result.skipped_schema.size()) * 256 + 64);
                    errors.insert(errors.end(), result.errors.begin(), result.errors.end());
                    auto counts = row.make_obj(), skips = row.make_obj();
                    for (const auto& [key, count] : result.executed)
                        counts.set(key, count);
                    for (const auto& [key, count] : result.skipped_schema)
                        skips.set(key, count);
                    row.add("geometry_mutations_executed", counts);
                    row.add("schema_invalid_not_geometry", skips);
                    changed = result.errors.empty();
                }
            } else {
                phase = "whole_source_Label_codec_and_plan";
                const auto encoded = joined683_canonical(views.model, work);
                official_role38_require(loom::utils::crypto::sha256(encoded) == pin.model_sha,
                                        "Body22 complete Label Model digest");
                const auto scene = wrap43_codec(views.model, work);
                model_decoded = true;
                ++decoded;
                const auto plan = wrap43_plan(scene, work);
                std::vector<std::pair<int, int>> owners;
                const auto hints = wrap43_constraints(plan, owners, work);
                profile_ready = true;
                ++ready;
                const auto allowance = work.remaining;
                phase = "whole_Label_body_geometry";
                if (!fallback) {
                    const auto result = validate(wide, plan.display, allowance, &hints);
                    wrap43_no_protocol_or_resource(result);
                    errors.insert(errors.end(), result.begin(), result.end());
                }
                if (narrow != small) {
                    const auto result = validate(narrow, plan.display, allowance, &hints);
                    wrap43_no_protocol_or_resource(result);
                    errors.insert(errors.end(), result.begin(), result.end());
                }
                if (!fallback && errors.empty() && observations.empty()) {
                    phase = "schema_valid_Label_body_mutations";
                    auto result = wrap43_mutations(wide, scene);
                    Work title_work;
                    title_work.remaining = allowance;
                    const auto copy = wrap43_copy_charge(plan.display, title_work);
                    title_work.spend(copy * 4 + 64);
                    auto wrong = plan.display;
                    wrong.title = wrong.title == "Wrong" ? "Other" : "Wrong";
                    check_event_model(wrong, title_work);
                    const auto rejected = validate(wide, wrong, title_work.remaining, &hints);
                    wrap43_no_protocol_or_resource(rejected);
                    ++result.executed["visible_title"];
                    if (rejected.empty())
                        result.errors.emplace_back("Accepted Body22 Label title mutation");
                    work.spend((result.executed.size() + result.schema_skips.size() +
                                result.profile_skips.size()) *
                                   256 +
                               64);
                    errors.insert(errors.end(), result.errors.begin(), result.errors.end());
                    auto counts = row.make_obj(), skips = row.make_obj(), pending = row.make_obj();
                    for (const auto& [key, count] : result.executed)
                        counts.set(key, count);
                    for (const auto& [key, count] : result.schema_skips)
                        skips.set(key, count);
                    for (const auto& [key, count] : result.profile_skips)
                        pending.set(key, count);
                    row.add("geometry_mutations_executed", counts);
                    row.add("schema_invalid_not_geometry", skips);
                    row.add("unreviewed_profile_not_geometry", pending);
                    changed = result.errors.empty();
                }
            }
        } catch (const Wrap43ProfileUnmet& error) {
            profile_pending = true;
            ++pending;
            row.set("explicit_profile_pending", error.what());
        } catch (const std::exception& error) {
            errors.emplace_back(phase + ": " + error.what());
        }
        const bool good = captured && model_decoded && profile_ready && !fallback && changed &&
                          errors.empty() && observations.empty();
        matched += good;
        mutated += changed;
        unmet += captured && fallback;
        failures += !errors.empty();
        observation_errors += !observations.empty();
        EXPECT_TRUE(captured);
        EXPECT_TRUE(model_decoded);
        EXPECT_TRUE(profile_ready);
        EXPECT_FALSE(fallback) << "All22 whole bodies remain mandatory";
        EXPECT_TRUE(good);
        for (const auto& error : errors)
            ADD_FAILURE() << error;
        for (const auto& error : observations)
            ADD_FAILURE() << error;
        row.set("Model_decoded", model_decoded);
        row.set("profile_ready", profile_ready);
        row.set("mutations_executed", changed);
        row.set("native_match", good);
        row.set("phase", phase);
        row.set("native_outcome", !observations.empty() ? "observation_error"
                                  : !errors.empty()     ? "oracle_or_geometry_error"
                                  : profile_pending     ? "complete_source_profile_unmet"
                                  : fallback            ? "same_body_positive_unmet"
                                  : good
                                      ? "complete_body_native_geometry_original_predicates_pending"
                                      : "incomplete_body_assertion");
        auto failed = row.make_arr(), capture_failed = row.make_arr();
        for (const auto& error : errors)
            failed.append(row.make_str(error));
        for (const auto& error : observations)
            capture_failed.append(row.make_str(error));
        row.add("native_errors", failed);
        row.add("observation_errors", capture_failed);
        rows.append(row);
    }
    EXPECT_EQ(observed, 22);
    EXPECT_EQ(decoded, 22);
    EXPECT_EQ(ready, 22);
    EXPECT_EQ(matched, 22);
    EXPECT_EQ(mutated, 22);
    EXPECT_EQ(unmet, 0);
    EXPECT_EQ(failures, 0);
    EXPECT_EQ(observation_errors, 0);
    EXPECT_EQ(pending, 0);
    root.set("source_facts_sha256", std::string(kBody22Sha));
    root.set("independent_source_review_sha256", std::string(kBody22SourceReview));
    root.set("whole_sources", 22);
    root.set("public_sources_observed", observed);
    root.set("models_decoded", decoded);
    root.set("profile_ready", ready);
    root.set("whole_body_geometry_matches", matched);
    root.set("sources_with_meaningful_mutations", mutated);
    root.set("source_positive_unmet", unmet);
    root.set("oracle_geometry_errors", failures);
    root.set("observation_errors", observation_errors);
    root.set("complete_source_profiles_pending", pending);
    root.set("original_predicates_certified", 0);
    root.set("qualification",
             "Same-body full native projection only. No raw geometry credit, original "
             "API/SVG/browser/ASCII graduation, snapshot or policy admission.");
    root.add("cases", rows);
    report.set_root(root);
#ifdef LOOM_MERMAID_REPORT_DIR
    std::filesystem::create_directories(LOOM_MERMAID_REPORT_DIR);
    std::ofstream output(std::filesystem::path(LOOM_MERMAID_REPORT_DIR) /
                             "mermaid-official-body22-native.json",
                         std::ios::binary);
    ASSERT_TRUE(output && (output << report.to_pretty_string() << '\n'));
#endif
}
